INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指效果和利益，通常用于衡量投入与产出的结果。", "primary_collocate": null, "pronunciation": "xiào yì", "ipa": "ɕiɑʊ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "效益", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个项目的效益很好。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想办法提高效益。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的效益一年比一年好。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做的效益太低，不值得。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投入这么多钱，效益却很小。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理很关心新店的效益。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业只有讲究效益，才能活下去。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条生产线的效益不如以前。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民说，种这种菜效益高。", "target_word": "效益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济效益", "label": "复合"}, {"form": "社会效益", "label": "复合"}], "register": "书面语", "sense_fingerprint": "衡量投入与产出的效果和利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效益", "is_correct": true, "explanation": "正确答案。效益指效果和利益，读作第四声 xiào yì。"}, {"text": "校医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，校医指学校里的医生。"}, {"text": "教义", "is_correct": false, "explanation": "jiào 与 xiào 声母不同，教义指宗教的基本道理。"}, {"text": "教益", "is_correct": false, "explanation": "jiào 与 xiào 声母不同，教益指从教导中得到的益处。"}], "explanations": {"效益": "正确答案。效益指效果和利益，读作第四声 xiào yì。", "校医": "yī（第一声）与 yì（第四声）声调不同，校医指学校里的医生。", "教义": "jiào 与 xiào 声母不同，教义指宗教的基本道理。", "教益": "jiào 与 xiào 声母不同，教益指从教导中得到的益处。"}, "sentence_index": null, "correct_answer": "效益"}, "level_3": {"options": [{"text": "效益", "is_correct": true, "explanation": "正确。效益指投入与产出带来的利益，正是可以被证券化的对象。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不是可以证券化的外部性收益，与“碳汇”“能源节约”无关。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：“证券化”不能用于色彩，色彩也不是收益。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育活动不能被当作证券化的收益，与“投资”“回报”不合。"}], "explanations": {"效益": "正确。效益指投入与产出带来的利益，正是可以被证券化的对象。", "人口": "语义：人口不是可以证券化的外部性收益，与“碳汇”“能源节约”无关。", "色彩": "搭配：“证券化”不能用于色彩，色彩也不是收益。", "体育": "语义：体育活动不能被当作证券化的收益，与“投资”“回报”不合。"}, "sentence_index": 0, "correct_answer": "效益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的效益很便宜，一盒只要五块钱。", "explanation": "这里应该用〈价格〉。效益指效果和利益，不能说便宜，药的贵贱要用价格。"}, {"text": "这位同学的效益很快，一小时能做完十道题。", "explanation": "这里应该用〈速度〉。效益指效果和利益，人做事的快慢要用速度。"}, {"text": "他这次数学效益进步了二十分。", "explanation": "这里应该用〈成绩〉。效益指做事得到的利益，考试的结果要用成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "效益", "is_correct": true, "explanation": "正确。经理关心的是店铺的经营收益。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：店铺没有身高，“身高”只能用来描述人或生物的外形。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：店铺没有脾气，不能被经理关心脾气。"}, {"text": "声调", "is_correct": false, "explanation": "语义：新店没有声调，声调是语言的音高特征，与经营无关。"}], "explanations": {"效益": "正确。经理关心的是店铺的经营收益。", "身高": "体貌：店铺没有身高，“身高”只能用来描述人或生物的外形。", "脾气": "语义：店铺没有脾气，不能被经理关心脾气。", "声调": "语义：新店没有声调，声调是语言的音高特征，与经营无关。"}, "sentence_index": 6, "correct_answer": "效益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的效益很漂亮，大家都喜欢它的样子。", "explanation": "这里应该用〈外观〉。效益指效果和利益，不能形容漂亮，机器好不好看要用外观。"}, {"text": "他的汉语效益提高了很多。", "explanation": "这里应该用〈水平〉。效益指利益，语言的掌握程度要用水平。"}, {"text": "这把椅子的效益很长。", "explanation": "这里应该用〈寿命〉。效益表示利益的大小，不能说长短，东西能用多久要用寿命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂的一台效益很高。", "corrected_sentence": "这家工厂的效益很高。", "error_description": "量词误用：“台”多用于机器、设备，不能计量抽象的“效益”；应直接说“效益很高”。错误在“一台”，“很高”没有问题。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法的效益大很。", "corrected_sentence": "这个办法的效益很大。", "error_description": "语序错误：程度副词“很”应放在形容词之前，应说“效益很大”，不能说“效益大很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将原本不能直接买卖的资产或未来收入，通过金融手段变成可以在市场上交易的证券。", "primary_collocate": null, "pronunciation": "zhèng quàn huà", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛn˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "证券化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "银行把房贷证券化，再卖给投资者。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想把未来的租金证券化。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房贷证券化以后，投资者可以在市场上买卖。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司证券化了应收账款，很快拿到了资金。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算把高速公路的收费权证券化。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过证券化，这些贷款变成了可以交易的债券。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行为什么要把贷款证券化？", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐版税也可以证券化，歌手能提前拿到钱。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提醒说，贷款证券化太多会带来风险。", "target_word": "证券化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "证券化了", "label": "体标"}, {"form": "资产证券化", "label": "复合"}, {"form": "證券化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "证券化：把资产或未来收入通过金融手段变成可交易的证券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "证券化", "is_correct": true, "explanation": "证券化：把外部性效益变成可交易的证券，与前句「新型金融工具」和后句「量化回报路径」相符。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是毁掉，与「开辟可持续投资的量化回报路径」的意思相反。"}, {"text": "遗忘", "is_correct": false, "explanation": "搭配：遗忘用于记忆、经历，不能带「外部性效益」这类宾语。"}, {"text": "搬迁", "is_correct": false, "explanation": "配价：搬迁需要具体的物体或处所，「外部性效益」是抽象的，无法搬迁。"}], "explanations": {"证券化": "证券化：把外部性效益变成可交易的证券，与前句「新型金融工具」和后句「量化回报路径」相符。", "销毁": "语义：销毁是毁掉，与「开辟可持续投资的量化回报路径」的意思相反。", "遗忘": "搭配：遗忘用于记忆、经历，不能带「外部性效益」这类宾语。", "搬迁": "配价：搬迁需要具体的物体或处所，「外部性效益」是抽象的，无法搬迁。"}, "sentence_index": 0, "correct_answer": "证券化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司计划明年把它的笑声证券化。", "explanation": "这里应该用〈录制〉。证券化指把资产或未来收入变成可交易的证券，笑声不是资产；把声音录下来要说“录制”。"}, {"text": "这家银行证券化了一种新债券。", "explanation": "这里应该用〈发行〉。债券本身已经是可以买卖的证券，证券化针对的是原本不能买卖的资产，不能再说「证券化一种债券」。"}, {"text": "他把股票证券化，买了一套房子。", "explanation": "这里应该用〈变现〉。股票本来就能在市场上买卖，不需要证券化；这句话说的是把股票换成现金，应该用「变现」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证券化", "is_correct": true, "explanation": "证券化：把贷款变成可以交易的债券，与后半句「变成了可以交易的债券」相符。"}, {"text": "抵押", "is_correct": false, "explanation": "语义：抵押是把财产作为担保，不会让贷款直接变成可以交易的债券。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝是不接受，与「变成了可以交易的债券」的结果相反。"}, {"text": "粉碎", "is_correct": false, "explanation": "搭配：粉碎搭配的是实物或希望，不搭配贷款，也不会得到债券。"}], "explanations": {"证券化": "证券化：把贷款变成可以交易的债券，与后半句「变成了可以交易的债券」相符。", "抵押": "语义：抵押是把财产作为担保，不会让贷款直接变成可以交易的债券。", "拒绝": "语义：拒绝是不接受，与「变成了可以交易的债券」的结果相反。", "粉碎": "搭配：粉碎搭配的是实物或希望，不搭配贷款，也不会得到债券。"}, "sentence_index": 6, "correct_answer": "证券化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这笔借款证券化，给了侄子。", "explanation": "这里应该用〈赠与〉。证券化是把资产变成可买卖的证券，不表示把东西送给别人；无偿送人应说「赠与」。"}, {"text": "评估师认定这套房子证券化了，价值三百万元。", "explanation": "这里应该用〈估值〉。证券化是把资产变成可买卖的证券，不表示判定资产价值；为房子评定价格应说「估值」。"}, {"text": "这只基金被证券化为低风险。", "explanation": "这里应该用〈评为〉。证券化指把资产变成可交易的证券，不用来描述风险等级，风险高低要用「评为」来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "银行已经房贷证券化了。", "corrected_sentence": "银行已经把房贷证券化了。", "error_description": "「把」字句漏了「把」：「房贷」是「证券化」的宾语，应提到动词前，说「把房贷证券化了」，不能直接说「房贷证券化了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把一笔贷款证券化债券。", "corrected_sentence": "他们把一笔贷款证券化为债券。", "error_description": "漏了「为」：「证券化」后面要接「为」表示结果，应说「证券化为债券」，不能直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
