INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打开通路；开创、发展新的事物。", "primary_collocate": null, "pronunciation": "kāi pì", "ipa": "kʰaɪ˥ pʰi˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "开辟", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司在国外开辟了新的市场。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家为医学研究开辟了新方向。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划为年轻人开辟了一条新路。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要开辟更多的销售渠道。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想开辟自己的事业。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网给学习开辟了新天地。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行开辟过一个新业务。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定开辟一个新的合作领域。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠旅游开辟了新的财源。", "target_word": "开辟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开辟了", "label": "体标"}, {"form": "开辟过", "label": "体标"}, {"form": "开辟着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "开创新的领域、市场、道路等抽象事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“路径”搭配，“吃了可持续投资的量化回报路径”不成立。"}, {"text": "开辟", "is_correct": true, "explanation": "“开辟”指开创新的领域或路径，与“可持续投资的量化回报路径”搭配，句意通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用于开创路径，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能与“路径”搭配，“煮了量化回报路径”无法成立。"}], "explanations": {"吃": "搭配：“吃”不能与“路径”搭配，“吃了可持续投资的量化回报路径”不成立。", "开辟": "“开辟”指开创新的领域或路径，与“可持续投资的量化回报路径”搭配，句意通顺。", "唱": "语义：“唱”不能用于开创路径，句子说不通。", "煮": "搭配：“煮”不能与“路径”搭配，“煮了量化回报路径”无法成立。"}, "sentence_index": 0, "correct_answer": "开辟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的电话已经开辟了。", "explanation": "这里应该用〈开通〉。开辟指开创新的道路或领域；电话、网络开始提供服务要用“开通”。"}, {"text": "他开辟了一家新公司。", "explanation": "这里应该用〈创办〉。开辟指开创新的道路或领域，成立公司这类机构要用“创办”，不能用“开辟”。"}, {"text": "我们开辟了一次调查。", "explanation": "这里应该用〈开展〉。开辟用于开创道路或领域，不能和“调查”这类活动搭配；进行调查要说“开展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光消失，不能用于开创新天地，“熄灭了新天地”不成立。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”只能用于有破损的东西，不能与“新天地”搭配。"}, {"text": "开辟", "is_correct": true, "explanation": "“开辟新天地”指开创新的领域，“互联网给学习”是其主体，句意通顺。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指使物体破裂，不能用于抽象的“新天地”。"}], "explanations": {"熄灭": "语义：“熄灭”指火或光消失，不能用于开创新天地，“熄灭了新天地”不成立。", "缝补": "搭配：“缝补”只能用于有破损的东西，不能与“新天地”搭配。", "开辟": "“开辟新天地”指开创新的领域，“互联网给学习”是其主体，句意通顺。", "打碎": "语义：“打碎”指使物体破裂，不能用于抽象的“新天地”。"}, "sentence_index": 6, "correct_answer": "开辟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我开辟了一瓶汽水，马上喝了起来。", "explanation": "这里应该用〈打开〉。开辟指开创新的领域或道路，瓶子开盖要用“打开”。"}, {"text": "学校开辟了一场比赛。", "explanation": "这里应该用〈举办〉。开辟不能与“比赛”这类活动搭配；办比赛要用“举办”。"}, {"text": "他开辟了一篇论文。", "explanation": "这里应该用〈发表〉。开辟指开创道路或领域，不能用于论文的公开；论文公开要用“发表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们明年要开辟了新市场。", "corrected_sentence": "他们明年要开辟新市场。", "error_description": "“了”误用：“明年”和“要”表示将来，“开辟了”表示已经完成，二者冲突；应去掉“了”，说“明年要开辟新市场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们靠卖茶开辟得新财源。", "corrected_sentence": "他们靠卖茶开辟了新财源。", "error_description": "助词误用：“开辟”后接“得”引出补语，但这里说的是已完成的动作，应用“了”；应说“开辟了新财源”，把“得”改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
