INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12708, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对别人的帮助或恩情加以报答。", "primary_collocate": null, "pronunciation": "huí bào", "ipa": "xwei˧˥ pau˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，让受益的居民以资金与参与来回报社区。", "target_word": "回报", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他一直想回报老师的帮助。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会用行动回报你的信任。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她努力工作来回报父母的养育之恩。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感谢大家的支持，我们一定好好回报。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人曾经帮过我，我要回报他。", "target_word": "回报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会给了他很多，他决心回报社会。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮了我，我该怎么回报你呢？", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用优异的成绩回报了老师的关心。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "企业有责任回报当地居民的支持。", "target_word": "回报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回报了", "label": "体标"}, {"form": "回报过", "label": "体标"}], "register": "书面", "sense_fingerprint": "报答别人的帮助或恩情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回报", "is_correct": true, "explanation": "回报 huí bào：报答别人的帮助或恩情，是本词。"}, {"text": "汇报", "is_correct": false, "explanation": "汇报 huì bào：第一音节声调不同（第四声与第二声），意思是向上级报告情况。"}, {"text": "回到", "is_correct": false, "explanation": "回到 huí dào：声母由 b 变为 d，意思是返回到某处。"}, {"text": "怀抱", "is_correct": false, "explanation": "怀抱 huái bào：第一音节韵母由 ui 变为 uai，意思是胸怀或拥抱。"}], "explanations": {"回报": "回报 huí bào：报答别人的帮助或恩情，是本词。", "汇报": "汇报 huì bào：第一音节声调不同（第四声与第二声），意思是向上级报告情况。", "回到": "回到 huí dào：声母由 b 变为 d，意思是返回到某处。", "怀抱": "怀抱 huái bào：第一音节韵母由 ui 变为 uai，意思是胸怀或拥抱。"}, "sentence_index": null, "correct_answer": "回报"}, "level_3": {"options": [{"text": "回报", "is_correct": true, "explanation": "正确：“回报社区”指以资金与参与报答社区，与“受益的居民”的感恩语境相合。"}, {"text": "报应", "is_correct": false, "explanation": "语义：“报应”是名词，指因果报应，不能作动词报答社区。"}, {"text": "报表", "is_correct": false, "explanation": "搭配：“报表”是文件，不能用来报答社区。"}, {"text": "报销", "is_correct": false, "explanation": "语义：“报销”指凭单据请求偿还费用，不能用来报答社区。"}], "explanations": {"回报": "正确：“回报社区”指以资金与参与报答社区，与“受益的居民”的感恩语境相合。", "报应": "语义：“报应”是名词，指因果报应，不能作动词报答社区。", "报表": "搭配：“报表”是文件，不能用来报答社区。", "报销": "语义：“报销”指凭单据请求偿还费用，不能用来报答社区。"}, "sentence_index": 0, "correct_answer": "回报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快回报了朋友的来信。", "explanation": "这里应该用〈回复〉。回报指报答恩情，回复指答复来信或问题。"}, {"text": "老人常常回报童年的生活。", "explanation": "这里应该用〈回忆〉。回报指报答别人的恩情，想起过去的事情要用回忆。"}, {"text": "他对我的问题做出了回报。", "explanation": "这里应该用〈回应〉。回报指报答恩情，回应指对问题或呼唤作出反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回报", "is_correct": true, "explanation": "回报 huí bào：报答别人的帮助或恩情，是本词。"}, {"text": "回拨", "is_correct": false, "explanation": "回拨 huí bō：韵母由 ao 变为 o，声调也不同，意思是回拨款项或拨回。"}, {"text": "回拜", "is_correct": false, "explanation": "回拜 huí bài：韵母由 ao 变为 ai，意思是回访。"}, {"text": "回驳", "is_correct": false, "explanation": "回驳 huí bó：韵母由 ao 变为 o，声调也不同，意思是反驳。"}], "explanations": {"回报": "回报 huí bào：报答别人的帮助或恩情，是本词。", "回拨": "回拨 huí bō：韵母由 ao 变为 o，声调也不同，意思是回拨款项或拨回。", "回拜": "回拜 huí bài：韵母由 ao 变为 ai，意思是回访。", "回驳": "回驳 huí bó：韵母由 ao 变为 o，声调也不同，意思是反驳。"}, "sentence_index": null, "correct_answer": "回报"}, "level_3": {"options": [{"text": "回报", "is_correct": true, "explanation": "正确：此处“回报”指报答社会的恩情，与前句“社会给了他很多”相合。"}, {"text": "攻击", "is_correct": false, "explanation": "语义：“攻击社会”与“社会给了他很多”的语境相反，不合情理。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”的对象是车辆或船只，不能用于“社会”。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负”指没有达到期望，与“社会给了他很多”的感恩语境相反。"}], "explanations": {"回报": "正确：此处“回报”指报答社会的恩情，与前句“社会给了他很多”相合。", "攻击": "语义：“攻击社会”与“社会给了他很多”的语境相反，不合情理。", "停靠": "搭配：“停靠”的对象是车辆或船只，不能用于“社会”。", "辜负": "语义：“辜负”指没有达到期望，与“社会给了他很多”的感恩语境相反。"}, "sentence_index": 6, "correct_answer": "回报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我收到了老师的来信，马上回报了一封。", "explanation": "这里应该用〈回信〉。回报指报答恩情，写信回复来信要用回信。"}, {"text": "面对这个难题，他总是回报，从不正面讨论。", "explanation": "这里应该用〈回避〉。回报指报答恩情，躲开问题、不正面面对要用回避。"}, {"text": "他走了几步，又突然回报看了一眼。", "explanation": "这里应该用〈回头〉。回报指报答恩情，转过脸来看要用回头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v