INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想用行动回报了老师的教导。", "corrected_sentence": "我想用行动回报老师的教导。", "error_description": "“了”位置错误：“想”表示意愿，后面的动词不能带“了”，应说“想用行动回报老师的教导”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经回报过过我的帮助。", "corrected_sentence": "他曾经回报过我的帮助。", "error_description": "“过”重复错误：一个动词后只能带一个动态助词“过”，应说“回报过我的帮助”，不能说“回报过过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪恶", "is_correct": true, "explanation": "反义：“正义”指符合道德与公平，“邪恶”指道德上极其恶劣，二者相反。"}, {"text": "距离", "is_correct": false, "explanation": "不是反义：“距离”指空间或时间的间隔，与道德概念无关。"}, {"text": "天气", "is_correct": false, "explanation": "不是反义：“天气”指大气状况，与“正义”的道德含义无关。"}, {"text": "面包", "is_correct": false, "explanation": "不是反义：“面包”是食物，与“正义”的道德含义无关。"}], "correct_answer": "邪恶", "explanations": {"邪恶": "反义：“正义”指符合道德与公平，“邪恶”指道德上极其恶劣，二者相反。", "距离": "不是反义：“距离”指空间或时间的间隔，与道德概念无关。", "天气": "不是反义：“天气”指大气状况，与“正义”的道德含义无关。", "面包": "不是反义：“面包”是食物，与“正义”的道德含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪恶", "is_correct": true, "explanation": "反义：“正义”指符合道德与公平，“邪恶”指道德上极其恶劣，二者相反。"}, {"text": "河流", "is_correct": false, "explanation": "不是反义：“河流”指地表的水流，与道德概念无关。"}, {"text": "桌子", "is_correct": false, "explanation": "不是反义：“桌子”是家具，与“正义”的道德含义无关。"}, {"text": "季节", "is_correct": false, "explanation": "不是反义：“季节”指一年中气候的分段，与“正义”无关。"}], "correct_answer": "邪恶", "explanations": {"邪恶": "反义：“正义”指符合道德与公平，“邪恶”指道德上极其恶劣，二者相反。", "河流": "不是反义：“河流”指地表的水流，与道德概念无关。", "桌子": "不是反义：“桌子”是家具，与“正义”的道德含义无关。", "季节": "不是反义：“季节”指一年中气候的分段，与“正义”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指符合道德、公平、公正的道理或行为。", "primary_collocate": null, "pronunciation": "zhèng yì", "ipa": "ʈʂɤŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "更深远的影响在于空间正义的再议程化。", "target_word": "正义", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "法官的责任是维护社会正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了正义，放弃了高薪工作。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正义也许会迟到，但不会缺席。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是正义战胜邪恶的故事。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们从小就要学会分辨正义和邪恶。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院的判决让大家看到了正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该为弱者伸张正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会正义需要每个人的努力。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直相信正义终会实现。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正义感", "label": "复合词"}, {"form": "正義", "label": "繁体"}], "register": "书面", "sense_fingerprint": "符合道德与公平的道理或行为（社会、法律层面的正义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确答案：正义（zhèng yì），指符合道德与公平的道理或行为。"}, {"text": "争议", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。"}, {"text": "正式", "is_correct": false, "explanation": "shì 与 yì 的声母不同，意思是正规、符合规定。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 yì 的声母不同，意思是政府管理国家的活动。"}], "explanations": {"正义": "正确答案：正义（zhèng yì），指符合道德与公平的道理或行为。", "争议": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。", "正式": "shì 与 yì 的声母不同，意思是正规、符合规定。", "政治": "zhì 与 yì 的声母不同，意思是政府管理国家的活动。"}, "sentence_index": null, "correct_answer": "正义"}, "level_3": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确：“空间正义”是句中的术语，指空间资源分配中的公平，与“再议程化”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“空间价格”说不通，句子讨论的是公平问题，与价格无关。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”不能与“空间”组合成可被“再议程化”的对象。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“空间工资”不成立，与句子讨论的空间分配无关。"}], "explanations": {"正义": "正确：“空间正义”是句中的术语，指空间资源分配中的公平，与“再议程化”相符。", "价格": "语义：“空间价格”说不通，句子讨论的是公平问题，与价格无关。", "热情": "搭配：“热情”不能与“空间”组合成可被“再议程化”的对象。", "工资": "语义：“空间工资”不成立，与句子讨论的空间分配无关。"}, "sentence_index": 0, "correct_answer": "正义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是他的正义，每天都要去上班。", "explanation": "这里应该用〈工作〉。正义指符合道德与公平的道理，不能说“每天去上班”。"}, {"text": "他对工作充满正义，每天都很努力。", "explanation": "这里应该用〈热情〉。“充满热情”是常用搭配；正义指符合道德、公平的道理或行为，不能用来描述对工作的情绪。"}, {"text": "他的正义很明确，就是成为一名医生。", "explanation": "这里应该用〈目标〉。“目标很明确”说的是想达到的目的；正义指符合道德、公平的道理或行为，不能说它明确与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确答案：正义（zhèng yì），指符合道德与公平的道理或行为。"}, {"text": "真意", "is_correct": false, "explanation": "zhēn（第一声）与 zhèng 的韵母不同（-n 与 -ng），意思是真实的意思。"}, {"text": "增益", "is_correct": false, "explanation": "zēng 与 zhèng 的声母不同（z 与 zh），意思是增加、益处。"}, {"text": "诚意", "is_correct": false, "explanation": "chéng 与 zhèng 的声母不同（ch 与 zh），意思是真诚的心意。"}], "explanations": {"正义": "正确答案：正义（zhèng yì），指符合道德与公平的道理或行为。", "真意": "zhēn（第一声）与 zhèng 的韵母不同（-n 与 -ng），意思是真实的意思。", "增益": "zēng 与 zhèng 的声母不同（z 与 zh），意思是增加、益处。", "诚意": "chéng 与 zhèng 的声母不同（ch 与 zh），意思是真诚的心意。"}, "sentence_index": null, "correct_answer": "正义"}, "level_3": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确：“看到了正义”指判决让人认识到公平的存在，符合句意。"}, {"text": "利润", "is_correct": false, "explanation": "语义：判决不能让人“看到”利润，与句中的法律语境不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：判决不能让人“看到”闹钟，与法律语境无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“看到”不能与“体温”搭配出判决让大家看到的内容。"}], "explanations": {"正义": "正确：“看到了正义”指判决让人认识到公平的存在，符合句意。", "利润": "语义：判决不能让人“看到”利润，与句中的法律语境不符。", "闹钟": "语义：判决不能让人“看到”闹钟，与法律语境无关。", "体温": "搭配：“看到”不能与“体温”搭配出判决让大家看到的内容。"}, "sentence_index": 6, "correct_answer": "正义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一直认为这道题的答案很正义。", "explanation": "这里应该用〈正确〉。正义指道德上的公平，不能用来评价答案的对错。"}, {"text": "这套方案的分工很正义。", "explanation": "这里应该用〈公平〉。正义指符合道德的道理或行为，多用于社会、法律层面；评价分工是否均衡应该用“公平”。"}, {"text": "她的正义很远大，想去当科学家。", "explanation": "这里应该用〈理想〉。正义指道理，不指个人志向的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的做法体现了一个正义。", "corrected_sentence": "他的做法体现了一种正义。", "error_description": "“正义”前的量词应用“种”，不能用“个”。“一个正义”不符合汉语习惯，抽象概念通常用“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们是正义们的代表。", "corrected_sentence": "他们是正义的代表。", "error_description": "错误：“正义”是抽象名词，前面不能加“们”表示复数。正确：“正义的代表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
