INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12710, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分配模式指资源或任务在多个个体或部分之间进行分配的方式或规则。", "primary_collocate": null, "pronunciation": "fēn pèi mó shì", "ipa": "fən˥ pʰeɪ˥˩ mwɔ˧˥ ʂɨ˥˩", "syllable_count": 4, "sentences": [{"text": "当绿色空间与本地化食品生产成为稀缺资源时，其分配模式直接关联社会分层。", "target_word": "分配模式", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的利润分配模式很公平。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的分配模式让每个村民都得到了土地。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家比较了两国不同的收入分配模式。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校改变了奖学金的分配模式，申请的学生更多。", "target_word": "分配模式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种分配模式对小企业不太有利。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水资源的分配模式要考虑农民和城市居民的需要。", "target_word": "分配模式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学课上，老师讲了几种常见的分配模式。", "target_word": "分配模式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭里的家务分配模式，也会影响夫妻关系。", "target_word": "分配模式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在研究一种更合理的分配模式。", "target_word": "分配模式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种分配模式", "label": "量词"}], "register": "书面", "sense_fingerprint": "分配模式：资源或任务在各部分之间分配的方式或规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b22c96-2fa8-472e-a1bf-893e911faf7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分配模式", "is_correct": true, "explanation": "正确。“其分配模式直接关联社会分层”中，“分配模式”指资源分配的方式和规则。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：资源的色彩与社会分层没有直接关联，不能说“其色彩直接关联社会分层”。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：节拍是音乐或运动的节奏，与资源和社会分层无关。"}, {"text": "嗓门", "is_correct": false, "explanation": "语义：嗓门指人说话的声音大小，资源没有嗓门，不能说“其嗓门直接关联社会分层”。"}], "explanations": {"分配模式": "正确。“其分配模式直接关联社会分层”中，“分配模式”指资源分配的方式和规则。", "色彩": "语义：资源的色彩与社会分层没有直接关联，不能说“其色彩直接关联社会分层”。", "节拍": "语义：节拍是音乐或运动的节奏，与资源和社会分层无关。", "嗓门": "语义：嗓门指人说话的声音大小，资源没有嗓门，不能说“其嗓门直接关联社会分层”。"}, "sentence_index": 0, "correct_answer": "分配模式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋米的分配模式很重，我一个人搬不动。", "explanation": "这里应该用〈重量〉。分配模式指分配资源或任务的规则，说米袋有多重要用重量。"}, {"text": "这台电视的分配模式很清楚，画面很好。", "explanation": "这里应该用〈清晰度〉。分配模式指分配资源或任务的规则，与画面的清楚程度无关，要用清晰度。"}, {"text": "他每天吃分配模式，所以很饱。", "explanation": "这里应该用〈饭〉。分配模式指分配资源或任务的规则，不能吃，每天吃的要用饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分配模式", "is_correct": true, "explanation": "正确。水资源的分配模式需要考虑农民和城市居民的需要。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：水资源没有年龄，不能说“水资源的年龄要考虑农民的需要”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：水资源没有身高，“身高”只用来描述人的高矮。"}, {"text": "音调", "is_correct": false, "explanation": "语义：水资源没有音调，音调与资源分配和居民需要无关。"}], "explanations": {"分配模式": "正确。水资源的分配模式需要考虑农民和城市居民的需要。", "年龄": "语义：水资源没有年龄，不能说“水资源的年龄要考虑农民的需要”。", "身高": "语义：水资源没有身高，“身高”只用来描述人的高矮。", "音调": "语义：水资源没有音调，音调与资源分配和居民需要无关。"}, "sentence_index": 6, "correct_answer": "分配模式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面的分配模式很香。", "explanation": "这里应该用〈味道〉。分配模式是分配资源或任务的规则，不能用来说闻起来香，应说味道。"}, {"text": "他的分配模式有一米七，很高。", "explanation": "这里应该用〈身高〉。分配模式是抽象的规则，没有身高，说人的高矮要用身高。"}, {"text": "这首歌的分配模式很动听。", "explanation": "这里应该用〈旋律〉。分配模式不能用来说歌曲动听，应说旋律动听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校确定了一场新的分配模式。", "corrected_sentence": "学校确定了一种新的分配模式。", "error_description": "量词用错。“场”多用于比赛、雨等，分配模式是抽象的规则，应说“一种分配模式”，不能说“一场分配模式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府制定了一朵更合理的分配模式。", "corrected_sentence": "政府制定了一种更合理的分配模式。", "error_description": "量词误用：“朵”多用于花、云等，分配模式是抽象的规则，应说“一种”，不能说“一朵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc7a9b2e-d686-4fd8-9991-0a1daa120f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
