INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指得到或拥有某种权利、利益、名誉等。", "primary_collocate": null, "pronunciation": "xiǎng yǒu", "ipa": "ɕjɑŋ˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "享有", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个公民都享有受教育的权利。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家在国内外享有很高的名誉。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人依法享有带薪休假。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿童享有受到保护的权利。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店在本地享有很好的名声。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客在这里享有同样的待遇。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工享有公司提供的医疗保险。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他享有这套房子的使用权。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员享有购物打折的优惠。", "target_word": "享有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "享有了", "label": "体标"}, {"form": "享有着", "label": "体标"}, {"form": "享有过", "label": "体标"}], "register": "书面", "sense_fingerprint": "得到并拥有权利、利益、名誉等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "享有", "is_correct": true, "explanation": "正确：“享有”指得到或拥有权利、利益，与“同样享有技术赋能的农业设施”相符。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”与前半句“确保”的意思矛盾。"}, {"text": "抵制", "is_correct": false, "explanation": "语义：“抵制”表示拒绝，与“确保……同样”的意思矛盾。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”后接责任、费用，不接“设施与绿地”这类所有物。"}], "explanations": {"享有": "正确：“享有”指得到或拥有权利、利益，与“同样享有技术赋能的农业设施”相符。", "失去": "语义：“失去”与前半句“确保”的意思矛盾。", "抵制": "语义：“抵制”表示拒绝，与“确保……同样”的意思矛盾。", "承担": "搭配：“承担”后接责任、费用，不接“设施与绿地”这类所有物。"}, "sentence_index": 0, "correct_answer": "享有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他享有一辆新自行车。", "explanation": "这里应该用〈拥有〉。享有多指得到权利、利益或声誉，拥有可用于具体的东西。"}, {"text": "他享有很多坏习惯。", "explanation": "这里应该用〈有〉。享有只用于权利、利益、名誉等好的方面，不能用于坏习惯。"}, {"text": "这台机器享有很强的功能。", "explanation": "这里应该用〈具有〉。享有指得到权利或利益，不用于机器本身的属性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "享有", "is_correct": true, "explanation": "正确：“享有”指得到同样的待遇，与“外国游客在这里”相符。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”的对象是衣物等具体物品，不能用于“待遇”。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶、头发等，不能用于“待遇”。"}, {"text": "发放", "is_correct": false, "explanation": "搭配：“发放”的施事一般是机构，不能以“外国游客”作主语。"}], "explanations": {"享有": "正确：“享有”指得到同样的待遇，与“外国游客在这里”相符。", "缝补": "搭配：“缝补”的对象是衣物等具体物品，不能用于“待遇”。", "修剪": "搭配：“修剪”的对象是枝叶、头发等，不能用于“待遇”。", "发放": "搭配：“发放”的施事一般是机构，不能以“外国游客”作主语。"}, "sentence_index": 6, "correct_answer": "享有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他享有很多责任，压力很大。", "explanation": "这里应该用〈承担〉。享有指得到权利或利益，责任要用承担。"}, {"text": "他这次享有好成绩，老师很高兴。", "explanation": "这里应该用〈取得〉。享有指得到权利、利益、声誉，成绩要用取得。"}, {"text": "他的孩子享有一场考试，很快就结束了。", "explanation": "这里应该用〈参加〉。享有指得到权利或利益，参加考试要用“参加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "职工享有把带薪年假。", "corrected_sentence": "职工享有带薪年假。", "error_description": "错误：“享有把带薪年假”。正确：“享有带薪年假”。“享有”是非处置动词，其宾语前不能加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们被享有免费的午餐。", "corrected_sentence": "学生们享有免费的午餐。", "error_description": "错误：“被享有”。正确：“享有”。“享有”不能用于被动结构“被……享有”，应直接作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
