INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12721, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家对其领土和事务拥有的最高权力。", "primary_collocate": null, "pronunciation": "zhǔ quán", "ipa": "ʈʂu˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "每个国家都有自己的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛属于我国，我们必须维护主权。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Zhè gè dǎo shǔyú wǒguó, wǒmen bìxū wéihù zhǔquán.", "sentence_source": "generated"}, {"text": "两国领导人谈到了这块土地的主权。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Liǎng guó lǐngdǎorén tándào le zhè kuài tǔdì de zhǔquán.", "sentence_source": "generated"}, {"text": "别的国家不能随便侵犯我国的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的主权受到了尊重。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家的主权包括领土和外交。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府说，会坚决保卫这个国家的主权。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Zhèngfǔ shuō, huì jiānjué bǎowèi zhège guójiā de zhǔquán.", "sentence_source": "generated"}, {"text": "这片海属于哪国，关系到我国的主权。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Zhè piàn hǎi shǔyú nǎ guó, guānxì dào wǒguó de zhǔquán.", "sentence_source": "generated"}, {"text": "联合国承认这个国家拥有主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了主权的意思。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主权国家", "label": "复合"}, {"form": "国家主权", "label": "复合"}, {"form": "主權", "label": "繁体"}], "register": "正式", "sense_fingerprint": "主权：国家对领土和事务的最高权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主权", "is_correct": true, "explanation": "正确：“每个国家都有自己的主权”中，「主权」指国家的最高权力，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：国家不能说“自己的身高”，身高是人或物的体貌特征。"}, {"text": "心情", "is_correct": false, "explanation": "语义：国家没有心情，“每个国家都有自己的心情”说不通。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：国家没有饭量，“每个国家都有自己的饭量”不成立。"}], "explanations": {"主权": "正确：“每个国家都有自己的主权”中，「主权」指国家的最高权力，符合语境。", "身高": "体貌：国家不能说“自己的身高”，身高是人或物的体貌特征。", "心情": "语义：国家没有心情，“每个国家都有自己的心情”说不通。", "饭量": "语义：国家没有饭量，“每个国家都有自己的饭量”不成立。"}, "sentence_index": 0, "correct_answer": "主权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个人都有受教育的主权。", "explanation": "这里应该用〈权利〉。主权是国家对领土和事务的最高权力，个人受教育的权利要说权利。"}, {"text": "这个岛是我们的主权。", "explanation": "这里应该用〈领土〉。领土指疆域本身，主权是国家对它的最高权力，不能直接说“这个岛是主权”。"}, {"text": "这家公司的主权属于大股东。", "explanation": "这里应该用〈所有权〉。主权指国家对领土和事务的最高权力，公司财产的归属要说所有权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主权", "is_correct": true, "explanation": "正确：“保卫这个国家的主权”是固定搭配，「主权」是唯一符合语境的词。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：保卫的对象是国家的权益，不能是早饭，“保卫这个国家的早饭”说不通。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“保卫”不与“发型”搭配，不能说“保卫这个国家的发型”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：国家没有体重，体重是人或物的体貌特征，不能用于国家。"}], "explanations": {"主权": "正确：“保卫这个国家的主权”是固定搭配，「主权」是唯一符合语境的词。", "早饭": "语义：保卫的对象是国家的权益，不能是早饭，“保卫这个国家的早饭”说不通。", "发型": "搭配：“保卫”不与“发型”搭配，不能说“保卫这个国家的发型”。", "体重": "体貌：国家没有体重，体重是人或物的体貌特征，不能用于国家。"}, "sentence_index": 6, "correct_answer": "主权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个政府是通过选举产生的主权。", "explanation": "这里应该用〈政权〉。政权指掌握国家权力的政府体制，主权是国家的最高权力，不能用来指政府。"}, {"text": "班长在班里有很大的主权。", "explanation": "这里应该用〈权力〉。主权只指国家对领土和事务的最高权力，个人在集体中的支配力量要说权力。"}, {"text": "他的身份是老师，他的主权也是老师。", "explanation": "这里应该用〈职业〉。主权指国家的最高权力，说明一个人的工作要说职业，不能用主权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家拥有完整地主权。", "corrected_sentence": "这个国家拥有完整的主权。", "error_description": "助词错误：修饰名词“主权”应用“的”，不能用“地”；“完整地主权”应为“完整的主权”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要坚决捍卫了我国的主权。", "corrected_sentence": "我们要坚决捍卫我国的主权。", "error_description": "体标错误：“要……”表示将来，动词后不能加“了”；应说“我们要坚决捍卫我国的主权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
