INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体移动；也指像水流一样移动、流通。", "primary_collocate": null, "pronunciation": "liú", "ipa": "ljoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "墨水从笔尖流到了纸上。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶从倒了的杯子里流到了桌子上。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜很稠，流得很慢。", "target_word": "流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油从锅边流到了火上，真危险。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨一停，屋顶的水就流下来了。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤洒了，汤汁流了一地。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课了，学生们像水一样流出教室。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人群流进了地铁站。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "血液在身体里不停地流。", "target_word": "流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天到了，山上的雪水流进了湖里。", "target_word": "流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "流了", "label": "完成体"}, {"form": "流着", "label": "持续体"}, {"form": "流过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "液体或像液体一样的东西流动、流淌，也可指人群、资源等的流动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc6c39ff-6648-49e0-a3c7-cae6bdba831d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流", "is_correct": true, "explanation": "正确。流 liú，指液体或事物的流动，与听到的音一致。"}, {"text": "柳", "is_correct": false, "explanation": "柳 liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。"}, {"text": "六", "is_correct": false, "explanation": "六 liù（第四声）与 liú（第二声）声调不同，意思是数字六。"}, {"text": "溜", "is_correct": false, "explanation": "溜 liū（第一声）与 liú（第二声）声调不同，意思是滑行、溜走。"}, {"text": "牛", "is_correct": false, "explanation": "牛 niú 的声母是 n，与 liú 的 l 不同，意思是牛。"}], "explanations": {"流": "正确。流 liú，指液体或事物的流动，与听到的音一致。", "柳": "柳 liǔ（第三声）与 liú（第二声）声调不同，意思是柳树。", "六": "六 liù（第四声）与 liú（第二声）声调不同，意思是数字六。", "溜": "溜 liū（第一声）与 liú（第二声）声调不同，意思是滑行、溜走。", "牛": "牛 niú 的声母是 n，与 liú 的 l 不同，意思是牛。"}, "sentence_index": null, "correct_answer": "流"}, "level_3": {"options": [{"text": "流", "is_correct": true, "explanation": "正确。“墨水从笔尖流到了纸上”中的“流”指液体移动，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "词性：“颜色”是名词，不能充当“从笔尖……到纸上”中的动词。"}, {"text": "车牌", "is_correct": false, "explanation": "语义：“车牌”是车辆的标识，与墨水的流动无关，句意不通。"}, {"text": "颜料", "is_correct": false, "explanation": "词性：“颜料”是名词，不能说“墨水从笔尖颜料到纸上”。"}], "explanations": {"流": "正确。“墨水从笔尖流到了纸上”中的“流”指液体移动，与句意相符。", "颜色": "词性：“颜色”是名词，不能充当“从笔尖……到纸上”中的动词。", "车牌": "语义：“车牌”是车辆的标识，与墨水的流动无关，句意不通。", "颜料": "词性：“颜料”是名词，不能说“墨水从笔尖颜料到纸上”。"}, "sentence_index": 0, "correct_answer": "流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把椅子流到门口。", "explanation": "这里应该用〈推〉。“流”用于液体或人群等连续流动，固体家具被移动应说〈推〉。"}, {"text": "他用吸管流果汁。", "explanation": "这里应该用〈吸〉。用吸管是主动吸取，“流”表示液体自然移动，不能表示用吸管取液体。"}, {"text": "这些垃圾被流进了桶里。", "explanation": "这里应该用〈扔〉。垃圾是固体，被人投入应说〈扔〉，“流”只描述液体或连续流动的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流", "is_correct": true, "explanation": "正确。“像水一样流出教室”是比喻，指学生像水一样向外移动，与句意相符。"}, {"text": "爬", "is_correct": false, "explanation": "语义：“爬”指手脚并用地移动，与“像水一样”的比喻不符，不能形容一群人同时涌出。"}, {"text": "飘", "is_correct": false, "explanation": "语义：“飘”形容轻轻浮动，不能用来形容学生像水一样流出教室。"}, {"text": "砍", "is_correct": false, "explanation": "配价：“砍”是及物动词，需要带宾语，“砍出教室”不成立。"}], "explanations": {"流": "正确。“像水一样流出教室”是比喻，指学生像水一样向外移动，与句意相符。", "爬": "语义：“爬”指手脚并用地移动，与“像水一样”的比喻不符，不能形容一群人同时涌出。", "飘": "语义：“飘”形容轻轻浮动，不能用来形容学生像水一样流出教室。", "砍": "配价：“砍”是及物动词，需要带宾语，“砍出教室”不成立。"}, "sentence_index": 6, "correct_answer": "流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行李一路流到了车站。", "explanation": "这里应该用〈拖〉。“流”多用于液体或人群、车流等连续移动，行李是固体，拖着走应说〈拖〉。"}, {"text": "他从书架上流出一本书。", "explanation": "这里应该用〈抽〉。“抽出”指从一堆东西里取出一件；“流”用于液体或连续移动，不能表示从书架上取书。"}, {"text": "杯子流到地上碎了。", "explanation": "这里应该用〈摔〉。杯子是固体，落地摔碎应说〈摔〉，“流”不能描述固体的坠落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红酒洒了，顺着桌腿流来下。", "corrected_sentence": "红酒洒了，顺着桌腿流下来。", "error_description": "补语语序颠倒：趋向补语“下来”是固定语序，应说“流下来”，不能倒置为“流来下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天的雨水流着进了小河。", "corrected_sentence": "昨天的雨水流进了小河。", "error_description": "体标误用：“流进了”已经表示完成的移动，不能再在“流”后加持续体“着”，应说“流进了小河”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e02eb2-f66b-4add-bba2-1045639f8f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
