INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "福祉指幸福、福气，多用于正式场合。", "primary_collocate": null, "pronunciation": "fú zhǐ", "ipa": "fu˧˥ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "房地产的价值根基，正从单一的物理空间占有，转向对生态服务流与社区福祉的动态贡献能力。", "target_word": "福祉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府应该关心人民的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项政策增进了老人的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教育关系到下一代的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要为全体市民谋福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一生致力于增进社会福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "提升居民福祉是这个项目的目标。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护环境就是保护子孙的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不能只追求利润，也要考虑员工的福祉。", "target_word": "福祉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基金会致力于改善儿童福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "幸福、福气（正式用语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7debcc69-2f8e-47f7-8acd-6bf8bbd25c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "福祉", "is_correct": true, "explanation": "福祉 fú zhǐ：幸福、福气，是本词。"}, {"text": "复制", "is_correct": false, "explanation": "复制 fù zhì：两个音节的声调都不同，意思是照原样做出一份，与福祉声音相近。"}, {"text": "扶持", "is_correct": false, "explanation": "扶持 fú chí：声母由 zh 变为 ch，声调也不同，意思是扶助支持。"}, {"text": "废纸", "is_correct": false, "explanation": "废纸 fèi zhǐ：韵母由 u 变为 ei，声调也不同，意思是没用的纸。"}, {"text": "肤质", "is_correct": false, "explanation": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}], "explanations": {"福祉": "福祉 fú zhǐ：幸福、福气，是本词。", "复制": "复制 fù zhì：两个音节的声调都不同，意思是照原样做出一份，与福祉声音相近。", "扶持": "扶持 fú chí：声母由 zh 变为 ch，声调也不同，意思是扶助支持。", "废纸": "废纸 fèi zhǐ：韵母由 u 变为 ei，声调也不同，意思是没用的纸。", "肤质": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}, "sentence_index": null, "correct_answer": "福祉"}, "level_3": {"options": [{"text": "福祉", "is_correct": true, "explanation": "正确：社区福祉指社区居民的幸福与利益，与前句的“生态服务”和“贡献能力”相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是交易中的金额，与“社区……贡献能力”的福利内涵不符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，与“价值根基”和正面的贡献语境相悖。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：“贡献能力”的对象应是人或社会利益，“停车场”是设施，不能作为贡献的对象。"}], "explanations": {"福祉": "正确：社区福祉指社区居民的幸福与利益，与前句的“生态服务”和“贡献能力”相合。", "价格": "语义：“价格”是交易中的金额，与“社区……贡献能力”的福利内涵不符。", "垃圾": "语义：“垃圾”是废弃物，与“价值根基”和正面的贡献语境相悖。", "停车场": "搭配：“贡献能力”的对象应是人或社会利益，“停车场”是设施，不能作为贡献的对象。"}, "sentence_index": 0, "correct_answer": "福祉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司为员工发了很好的福祉，大家都很满意。", "explanation": "这里应该用〈福利〉。福利指员工得到的具体待遇，福祉指人的整体幸福，不用于具体的待遇。"}, {"text": "这次谈判我们争取到了很大的福祉。", "explanation": "这里应该用〈利益〉。福祉指人的幸福，谈判争取到的得失要用利益，不用福祉。"}, {"text": "这家商店把店里的福祉都卖光了。", "explanation": "这里应该用〈商品〉。福祉指人的幸福，不能像货物一样卖光；店里的货物要用商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "福祉", "is_correct": true, "explanation": "福祉 fú zhǐ：幸福、福气，是本词。"}, {"text": "服饰", "is_correct": false, "explanation": "服饰 fú shì：第二音节声母由 zh 变为 sh，声调也不同，意思是衣服和装饰品。"}, {"text": "复制", "is_correct": false, "explanation": "复制 fù zhì：两个音节的声调都不同，意思是照原样做出一份。"}, {"text": "肤质", "is_correct": false, "explanation": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}, {"text": "扶志", "is_correct": false, "explanation": "扶志 fú zhì：第二音节由第三声变为第四声，意思是扶助意志。"}], "explanations": {"福祉": "福祉 fú zhǐ：幸福、福气，是本词。", "服饰": "服饰 fú shì：第二音节声母由 zh 变为 sh，声调也不同，意思是衣服和装饰品。", "复制": "复制 fù zhì：两个音节的声调都不同，意思是照原样做出一份。", "肤质": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。", "扶志": "扶志 fú zhì：第二音节由第三声变为第四声，意思是扶助意志。"}, "sentence_index": null, "correct_answer": "福祉"}, "level_3": {"options": [{"text": "福祉", "is_correct": true, "explanation": "正确：居民福祉指居民的幸福与利益，与“居民”和“项目目标”相合。"}, {"text": "恩情", "is_correct": false, "explanation": "搭配：“提升”不能与“恩情”搭配，恩情是要报答的，不能被提升。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“提升”用于质量或水平，“居民树木”没有意义，树木不能作为提升的对象。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是害虫，项目不会以提升蚊子为目标，与语境不符。"}], "explanations": {"福祉": "正确：居民福祉指居民的幸福与利益，与“居民”和“项目目标”相合。", "恩情": "搭配：“提升”不能与“恩情”搭配，恩情是要报答的，不能被提升。", "树木": "搭配：“提升”用于质量或水平，“居民树木”没有意义，树木不能作为提升的对象。", "蚊子": "语义：蚊子是害虫，项目不会以提升蚊子为目标，与语境不符。"}, "sentence_index": 6, "correct_answer": "福祉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司给社区带来了一座福祉。", "explanation": "量词误用：福祉是抽象名词，不能用“座”计量，应去掉“一座”，说“带来了福祉”。"}, {"text": "政府给每家每户送了一颗福祉。", "explanation": "量词误用：福祉是抽象名词，不能用“颗”计量，也不能像东西一样“送”，应说“为每家每户带来福祉”。"}, {"text": "这个基金会给孩子们留下了一把福祉。", "explanation": "量词误用：福祉是抽象名词，不能用“把”计量，应去掉“一把”，说“留下了福祉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项计划带来了一颗福祉。", "corrected_sentence": "这项计划带来了很多福祉。", "error_description": "量词错误：「颗」用于粒状的小东西，不能用来计量福祉，应说「很多福祉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位市长一直市民谋福祉。", "corrected_sentence": "这位市长一直为市民谋福祉。", "error_description": "介词缺失：“为市民”表示对象，不能省去“为”，应说“为市民谋福祉”，不能说“市民谋福祉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a7285b4-2dba-41ef-b2ce-e1b77463d0ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“新”与“老”在存在时间长的意思上相反。"}, {"text": "快", "is_correct": false, "explanation": "“快”形容速度，与“老”的时间义没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”形容高度，与“老”的时间义没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”形容厚度，与“老”的时间义没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“新”与“老”在存在时间长的意思上相反。", "快": "“快”形容速度，与“老”的时间义没有反义关系。", "高": "“高”形容高度，与“老”的时间义没有反义关系。", "厚": "“厚”形容厚度，与“老”的时间义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“新”与“老”在存在时间长的意思上相反。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”形容重量，与“老”的时间义没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”形容光线，与“老”的时间义没有反义关系。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”形容宽度，与“老”的时间义没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“新”与“老”在存在时间长的意思上相反。", "轻": "“轻”形容重量，与“老”的时间义没有反义关系。", "亮": "“亮”形容光线，与“老”的时间义没有反义关系。", "宽": "“宽”形容宽度，与“老”的时间义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指程度深、时间长或经验丰富。", "primary_collocate": null, "pronunciation": "lǎo", "ipa": "lɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "在很干的地方，人们用老方法存水。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子很老，下雨时会漏水。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老医生，看病的经验很丰富。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树太老了，今年没有长叶子。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农民种了五十年地，知道什么时候下雨。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老工人，修机器又快又好。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老厨师做菜又快又好吃。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有很多老房子，都有一百年了。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听的是一首老歌，二十年前很有名。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的手机很老，只能打电话。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老了", "label": "体标"}], "register": "中性", "sense_fingerprint": "老：存在的时间长，或经验丰富", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老", "is_correct": true, "explanation": "老 lǎo：存在的时间长，或经验丰富。"}, {"text": "劳", "is_correct": false, "explanation": "láo（第二声）与 lǎo 声调不同，意思是劳动。"}, {"text": "烙", "is_correct": false, "explanation": "lào（第四声）与 lǎo 声调不同，意思是用火烤。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 lǎo 声母不同（n 与 l），意思是大脑。"}], "explanations": {"老": "老 lǎo：存在的时间长，或经验丰富。", "劳": "láo（第二声）与 lǎo 声调不同，意思是劳动。", "烙": "lào（第四声）与 lǎo 声调不同，意思是用火烤。", "脑": "nǎo 与 lǎo 声母不同（n 与 l），意思是大脑。"}, "sentence_index": null, "correct_answer": "老"}, "level_3": {"options": [{"text": "老", "is_correct": true, "explanation": "“老方法”指存在时间长的传统方法，与句中的语境相符。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“很干的地方”与“湿”矛盾，“湿方法用水”说不通。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”只用于人或年龄，不能修饰“方法”。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢方法”不是固定说法，与“用水”的语境不搭。"}], "explanations": {"老": "“老方法”指存在时间长的传统方法，与句中的语境相符。", "湿": "语义：“很干的地方”与“湿”矛盾，“湿方法用水”说不通。", "年轻": "语义：“年轻”只用于人或年龄，不能修饰“方法”。", "慢": "搭配：“慢方法”不是固定说法，与“用水”的语境不搭。"}, "sentence_index": 0, "correct_answer": "老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位工人操作机器很老，从不出错。", "explanation": "这里应该用〈熟练〉。「老」形容东西存在的时间长或人的经验丰富，不说操作机器很老；操作的熟练程度要用「熟练」。"}, {"text": "这里离市中心很老，骑车要一个小时。", "explanation": "这里应该用〈远〉。「老远」可以说，但「很老」不用来形容距离；说距离远要用「远」。"}, {"text": "这件事已经过去很老了，大家都忘了。", "explanation": "这里应该用〈久〉。「老」形容东西或人的状态，不说事情过去的时间，表示时间长要用「久」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老", "is_correct": true, "explanation": "老 lǎo：存在的时间长，或经验丰富。"}, {"text": "牢", "is_correct": false, "explanation": "láo（第二声）与 lǎo 声调不同，意思是监狱。"}, {"text": "涝", "is_correct": false, "explanation": "lào（第四声）与 lǎo 声调不同，意思是雨水过多造成的积水。"}, {"text": "恼", "is_correct": false, "explanation": "nǎo（第三声）与 lǎo 声母不同（n 与 l），意思是生气。"}], "explanations": {"老": "老 lǎo：存在的时间长，或经验丰富。", "牢": "láo（第二声）与 lǎo 声调不同，意思是监狱。", "涝": "lào（第四声）与 lǎo 声调不同，意思是雨水过多造成的积水。", "恼": "nǎo（第三声）与 lǎo 声母不同（n 与 l），意思是生气。"}, "sentence_index": null, "correct_answer": "老"}, "level_3": {"options": [{"text": "老", "is_correct": true, "explanation": "“老厨师”指经验丰富的厨师，与句中的语境相符。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢厨师”与后半句“做菜又快又好吃”矛盾。"}, {"text": "笨", "is_correct": false, "explanation": "语义：“笨”形容能力差，与“做菜又快又好吃”矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "搭配：“懒”形容性格，与“做菜又快又好吃”的描述不搭。"}], "explanations": {"老": "“老厨师”指经验丰富的厨师，与句中的语境相符。", "慢": "语义：“慢厨师”与后半句“做菜又快又好吃”矛盾。", "笨": "语义：“笨”形容能力差，与“做菜又快又好吃”矛盾。", "懒": "搭配：“懒”形容性格，与“做菜又快又好吃”的描述不搭。"}, "sentence_index": 6, "correct_answer": "老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学成绩很老，这次又考了第一名。", "explanation": "这里应该用〈高〉。「老」形容东西存在的时间长或人的经验丰富，不用来形容成绩的好坏；成绩好要用「高」。"}, {"text": "今天的天气很老，适合出去玩。", "explanation": "这里应该用〈好〉。「老」指人或东西存在的时间长，不用来形容天气；天气好坏要用「好」。"}, {"text": "他写字很老，一分钟就写完了。", "explanation": "这里应该用〈快〉。「老」形容东西存在的时间长或人的经验丰富，不用来形容动作的速度；写得快要用「快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵树已经老了了，不结果了。", "corrected_sentence": "这棵树已经老了，不结果了。", "error_description": "“老了”后面不能再加“了”。正确的说法是「这棵树已经老了，不结果了」，错误在多加了一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆自行车很老过，但是还能骑。", "corrected_sentence": "那辆自行车很老，但是还能骑。", "error_description": "“老”后面不能用“过”表示经历，应去掉“过”，说「那辆自行车很老，但是还能骑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
