INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12733, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12733, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小的沟渠，通常指狭窄的人工或自然水道。", "primary_collocate": null, "pronunciation": "xiǎo gōu", "ipa": "ɕiɑʊ˨˩˦ kɤʊ˥", "syllable_count": 2, "sentences": [{"text": "他们用石头建小沟，雨水流到田里。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "田边有一条小沟，水慢慢地流着。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩在小沟里放了一只纸船。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，小沟里的水很清，能看见小鱼。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小路旁边的小沟把雨水引到河里。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳过那条小沟，跑到了对面。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，小沟里全是黄色的水。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人每年春天都要清理小沟。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小沟太窄，大船开不进去。", "target_word": "小沟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶家门前有一条小沟，夏天有青蛙。", "target_word": "小沟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "小溝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小的沟渠；狭窄的人工或自然水道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小沟", "is_correct": true, "explanation": "“建小沟”指修筑窄窄的水道，与“雨水流到田里”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：不能用石头“建”小狗。"}, {"text": "小鸡", "is_correct": false, "explanation": "语义：不能用石头“建”小鸡。"}, {"text": "小锅", "is_correct": false, "explanation": "搭配：“建”用于房屋、渠道等，不说“建小锅”。"}], "explanations": {"小沟": "“建小沟”指修筑窄窄的水道，与“雨水流到田里”相符。", "小狗": "语义：不能用石头“建”小狗。", "小鸡": "语义：不能用石头“建”小鸡。", "小锅": "搭配：“建”用于房屋、渠道等，不说“建小锅”。"}, "sentence_index": 0, "correct_answer": "小沟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条小沟很宽，大船能开过去。", "explanation": "这里应该用〈河〉。「小沟」是窄窄的小水道，不能说很宽、大船能开过去。"}, {"text": "他在商店买了一条小沟，放在浴缸里玩。", "explanation": "这里应该用〈小船〉。小沟是地上的水道，不能在商店买来放进浴缸里玩。"}, {"text": "这条小沟像大楼一样高，我们爬不上去。", "explanation": "这里应该用〈小山〉。「小沟」是地面上向下的窄水道，不能说像大楼一样高、要往上爬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小沟", "is_correct": true, "explanation": "“小沟里全是黄色的水”指雨后积水的窄水道，与句意相符。"}, {"text": "小山", "is_correct": false, "explanation": "语义：小山上不会“里面全是黄色的水”。"}, {"text": "小桥", "is_correct": false, "explanation": "配价：“里”需要容器或范围，“小桥”不能用来装水。"}, {"text": "小床", "is_correct": false, "explanation": "语义：小床里不会积满雨后的黄水。"}], "explanations": {"小沟": "“小沟里全是黄色的水”指雨后积水的窄水道，与句意相符。", "小山": "语义：小山上不会“里面全是黄色的水”。", "小桥": "配价：“里”需要容器或范围，“小桥”不能用来装水。", "小床": "语义：小床里不会积满雨后的黄水。"}, "sentence_index": 6, "correct_answer": "小沟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶家门前有一条小沟，我们在上面骑车。", "explanation": "这里应该用〈小路〉。「小沟」是水道，不能在上面骑车；骑车要用「小路」。"}, {"text": "孩子们在小沟里打篮球。", "explanation": "这里应该用〈操场〉。「小沟」是窄窄的水道，不能用来打篮球。"}, {"text": "他把小沟拧开，水就流出来了。", "explanation": "这里应该用〈水龙头〉。「小沟」不能用「拧」来开，拧的是水龙头等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在田边挖了一只小沟，让雨水流走。", "corrected_sentence": "他在田边挖了一条小沟，让雨水流走。", "error_description": "「小沟」的量词要用「条」，不用「只」；「只」多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把那条小沟喝干了。", "corrected_sentence": "工人把那条小沟排干了。", "error_description": "“喝”的对象是饮品，不能用于水道；把沟里的水弄干要说“排干”。错误：“喝干”。正确：“排干”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
