INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指通过跑步或快速移动的方式离开某处。", "primary_collocate": null, "pronunciation": "pǎo diào", "ipa": "pʰaʊ˨˩˦ tiaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "田边的松鼠听见脚步声，马上就跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只狗听见门响，早就跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小偷看见警察，马上跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门没关好，小狗跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕妈妈骂他，一下子就跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚走近，兔子就跑掉了。", "target_word": "跑掉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别让那只羊跑掉。", "target_word": "跑掉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们笑着跑掉了。", "target_word": "跑掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把门打开，马一下就跑掉了。", "target_word": "跑掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我追过去的时候，他已经跑掉了。", "target_word": "跑掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑掉了", "label": "体标（了）"}, {"form": "跑不掉", "label": "可能补语（否定）"}, {"form": "跑得掉", "label": "可能补语（肯定）"}], "register": "口语", "sense_fingerprint": "跑着或快速移动，从某处离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b763f8e4-c8e2-4fed-b4e1-513ee2e3c8b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉（pǎo diào）：快速离开，不在原处了，是本题的正确词形。"}, {"text": "跑跳", "is_correct": false, "explanation": "跑跳（pǎo tiào）与跑掉的第二音节声母不同（t 与 d），声调相同，意思是边跑边跳。"}, {"text": "跑道", "is_correct": false, "explanation": "跑道（pǎo dào）与跑掉的第二音节韵母不同（dào 与 diào），声调相同，意思是运动场或机场的跑道。"}, {"text": "倒掉", "is_correct": false, "explanation": "倒掉（dǎo diào）与跑掉的第一音节声母不同（d 与 p），声调相同，意思是把液体倒出去。"}], "explanations": {"跑掉": "跑掉（pǎo diào）：快速离开，不在原处了，是本题的正确词形。", "跑跳": "跑跳（pǎo tiào）与跑掉的第二音节声母不同（t 与 d），声调相同，意思是边跑边跳。", "跑道": "跑道（pǎo dào）与跑掉的第二音节韵母不同（dào 与 diào），声调相同，意思是运动场或机场的跑道。", "倒掉": "倒掉（dǎo diào）与跑掉的第一音节声母不同（d 与 p），声调相同，意思是把液体倒出去。"}, "sentence_index": null, "correct_answer": "跑掉"}, "level_3": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉：快速离开，符合松鼠听见脚步声后迅速逃走的语境。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”只用于种子或植物，松鼠不能发芽，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语是天气，与松鼠不搭配，句意不通。"}, {"text": "咬掉", "is_correct": false, "explanation": "搭配：“咬掉”需要宾语，且与“听见脚步声”后的语境不符，句意不通。"}], "explanations": {"跑掉": "跑掉：快速离开，符合松鼠听见脚步声后迅速逃走的语境。", "发芽": "语义：“发芽”只用于种子或植物，松鼠不能发芽，句意不通。", "下雨": "语义：“下雨”的主语是天气，与松鼠不搭配，句意不通。", "咬掉": "搭配：“咬掉”需要宾语，且与“听见脚步声”后的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "跑掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的钱包突然跑掉了，怎么也找不到。", "explanation": "这句想表达“丢失”；钱包不能自行离开，跑掉指人或动物快速离开，此义应用〈丢失〉。"}, {"text": "这把椅子突然跑掉了。", "explanation": "这句想表达“翻倒”；椅子不能自行离开，跑掉指人或动物快速离开，此义应用〈翻倒〉。"}, {"text": "这扇窗户突然跑掉了。", "explanation": "这句想表达“脱落”；窗户不能自行离开，跑掉指人或动物快速离开，此义应用〈脱落〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12738, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉（pǎo diào）：快速离开，不在原处了，是本题的正确词形。"}, {"text": "抛掉", "is_correct": false, "explanation": "抛掉（pāo diào）与跑掉的第一音节声调不同（第一声与第三声），意思是扔掉。"}, {"text": "泡掉", "is_correct": false, "explanation": "泡掉（pào diào）与跑掉的第一音节声调不同（第四声），意思是用水浸掉。"}, {"text": "刨掉", "is_correct": false, "explanation": "刨掉（páo diào）与跑掉的第一音节声调不同（第二声），意思是挖去或削去。"}], "explanations": {"跑掉": "跑掉（pǎo diào）：快速离开，不在原处了，是本题的正确词形。", "抛掉": "抛掉（pāo diào）与跑掉的第一音节声调不同（第一声与第三声），意思是扔掉。", "泡掉": "泡掉（pào diào）与跑掉的第一音节声调不同（第四声），意思是用水浸掉。", "刨掉": "刨掉（páo diào）与跑掉的第一音节声调不同（第二声），意思是挖去或削去。"}, "sentence_index": null, "correct_answer": "跑掉"}, "level_3": {"options": [{"text": "跑掉", "is_correct": true, "explanation": "跑掉：离开，符合“别让……”的语境，表示羊逃走。"}, {"text": "说话", "is_correct": false, "explanation": "语义：羊不能“说话”，“别让那只羊说话”句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“别让……”所表达的防止逃离无关，句意不通。"}, {"text": "宴请", "is_correct": false, "explanation": "语域：“宴请”是正式书面用语，且对象通常是人，与口语语境不符。"}], "explanations": {"跑掉": "跑掉：离开，符合“别让……”的语境，表示羊逃走。", "说话": "语义：羊不能“说话”，“别让那只羊说话”句意不通。", "唱歌": "语义：“唱歌”与“别让……”所表达的防止逃离无关，句意不通。", "宴请": "语域：“宴请”是正式书面用语，且对象通常是人，与口语语境不符。"}, "sentence_index": 6, "correct_answer": "跑掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一动不动地跑掉了。", "explanation": "这句想表达“静止不动”；跑掉指通过快速移动离开某处，不能用于静止的人，与“一动不动”矛盾。"}, {"text": "这棵老树突然跑掉了。", "explanation": "这句想表达“倒下”；树不能自行离开，跑掉指人或动物快速离开，此义应用〈倒下〉。"}, {"text": "他的鼻子突然跑掉了。", "explanation": "这句想表达“脱落”；鼻子不能自行离开，跑掉指人或动物快速离开，此义应用〈脱落〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小偷趁乱没跑掉了。", "corrected_sentence": "小偷趁乱跑掉了。", "error_description": "错误在于多加了否定词“没”。“没”与“了”不能同用，应删去“没”，说“小偷趁乱跑掉了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只猫被跑掉了。", "corrected_sentence": "那只猫跑掉了。", "error_description": "错误在于给不及物动词“跑掉”加了“被”字句。“跑掉”没有受事主语，不能用被动，应去掉“被”，说“那只猫跑掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
