INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水渠是人工修建的、用于引水灌溉或排水的渠道。", "primary_collocate": null, "pronunciation": "shuǐ qú", "ipa": "ʂweɪ˨˩˦ tɕʰy˧˥", "syllable_count": 2, "sentences": [{"text": "农民在田边挖了水渠，把河水引进来灌溉。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的水渠每年都要清理一次。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了这条水渠，田里就能浇水了。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用石头建小水渠，把雨水引到田里。", "target_word": "水渠", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "早上，一个人看水渠，不让水乱流。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "水渠里的水很清。", "target_word": "水渠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农民沿着水渠走到田边。", "target_word": "水渠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条水渠是爷爷年轻时修的。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨后，水渠里满是水。", "target_word": "水渠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在水渠边玩。", "target_word": "水渠", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "输水渠", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人工修建的引水灌溉或排水的渠道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b763f8e4-c8e2-4fed-b4e1-513ee2e3c8b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12744, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水渠", "is_correct": true, "explanation": "水渠（shuǐ qú）指人工修建的引水渠道，是正确答案。"}, {"text": "水球", "is_correct": false, "explanation": "qú（第二声）与 qiú（第二声）韵母不同（ü 与 iou），声调相同，意思是水球（一种球类运动）。"}, {"text": "睡去", "is_correct": false, "explanation": "睡去（shuì qù）与水渠（shuǐ qú）声母韵母相同，两个音节声调都不同，意思是睡着。"}, {"text": "水泉", "is_correct": false, "explanation": "qú 与 quán 韵母不同，意思是泉水的出口，不是人工修建的渠道。"}], "explanations": {"水渠": "水渠（shuǐ qú）指人工修建的引水渠道，是正确答案。", "水球": "qú（第二声）与 qiú（第二声）韵母不同（ü 与 iou），声调相同，意思是水球（一种球类运动）。", "睡去": "睡去（shuì qù）与水渠（shuǐ qú）声母韵母相同，两个音节声调都不同，意思是睡着。", "水泉": "qú 与 quán 韵母不同，意思是泉水的出口，不是人工修建的渠道。"}, "sentence_index": null, "correct_answer": "水渠"}, "level_3": {"options": [{"text": "水渠", "is_correct": true, "explanation": "水渠：人工修建的渠道，“挖了”后可以接，与“引进来灌溉”相符。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头是出水的装置，不能被“挖”，句意不通。"}, {"text": "水泵", "is_correct": false, "explanation": "语义：水泵是抽水的机器，不能被“挖”，与“引进来灌溉”的语境不符。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是盛水的器具，不能被“挖”，句意不通。"}], "explanations": {"水渠": "水渠：人工修建的渠道，“挖了”后可以接，与“引进来灌溉”相符。", "水龙头": "语义：水龙头是出水的装置，不能被“挖”，句意不通。", "水泵": "语义：水泵是抽水的机器，不能被“挖”，与“引进来灌溉”的语境不符。", "水杯": "语义：水杯是盛水的器具，不能被“挖”，句意不通。"}, "sentence_index": 0, "correct_answer": "水渠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们家洗澡用的水渠坏了，要请人修。", "explanation": "这里应该用〈水管〉。水渠是田间的排灌渠道，不能用来给人洗澡供水，供水的应是水管。"}, {"text": "妈妈把水渠端到桌子上，给客人倒茶。", "explanation": "这里应该用〈茶壶〉。水渠是固定在地上的渠道，不能端起来倒茶，倒茶的应是茶壶。"}, {"text": "他把水渠拧紧了，免得漏水。", "explanation": "这里应该用〈水龙头〉。水渠是地面的渠道，不能拧紧或关闭，拧紧的应是水龙头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水渠", "is_correct": true, "explanation": "“沿着”后接路线，“水渠”是可以沿行的渠道，可以填入。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶是盛水的器具，不能作为行走的路线。"}, {"text": "水泵", "is_correct": false, "explanation": "语义：水泵是抽水的机器，不是可以沿着走的地方。"}, {"text": "水桶", "is_correct": false, "explanation": "搭配：“沿着”后接路线或地段，“水桶”是容器，二者搭配不当。"}], "explanations": {"水渠": "“沿着”后接路线，“水渠”是可以沿行的渠道，可以填入。", "水壶": "语义：水壶是盛水的器具，不能作为行走的路线。", "水泵": "语义：水泵是抽水的机器，不是可以沿着走的地方。", "水桶": "搭配：“沿着”后接路线或地段，“水桶”是容器，二者搭配不当。"}, "sentence_index": 6, "correct_answer": "水渠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们把水渠放进书包，带回家玩。", "explanation": "这里应该用〈玩具〉。水渠是地上修的渠道，不能放进书包带走。"}, {"text": "孩子们坐在水渠上看电视。", "explanation": "这里应该用〈沙发〉。水渠是引水的渠道，不是坐着看电视的家具。"}, {"text": "孩子们用水渠给奶奶写了一封信。", "explanation": "这里应该用〈笔〉。水渠是引水的渠道，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民每年春天都要清理一朵水渠。", "corrected_sentence": "村民每年春天都要清理一条水渠。", "error_description": "“水渠”的量词应用“条”，不能用“朵”。“朵”用于花朵、云朵等，水渠不能用“朵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里有一条很长水渠。", "corrected_sentence": "村里有一条很长的水渠。", "error_description": "修饰语“很长”与名词“水渠”之间漏了“的”。修饰语是词组时要用“的”连接，应说“很长的水渠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
