INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指共同居住在一个地方，通常指家庭成员或关系亲密的人一起生活。", "primary_collocate": null, "pronunciation": "zhù zài yì qǐ", "ipa": "ʈ͡ʂu˥˩ t͡sai˥˩ i˥˩ t͡ɕʰi˨˩˦", "syllable_count": 4, "sentences": [{"text": "大家住在一起，每家轮流用水。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他们是一家人，住在一起很热闹。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友在北京住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶和我们住在一起。", "target_word": "住在一起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们结婚以后，就住在一起了。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个学生为了省钱，住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想和爸爸妈妈住在一起吗？", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前我们三个人住在一起过。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我和两个朋友住在一起，互相照顾。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想搬出去，不想和父母住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "住在一起了", "label": "完成体"}, {"form": "住在一起过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "亲人或亲密的人共同居住在同一处并一起生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独居", "is_correct": false, "explanation": "语义：“独居”指一人独自生活，与“大家”共处一处、轮流用水的情境矛盾。"}, {"text": "住在一起", "is_correct": true, "explanation": "正确：“大家住在一起”与“每家轮流用水”相符，几家共处一处才需要轮流用水。"}, {"text": "搬走", "is_correct": false, "explanation": "语义：“搬走”指迁离原处，与几家仍共用水源的情境矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指闲步走动，与“每家轮流用水”的情境无关。"}], "explanations": {"独居": "语义：“独居”指一人独自生活，与“大家”共处一处、轮流用水的情境矛盾。", "住在一起": "正确：“大家住在一起”与“每家轮流用水”相符，几家共处一处才需要轮流用水。", "搬走": "语义：“搬走”指迁离原处，与几家仍共用水源的情境矛盾。", "散步": "语义：“散步”指闲步走动，与“每家轮流用水”的情境无关。"}, "sentence_index": 0, "correct_answer": "住在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人住在一起，很自在。", "explanation": "这里不这么用。住在一起指两人或多人共同住在一处，只有一个人时应说“一个人住”。"}, {"text": "这台冰箱和洗衣机住在一起。", "explanation": "这里应该用〈放在一起〉。住在一起指人或动物共同居住，家电不能“住”，只能说放在一起。"}, {"text": "地铁高峰时，大家住在一起。", "explanation": "这里应该用〈挤在一起〉。住在一起指共同居住，不能形容车厢里拥挤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失散", "is_correct": false, "explanation": "语义：“失散”指走散、失去联系，与“你想和爸爸妈妈……吗”的意愿相悖。"}, {"text": "住在一起", "is_correct": true, "explanation": "正确：“你想和爸爸妈妈住在一起吗”是询问是否愿意同住，与句意相符。"}, {"text": "分手", "is_correct": false, "explanation": "搭配：“分手”多指恋人或伴侣分开，不能用于和父母的关系。"}, {"text": "居留", "is_correct": false, "explanation": "语域：“居留”是书面或官方用语，不符合这句口语提问。"}], "explanations": {"失散": "语义：“失散”指走散、失去联系，与“你想和爸爸妈妈……吗”的意愿相悖。", "住在一起": "正确：“你想和爸爸妈妈住在一起吗”是询问是否愿意同住，与句意相符。", "分手": "搭配：“分手”多指恋人或伴侣分开，不能用于和父母的关系。", "居留": "语域：“居留”是书面或官方用语，不符合这句口语提问。"}, "sentence_index": 6, "correct_answer": "住在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们在公园住在一起。", "explanation": "这里应该用〈见面〉。住在一起指共同住在一处，不能表示在公园碰面。"}, {"text": "拍合影时，我们住在一起。", "explanation": "这里应该用〈站在一起〉。住在一起指共同居住，拍照时的站位不能用它。"}, {"text": "排队买票时，大家住在一起。", "explanation": "这里应该用〈站在一起〉。住在一起指共同居住，不能指排队时站在一处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毕业后，把我和同学住在一起，房租一人一半。", "corrected_sentence": "毕业后，我和同学住在一起，房租一人一半。", "error_description": "“把”错误：“住在一起”前不能加“把”，应去掉“把”，说“我和同学住在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "如果你毕业了，还想和爸爸妈妈住在一起了吗？", "corrected_sentence": "如果你毕业了，还想和爸爸妈妈住在一起吗？", "error_description": "多余的“了”：“还想”表示尚未实现的意愿，句中不能用“了”，应去掉“了”，说“还想和爸爸妈妈住在一起吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
