INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按顺序依次进行，一个接着一个，周而复始。", "primary_collocate": null, "pronunciation": "lún liú", "ipa": "lwən˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "大家住在一起，每家轮流用水。", "target_word": "轮流", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们三个人轮流做饭。", "target_word": "轮流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子生病了，爸爸妈妈轮流照顾他。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们轮流回答老师的问题。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天你洗碗，明天他洗，我们轮流。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机太累了，两个人轮流开车。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们轮流打扫教室，今天轮到我。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家排好队，轮流上车。", "target_word": "轮流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里孩子哭，妈妈和奶奶轮流起床。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们轮流用一台电脑写作业。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按顺序一个接一个地做，并且反复循环", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辩论", "is_correct": false, "explanation": "语义：“辩论”指争论是非，与“每家轮流用水”的情境无关。"}, {"text": "轮流", "is_correct": true, "explanation": "正确：“每家轮流用水”指几家依次用水，与“大家住在一起”相符。"}, {"text": "霸占", "is_correct": false, "explanation": "语义：“霸占”指强占，与依次轮用水的意思不符。"}, {"text": "打理", "is_correct": false, "explanation": "搭配：“打理”不能搭配“用水”。"}], "explanations": {"辩论": "语义：“辩论”指争论是非，与“每家轮流用水”的情境无关。", "轮流": "正确：“每家轮流用水”指几家依次用水，与“大家住在一起”相符。", "霸占": "语义：“霸占”指强占，与依次轮用水的意思不符。", "打理": "搭配：“打理”不能搭配“用水”。"}, "sentence_index": 0, "correct_answer": "轮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人轮流回答老师的问题。", "explanation": "这里不这么用。轮流需要两人或以上依次进行，只有一个人时不能用〈轮流〉。"}, {"text": "同学们轮流同时回答老师的问题。", "explanation": "这里不这么用。轮流指一个接一个依次进行，与“同时”矛盾。"}, {"text": "同学们轮流集体回答老师的问题。", "explanation": "这里应该用〈一起〉。轮流指依次进行，与“集体”（同时全体）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人，与“我们”及“今天轮到我”的轮换矛盾。"}, {"text": "轮流", "is_correct": true, "explanation": "正确：“我们轮流打扫教室，今天轮到我”说明大家依次打扫，与句意相符。"}, {"text": "包揽", "is_correct": false, "explanation": "语义：“包揽”指全部承担，与“今天轮到我”的轮换矛盾。"}, {"text": "退避", "is_correct": false, "explanation": "语域：“退避”是书面用语，且意思是躲避，不符合这句口语。"}], "explanations": {"独自": "语义：“独自”指一个人，与“我们”及“今天轮到我”的轮换矛盾。", "轮流": "正确：“我们轮流打扫教室，今天轮到我”说明大家依次打扫，与句意相符。", "包揽": "语义：“包揽”指全部承担，与“今天轮到我”的轮换矛盾。", "退避": "语域：“退避”是书面用语，且意思是躲避，不符合这句口语。"}, "sentence_index": 6, "correct_answer": "轮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们轮流各自用一台电脑写作业。", "explanation": "这里不这么用。“轮流”表示共用一件东西依次使用，“各自用一台”与之矛盾。"}, {"text": "他们轮流并排写作业。", "explanation": "这里应该用〈一起〉。轮流指依次进行，与“并排”（同时在旁）矛盾。"}, {"text": "他们轮流一起写作业。", "explanation": "这里不这么用。轮流指依次进行，与“一起”（同时）矛盾，应去掉“轮流”，说“他们一起写作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们轮流了打扫教室，每周换一次。", "corrected_sentence": "同学们轮流打扫教室，每周换一次。", "error_description": "“轮流了”错误，应为“轮流打扫”。“了”不能插在状语“轮流”和动词“打扫”之间，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们三个人把轮流看护孩子，每人一天。", "corrected_sentence": "他们三个人轮流看护孩子，每人一天。", "error_description": "“把”误用：“轮流”是状语，后面直接接动词，“把”字句需要“把+宾语+动词”，此处应去掉“把”，说“轮流看护孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大意", "is_correct": true, "explanation": "“大意”指粗疏、不留神，与“小心”构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "柔软", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "整齐", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}], "correct_answer": "大意", "explanations": {"大意": "“大意”指粗疏、不留神，与“小心”构成反义关系。", "明亮": "与“小心”没有反义关系，语义无关。", "柔软": "与“小心”没有反义关系，语义无关。", "整齐": "与“小心”没有反义关系，语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗心", "is_correct": true, "explanation": "“粗心”指不细心、不留神，与“小心”构成反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "圆满", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}], "correct_answer": "粗心", "explanations": {"粗心": "“粗心”指不细心、不留神，与“小心”构成反义关系。", "热闹": "与“小心”没有反义关系，语义无关。", "潮湿": "与“小心”没有反义关系，语义无关。", "圆满": "与“小心”没有反义关系，语义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注意、留神，避免发生危险或错误。", "primary_collocate": null, "pronunciation": "xiǎo xīn", "ipa": "ɕjɑʊ˨˩˦ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "地上很滑，大家走路都要小心。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯水很烫，你喝的时候要小心。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时要小心，别写错名字。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些玻璃杯很容易碎，请你小心拿。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过马路的时候要小心车。", "target_word": "小心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上车多，你开车要小心。", "target_word": "小心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，写作业时要小心，别抄错题。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请小心，地上的水还没有干。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是重要的文件，你要小心保管。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天路滑，走路要小心。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小心点儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "小心：留神注意，避免出错或出危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72bece28-fe60-41bb-93d2-7f058d6d083f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小心", "is_correct": true, "explanation": "正确：地上滑，走路要留神，“小心”与句意相符。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”需要对象，且与地滑要留神的语境无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：走路时不能睡觉，与句意不符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：地上很滑时跳舞与提醒注意的句意相反。"}], "explanations": {"小心": "正确：地上滑，走路要留神，“小心”与句意相符。", "浪费": "语义：“浪费”需要对象，且与地滑要留神的语境无关。", "睡觉": "语义：走路时不能睡觉，与句意不符。", "跳舞": "语义：地上很滑时跳舞与提醒注意的句意相反。"}, "sentence_index": 0, "correct_answer": "小心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天小心生病的爷爷。", "explanation": "这里应该用〈照顾〉。“小心”表示注意避免错误或危险，不用于照料人。"}, {"text": "奶奶每天小心孙子上学。", "explanation": "这里应该用〈陪伴〉。“小心”表示留神避免出错，不能用来指陪同。"}, {"text": "他很小心，一句话不说就动手打人。", "explanation": "这里应该用〈冲动〉。“小心”表示留神避免错误，与“动手打人”的莽撞相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小心", "is_correct": true, "explanation": "“小心”指注意避免出错，与后句“别抄错题”前后呼应。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：写作业时跳舞与句意不相合。"}, {"text": "放心", "is_correct": false, "explanation": "语义：“放心”表示不用担心，与后句提醒“别抄错题”矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”需要带宾语，句中没有打扫的对象。"}], "explanations": {"小心": "“小心”指注意避免出错，与后句“别抄错题”前后呼应。", "跳舞": "语义：写作业时跳舞与句意不相合。", "放心": "语义：“放心”表示不用担心，与后句提醒“别抄错题”矛盾。", "打扫": "配价：“打扫”需要带宾语，句中没有打扫的对象。"}, "sentence_index": 6, "correct_answer": "小心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他上个月小心了一个好朋友。", "explanation": "这里应该用〈认识〉。“小心”表示留神避免危险，不能表示结交朋友。"}, {"text": "请小心，这本书很好看。", "explanation": "这里应该用〈看看〉。“小心”用于提醒危险或错误，“书很好看”没有危险。"}, {"text": "我很小心明天的考试。", "explanation": "这里应该用〈担心〉。“小心”指留神避免出错，表示忧虑要用“担心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地上有水，你走路要小心到。", "corrected_sentence": "地上有水，你走路要小心。", "error_description": "“小心”后面不能加结果补语“到”，应去掉“到”，说“走路要小心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨天路滑，你骑车要小心过。", "corrected_sentence": "雨天路滑，你骑车要小心。", "error_description": "“过”误用：提醒将来要注意时，“小心”后不能加经历体“过”，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60712c0e-0dcd-4c4e-a88a-dfa46e937ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
