INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去常用的、没有改变的方法。", "primary_collocate": null, "pronunciation": "lǎo bàn fǎ", "ipa": "lɑʊ˨˩ pan˥˩ fa˨˩", "syllable_count": 3, "sentences": [{"text": "现在，年轻人也学这些老办法。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个老办法很简单，大家都会用。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶还是用老办法洗衣服。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机器坏了，我们只好用老办法。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，种地还是老办法最好。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢新方法，总是用老办法做饭。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老办法已经用了一百年。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没有信号，我们用老办法看地图。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校还用老办法教汉字，让学生一遍一遍地写。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老办法有时候比新办法更好用。", "target_word": "老办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "老辦法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "老办法：过去一直在用、没有改变的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7b8f82-bb2e-4b85-bf5b-cf3555f41d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老办法", "is_correct": true, "explanation": "老办法：此处是名词，指过去一直用、没有改变的方法，与“年轻人也学”相合。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“学”的对象应是知识、技能，不能说学空调。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”指人，不是可以学习的内容，句意不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”指场所，不是可学的东西，句子不成立。"}], "explanations": {"老办法": "老办法：此处是名词，指过去一直用、没有改变的方法，与“年轻人也学”相合。", "空调": "搭配：“学”的对象应是知识、技能，不能说学空调。", "老人": "语义：“老人”指人，不是可以学习的内容，句意不通。", "食堂": "语义：“食堂”指场所，不是可学的东西，句子不成立。"}, "sentence_index": 0, "correct_answer": "老办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他又犯了老办法，每次都迟到。", "explanation": "这里应该用〈老毛病〉。“犯”后面接的是“老毛病”这类缺点，老办法指方法，不指缺点。"}, {"text": "他是我们班的老办法，大家都很喜欢他。", "explanation": "这里应该用〈老同学〉。老办法指方法，不指人，不能用来指同学。"}, {"text": "我们是几十年的老办法了。", "explanation": "这里应该用〈老朋友〉。老办法指方法，不指人，不能用来形容交情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老办法", "is_correct": true, "explanation": "老办法：此处是名词，指一直沿用的方法，与“已经用了一百年”相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不是可以使用的东西，“这个心情已经用了一百年”句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被使用，句子不成立。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“用”的宾语不能是“情绪”，说“用情绪”不成搭配。"}], "explanations": {"老办法": "老办法：此处是名词，指一直沿用的方法，与“已经用了一百年”相合。", "心情": "语义：“心情”不是可以使用的东西，“这个心情已经用了一百年”句意不通。", "天气": "语义：“天气”不能被使用，句子不成立。", "情绪": "搭配：“用”的宾语不能是“情绪”，说“用情绪”不成搭配。"}, "sentence_index": 6, "correct_answer": "老办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅是老办法，已经开了一百年。", "explanation": "这里应该用〈老字号〉。老办法指方法，不指店铺，不能用来形容店面。"}, {"text": "我们约在老办法见面。", "explanation": "这里应该用〈老地方〉。老办法指方法，不指地点，不能用来表示见面的场所。"}, {"text": "我们搬进了老办法。", "explanation": "这里应该用〈老房子〉。老办法指方法，不指房屋，不能搬进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只老办法，大家都会用。", "corrected_sentence": "这是一个老办法，大家都会用。", "error_description": "“老办法”的量词应为“个”，不能用“只”（“只”多用于动物等）。错误：“一只老办法”。正确：“这是一个老办法，大家都会用。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶一直用得老办法。", "corrected_sentence": "奶奶一直用着老办法。", "error_description": "“用”后面接“得”引出补语，但这里没有补语，应该用“着”表示动作持续的状态。错误：“用得老办法”。正确：“奶奶一直用着老办法。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19bcd43-4461-44fd-87b7-17085f870e81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "反义：“浪费”与“节约”相对，指不珍惜地使用资源。"}, {"text": "挖掘", "is_correct": false, "explanation": "无反义关系：“挖掘”指挖出或发掘，与节约用水不相对。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指慢慢地走，与用水无关。"}, {"text": "栽种", "is_correct": false, "explanation": "无反义关系：“栽种”指种植，与节约用水无关。"}], "correct_answer": "浪费", "explanations": {"浪费": "反义：“浪费”与“节约”相对，指不珍惜地使用资源。", "挖掘": "无反义关系：“挖掘”指挖出或发掘，与节约用水不相对。", "散步": "无反义关系：“散步”指慢慢地走，与用水无关。", "栽种": "无反义关系：“栽种”指种植，与节约用水无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "反义：“浪费”与“节约”相对，指不珍惜地使用资源。"}, {"text": "驾驶", "is_correct": false, "explanation": "无反义关系：“驾驶”指操纵车辆，与节约用水不相对。"}, {"text": "讲述", "is_correct": false, "explanation": "无反义关系：“讲述”指把事情说出来，与用水无关。"}, {"text": "绘画", "is_correct": false, "explanation": "无反义关系：“绘画”指画画，与节约用水不相对。"}], "correct_answer": "浪费", "explanations": {"浪费": "反义：“浪费”与“节约”相对，指不珍惜地使用资源。", "驾驶": "无反义关系：“驾驶”指操纵车辆，与节约用水不相对。", "讲述": "无反义关系：“讲述”指把事情说出来，与用水无关。", "绘画": "无反义关系：“绘画”指画画，与节约用水不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指合理使用水资源，避免浪费的行为。", "primary_collocate": null, "pronunciation": "jié yuē yòng shuǐ", "ipa": "tɕjɛ˧˥ ɥɛ˧˥ jʊŋ˥˩ ʂweɪ˨˩˦", "syllable_count": 4, "sentences": [{"text": "在一些干旱的地区，人们很早就学会了如何节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "夏天天气热，我们要节约用水。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师告诉学生要节约用水。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刷牙的时候关上水龙头，也是节约用水。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节约用水对每个人都很重要。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家用洗菜的水冲厕所，可以节约用水。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水很少的地方，大家更要节约用水。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈常常提醒我节约用水。", "target_word": "节约用水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节约用水是一个好习惯。", "target_word": "节约用水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水费越来越贵，我们家每天都注意节约用水。", "target_word": "节约用水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "合理用水、不浪费水资源的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”与干旱地区的节水做法相反，句意矛盾。"}, {"text": "节约用水", "is_correct": true, "explanation": "正确：干旱地区人们学会的是“节约用水”，与“很早就学会了”的语境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：人不能“学会如何下雨”，句子说不通。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：“挥霍”指毫无节制地浪费，与干旱地区人们学会的做法相反，句意矛盾。"}], "explanations": {"浪费": "语义：“浪费”与干旱地区的节水做法相反，句意矛盾。", "节约用水": "正确：干旱地区人们学会的是“节约用水”，与“很早就学会了”的语境相符。", "下雨": "语义：人不能“学会如何下雨”，句子说不通。", "挥霍": "语义：“挥霍”指毫无节制地浪费，与干旱地区人们学会的做法相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "节约用水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电视机每天都节约用水。", "explanation": "这里应该用〈省电〉。电视机不用水，“节约用水”只能指减少用水；说减少用电要用“省电”。"}, {"text": "这盏台灯每天都节约用水。", "explanation": "这里应该用〈省电〉。台灯不用水，“节约用水”不能用于不用水的物品；说减少用电要用“省电”。"}, {"text": "这台电风扇每天都节约用水。", "explanation": "这里应该用〈省电〉。电风扇不用水，“节约用水”不能用于它；说减少用电要用“省电”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "泼水", "is_correct": false, "explanation": "语义：“泼水”与水少、需要节约的语境相反。"}, {"text": "玩水", "is_correct": false, "explanation": "语义：水少的地方大家不会“玩水”，句意矛盾。"}, {"text": "提高", "is_correct": false, "explanation": "配价：“提高”是及物动词，需带“效率”“水平”等宾语，“更要提高”缺少宾语。"}, {"text": "节约用水", "is_correct": true, "explanation": "正确：水少的地方“大家更要节约用水”，与“更要”的语气一致。"}], "explanations": {"泼水": "语义：“泼水”与水少、需要节约的语境相反。", "玩水": "语义：水少的地方大家不会“玩水”，句意矛盾。", "提高": "配价：“提高”是及物动词，需带“效率”“水平”等宾语，“更要提高”缺少宾语。", "节约用水": "正确：水少的地方“大家更要节约用水”，与“更要”的语气一致。"}, "sentence_index": 6, "correct_answer": "节约用水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台空调很节约用水，一个月电费很少。", "explanation": "这里应该用〈省电〉。“节约用水”只指少用水，说空调少用电要用“省电”。"}, {"text": "这辆车很节约用水，一百公里只用五升油。", "explanation": "这里应该用〈省油〉。“节约用水”只指少用水，说汽车少耗油要用“省油”。"}, {"text": "他洗澡一洗就是一个小时，真节约用水。", "explanation": "这里应该用〈浪费水〉。长时间洗澡是多用水，“节约用水”意思正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区为了节约用水的，安装了新的水表。", "corrected_sentence": "这个小区为了节约用水，安装了新的水表。", "error_description": "错误：“为了节约用水的”；正确：“为了节约用水”。“为了”引出的目的成分是动词短语，“节约用水”后面不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从小就了节约用水，到现在还在坚持。", "corrected_sentence": "我从小就节约用水，到现在还在坚持。", "error_description": "错误：“就了节约用水”；正确：“就节约用水”。“了”是完成标记，不能放在动词短语前面，此处不需要任何时态标记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12757, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "反义：“失传”指传承中断，与“代代相传”相对。"}, {"text": "漂流", "is_correct": false, "explanation": "无反义关系：“漂流”指随水流移动，与传承无关。"}, {"text": "绘制", "is_correct": false, "explanation": "无反义关系：“绘制”指画出图样，与传承无关。"}, {"text": "游览", "is_correct": false, "explanation": "无反义关系：“游览”指参观风景，与传承无关。"}], "correct_answer": "失传", "explanations": {"失传": "反义：“失传”指传承中断，与“代代相传”相对。", "漂流": "无反义关系：“漂流”指随水流移动，与传承无关。", "绘制": "无反义关系：“绘制”指画出图样，与传承无关。", "游览": "无反义关系：“游览”指参观风景，与传承无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
