INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在土地上播种、耕作、管理农作物，以获取收成的农业活动。", "primary_collocate": null, "pronunciation": "zhòng dì", "ipa": "ʈʂʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "过去没有现代技术，农民依靠雨水种地。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷在农村种地，每年秋天都有好收成。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想去城里工作，回家种地了。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种地很辛苦，夏天太阳大，农民还要下田。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家有五亩田，一家人靠种地生活。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多农民用机器种地，比以前轻松多了。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，村里人都忙着种地。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想种地有收成，天气和雨水都很重要。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后回到老家，开始学习种地。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种地的人起得早，天一亮就下田。", "target_word": "种地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种了地", "label": "体标（了）"}, {"form": "种过地", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "在土地上播种耕作以获得收成的农业活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12758, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种地", "is_correct": true, "explanation": "正确：种地，指在土地上播种、耕作。"}, {"text": "重大", "is_correct": false, "explanation": "dà（第四声）与 dì（第四声）韵母不同，意思是重大、重要。"}, {"text": "重力", "is_correct": false, "explanation": "lì 与 dì 声母不同（l／d），声调相同，意思是重力。"}, {"text": "重度", "is_correct": false, "explanation": "dù（第四声）与 dì（第四声）韵母不同，意思是程度深、严重。"}], "explanations": {"种地": "正确：种地，指在土地上播种、耕作。", "重大": "dà（第四声）与 dì（第四声）韵母不同，意思是重大、重要。", "重力": "lì 与 dì 声母不同（l／d），声调相同，意思是重力。", "重度": "dù（第四声）与 dì（第四声）韵母不同，意思是程度深、严重。"}, "sentence_index": null, "correct_answer": "种地"}, "level_3": {"options": [{"text": "种地", "is_correct": true, "explanation": "正确：农民依靠雨水在土地上耕种，与句意一致。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指到单位工作，与依靠雨水的农业生活不符。"}, {"text": "烧饭", "is_correct": false, "explanation": "语义：雨水不能用来做饭，“依靠雨水烧饭”说不通。"}, {"text": "织布", "is_correct": false, "explanation": "搭配：“织布”需要纱线和织机，不说依靠雨水。"}], "explanations": {"种地": "正确：农民依靠雨水在土地上耕种，与句意一致。", "上班": "语义：“上班”指到单位工作，与依靠雨水的农业生活不符。", "烧饭": "语义：雨水不能用来做饭，“依靠雨水烧饭”说不通。", "织布": "搭配：“织布”需要纱线和织机，不说依靠雨水。"}, "sentence_index": 0, "correct_answer": "种地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工厂里种地，每天按时上下班。", "explanation": "这里应该用〈打工〉。种地指在土地上耕种，在工厂工作不能说种地。"}, {"text": "渔民每天早上去海上种地，回来卖鱼。", "explanation": "这里应该用〈捕鱼〉。种地要在陆地的田地里进行，海上作业要说捕鱼。"}, {"text": "妈妈在阳台上种地，种了很多番茄。", "explanation": "这里应该用〈种菜〉。种地指在大片田地里耕种粮食，阳台上种番茄要说种菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种地", "is_correct": true, "explanation": "正确：春天农忙时，村里人都在田里种地，与句意一致。"}, {"text": "过冬", "is_correct": false, "explanation": "语义：“过冬”是冬季的活动，与“春天一到”的语境相反。"}, {"text": "滑雪", "is_correct": false, "explanation": "搭配：“滑雪”需要雪地和雪场，春天的农村没有这样的条件。"}, {"text": "烤火", "is_correct": false, "explanation": "语义：“烤火”多用于寒冷的季节，与春天不符。"}], "explanations": {"种地": "正确：春天农忙时，村里人都在田里种地，与句意一致。", "过冬": "语义：“过冬”是冬季的活动，与“春天一到”的语境相反。", "滑雪": "搭配：“滑雪”需要雪地和雪场，春天的农村没有这样的条件。", "烤火": "语义：“烤火”多用于寒冷的季节，与春天不符。"}, "sentence_index": 6, "correct_answer": "种地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上去市场种地，然后回家吃饭。", "explanation": "这里应该用〈卖菜〉。种地指在土地上耕种，去市场做买卖要说卖菜。"}, {"text": "奶奶每天在鸡舍里种地，然后给鸡喂食。", "explanation": "这里应该用〈养鸡〉。种地指在田地里耕作，在鸡舍里饲养鸡要说养鸡，不能说种地。"}, {"text": "这个老师每天在学校里种地，教学生画画。", "explanation": "这里应该用〈教书〉。种地指耕种土地，在学校教学生画画要说教书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我奶奶年轻时很种地，家里有一块地。", "corrected_sentence": "我奶奶年轻时种地，家里有一块地。", "error_description": "错误：程度副词“很”不能修饰动词短语“种地”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他种地得很好，每年都有好收成。", "corrected_sentence": "他种地种得很好，每年都有好收成。", "error_description": "补语“得很好”前要重复动词，应说“种地种得很好”。只说“种地得很好”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短时间", "is_correct": true, "explanation": "正确：“短时间”与“长时间”在时间跨度上相对，是这一义项的反义词。"}, {"text": "水果", "is_correct": false, "explanation": "无关：“水果”指具体的食物，与时间跨度没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”指大气状况，与时间跨度没有反义关系。"}, {"text": "文化", "is_correct": false, "explanation": "无关：“文化”指社会的知识与习俗，与时间跨度没有反义关系。"}], "correct_answer": "短时间", "explanations": {"短时间": "正确：“短时间”与“长时间”在时间跨度上相对，是这一义项的反义词。", "水果": "无关：“水果”指具体的食物，与时间跨度没有反义关系。", "天气": "无关：“天气”指大气状况，与时间跨度没有反义关系。", "文化": "无关：“文化”指社会的知识与习俗，与时间跨度没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短时间", "is_correct": true, "explanation": "正确：“短时间”与“长时间”在时间跨度上相对，是这一义项的反义词。"}, {"text": "礼物", "is_correct": false, "explanation": "无关：“礼物”指送人的东西，与时间跨度没有反义关系。"}, {"text": "银行", "is_correct": false, "explanation": "无关：“银行”指金融机构，与时间跨度没有反义关系。"}, {"text": "运动", "is_correct": false, "explanation": "无关：“运动”指身体活动，与时间跨度没有反义关系。"}], "correct_answer": "短时间", "explanations": {"短时间": "正确：“短时间”与“长时间”在时间跨度上相对，是这一义项的反义词。", "礼物": "无关：“礼物”指送人的东西，与时间跨度没有反义关系。", "银行": "无关：“银行”指金融机构，与时间跨度没有反义关系。", "运动": "无关：“运动”指身体活动，与时间跨度没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指较长的时间跨度。", "primary_collocate": null, "pronunciation": "cháng shí jiān", "ipa": "ʈʂʰɑŋ˧˥ ʂɨ˧˥ tɕjɛn˥˥", "syllable_count": 3, "sentences": [{"text": "如果长时间不下雨，庄稼就会干死。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "长时间看手机对眼睛不好。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长时间没有回家，妈妈很想他。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间坐着不动，腰会很疼。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事需要长时间的练习。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过长时间的等待，车终于来了。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她长时间在国外工作，很少见朋友。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间不运动，身体会变差。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们长时间没见面了，最近好吗？", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间开车很累，我们休息一下吧。", "target_word": "长时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "较长的时间跨度，常作状语或定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长时间", "is_correct": true, "explanation": "正确：“长时间”指较长的时间跨度，与“不下雨、庄稼干死”所需的持续时间相符。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：“片刻”指极短的一瞬间，几刻钟不下雨庄稼不会干死，与后半句的结果矛盾。"}, {"text": "短时间", "is_correct": false, "explanation": "语义：“短时间”说时间很短，不足以使庄稼干死，与“会干死”的结果相冲突。"}, {"text": "土壤", "is_correct": false, "explanation": "语义：“土壤”是地面的泥土，本身不能作“不下雨”的主语，句子无法成立。"}], "explanations": {"长时间": "正确：“长时间”指较长的时间跨度，与“不下雨、庄稼干死”所需的持续时间相符。", "片刻": "语义：“片刻”指极短的一瞬间，几刻钟不下雨庄稼不会干死，与后半句的结果矛盾。", "短时间": "语义：“短时间”说时间很短，不足以使庄稼干死，与“会干死”的结果相冲突。", "土壤": "语义：“土壤”是地面的泥土，本身不能作“不下雨”的主语，句子无法成立。"}, "sentence_index": 0, "correct_answer": "长时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长时间到达了北京。", "explanation": "这里应该用〈很快〉。“到达”是瞬间完成的动作，不能用“长时间”修饰；表示速度要用“很快”。"}, {"text": "他长时间地看了一眼手机，就放下了。", "explanation": "这里应该用〈片刻〉。“看一眼”只需极短的时间，与表示持续很久的“长时间”相冲突；应说“看了片刻手机”。"}, {"text": "我们约好在长时间见面。", "explanation": "“约好在……见面”需要一个具体的时间点，“长时间”只说持续的跨度，不能充当时间点；应改用“明天下午”之类的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长时间", "is_correct": true, "explanation": "正确：“长时间”强调工作持续的时间跨度，与“很少见朋友”相呼应。"}, {"text": "时候", "is_correct": false, "explanation": "搭配：“时候”是时间名词，不能直接作“工作”的修饰成分，“她时候在国外工作”不成立。"}, {"text": "一刻", "is_correct": false, "explanation": "语义：“一刻”只有十五分钟左右，不能说明在国外工作的持续状况，与“很少见朋友”的长期效果不符。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”指极短的一刹那，工作不能瞬间完成，与句中的长期工作状况冲突。"}], "explanations": {"长时间": "正确：“长时间”强调工作持续的时间跨度，与“很少见朋友”相呼应。", "时候": "搭配：“时候”是时间名词，不能直接作“工作”的修饰成分，“她时候在国外工作”不成立。", "一刻": "语义：“一刻”只有十五分钟左右，不能说明在国外工作的持续状况，与“很少见朋友”的长期效果不符。", "瞬间": "语义：“瞬间”指极短的一刹那，工作不能瞬间完成，与句中的长期工作状况冲突。"}, "sentence_index": 6, "correct_answer": "长时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的长时间正合适。", "explanation": "这里应该用〈长度〉。“长时间”指时间的跨度，绳子的长短要用“长度”表示。"}, {"text": "我们一起度过了一只长时间。", "explanation": "“只”多用于动物或个别物品，时间跨度要用“段”来计量，应说“一段很长的时间”。"}, {"text": "他个子很长时间，所以坐在后面。", "explanation": "这里应该用〈高〉。描述身高要用“高”，“长时间”只说时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们长时间了没有联系，你还好吗？", "corrected_sentence": "我们长时间没有联系，你还好吗？", "error_description": "错误形式：“长时间了没有联系”。正确形式：“长时间没有联系”。“长时间”作状语直接修饰后面的动词短语，中间不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我花了很长时间的才做完作业。", "corrected_sentence": "我花了很长时间才做完作业。", "error_description": "错误形式：“很长时间的才做完”。正确形式：“很长时间才做完”。“很长时间”之后多出的“的”没有意义，句子不成立，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
