INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12763, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指某个地方或地区的居民。", "primary_collocate": null, "pronunciation": "dāng dì rén", "ipa": "tɑŋ˥˥ ti˥˩ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "为了应对这个问题，当地人发展出许多传统的资源管理方式。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "当地人都喜欢吃这种面。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问当地人怎么去车站。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人说，这里冬天很冷。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住了十年，已经像当地人一样了。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去旅行时，我常跟当地人聊天。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人欢迎每一个客人。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的客人多是当地人。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人带我们去看了老城。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人是当地人，知道很多故事。", "target_word": "当地人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位当地人", "label": "量词"}], "register": "中性", "sense_fingerprint": "某个地方或地区的居民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12763, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当地人", "is_correct": true, "explanation": "正确：“当地人”指本地居民，是发展当地资源管理方式的主体。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”是短期来访者，不会发展当地的传统资源管理方式。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“发展”需要有生命的施事，“天气”不能作其主语。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”不具备发展传统资源管理方式的能力，与“传统”的成熟经验不符。"}], "explanations": {"当地人": "正确：“当地人”指本地居民，是发展当地资源管理方式的主体。", "游客": "语义：“游客”是短期来访者，不会发展当地的传统资源管理方式。", "天气": "配价：“发展”需要有生命的施事，“天气”不能作其主语。", "孩子": "语义：“孩子”不具备发展传统资源管理方式的能力，与“传统”的成熟经验不符。"}, "sentence_index": 0, "correct_answer": "当地人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些当地人刚来这里，还不习惯。", "explanation": "这里应该用〈外地人〉。“当地人”指本地居民，刚来这里的人应说“外地人”。"}, {"text": "我在路上遇到一只当地人，他很热情。", "explanation": "“只”多用于动物，指人要用“位”或“个”，应说“一位当地人”。"}, {"text": "我点了一份当地人，味道很好。", "explanation": "这里应该用〈当地菜〉。食物要用“当地菜”，“当地人”指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当地人", "is_correct": true, "explanation": "正确：“当地人”能够欢迎客人，是句子的合适主语。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“欢迎”需要有生命的施事，“空气”不能欢迎客人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是无生命的物体，无法欢迎客人，句子不成立。"}, {"text": "数据", "is_correct": false, "explanation": "语义：“数据”是抽象的信息，不是能主动欢迎客人的主体。"}], "explanations": {"当地人": "正确：“当地人”能够欢迎客人，是句子的合适主语。", "空气": "配价：“欢迎”需要有生命的施事，“空气”不能欢迎客人。", "桌子": "语义：“桌子”是无生命的物体，无法欢迎客人，句子不成立。", "数据": "语义：“数据”是抽象的信息，不是能主动欢迎客人的主体。"}, "sentence_index": 6, "correct_answer": "当地人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车是当地人，停在路边。", "explanation": "这里应该用〈本地产〉。“当地人”指人，不能用来说车；说车子产自本地，应说“本地产的车”。"}, {"text": "我每年都回当地人过年。", "explanation": "这里应该用〈老家〉。“回……过年”要回到一个地方，“当地人”指人，不能充当回去的地点；应说“回老家过年”。"}, {"text": "我们一起去当地人旅游了。", "explanation": "这里应该用〈外地〉。“当地人”指人，不能充当去旅游的地点；去别的地方旅游应说“去外地旅游”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三个当地人们带我们去看了老城。", "corrected_sentence": "三个当地人带我们去看了老城。", "error_description": "错误形式：“三个当地人们”。正确形式：“三个当地人”。名词前已有数量词时，不能再加表示复数的“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当地人地热情让我很感动。", "corrected_sentence": "当地人的热情让我很感动。", "error_description": "错误形式：“当地人地热情”。正确形式：“当地人的热情”。修饰名词要用“的”，这里误用了表示状语的“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
