INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把分散的东西集中起来。", "primary_collocate": null, "pronunciation": "shōu jí", "ipa": "ʂoʊ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "例如，有些社区会在雨季时把雨水收集起来，储存在地下的水窖里。", "target_word": "收集", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他把地上的树叶收集起来，放进袋子里。", "target_word": "收集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家收集一些旧报纸。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在网上收集了很多旅行的资料。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在收集证据。", "target_word": "收集", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她每天放学后收集空瓶子。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想收集大家对新产品的意见。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们收集好数据后，开始写报告。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把大家的作业收集一下，交给老师。", "target_word": "收集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在现场收集消息。", "target_word": "收集", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "收集了", "label": "体标（完成）"}, {"form": "收集过", "label": "体标（经历）"}, {"form": "收集着", "label": "体标（持续）"}, {"form": "收集起来", "label": "复合（趋向）"}], "register": "中性", "sense_fingerprint": "收集：把分散的东西、资料集中到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。收集（shōu jí）指把分散的东西集中起来。"}, {"text": "手机", "is_correct": false, "explanation": "手（shǒu）与收（shōu）声调不同，“手机”指手持的电话。"}, {"text": "收寄", "is_correct": false, "explanation": "寄（jì）与集（jí）声调不同，意思是收取并寄出邮件。"}, {"text": "手记", "is_correct": false, "explanation": "手记（shǒu jì）两个音节的声调都与收集不同，意思是亲手写下的记录。"}], "explanations": {"收集": "正确。收集（shōu jí）指把分散的东西集中起来。", "手机": "手（shǒu）与收（shōu）声调不同，“手机”指手持的电话。", "收寄": "寄（jì）与集（jí）声调不同，意思是收取并寄出邮件。", "手记": "手记（shǒu jì）两个音节的声调都与收集不同，意思是亲手写下的记录。"}, "sentence_index": null, "correct_answer": "收集"}, "level_3": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。“把雨水收集起来”指把分散的雨水集中起来，再储存。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：蒸发会让雨水消失，与后面“储存在地下的水窖里”相矛盾。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”不用于“把……起来”的结构，且与“储存”的意思相反。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染会使雨水变脏，不能用于储存雨水。"}], "explanations": {"收集": "正确。“把雨水收集起来”指把分散的雨水集中起来，再储存。", "蒸发": "语义：蒸发会让雨水消失，与后面“储存在地下的水窖里”相矛盾。", "浪费": "搭配：“浪费”不用于“把……起来”的结构，且与“储存”的意思相反。", "污染": "语义：污染会使雨水变脏，不能用于储存雨水。"}, "sentence_index": 0, "correct_answer": "收集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈下班后在收集厨房。", "explanation": "这里应该用〈收拾〉。收集是把分散的东西聚到一起，不用于整理房间。"}, {"text": "公司正在收集新员工。", "explanation": "这里应该用〈招募〉。收集用于东西、资料、意见等，不用于招人。"}, {"text": "公司收集了一家小工厂。", "explanation": "这里应该用〈收购〉。收购指买下企业，收集指把零散的东西聚到一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12765, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。收集（shōu jí）指把分散的东西集中起来。"}, {"text": "兽迹", "is_correct": false, "explanation": "兽（shòu）与收声调不同，迹（jì）与集声调不同，意思是野兽留下的足迹。"}, {"text": "手迹", "is_correct": false, "explanation": "手（shǒu）与收（shōu）声调不同，迹（jì）与集（jí）声调不同，意思是亲手写的字。"}, {"text": "首级", "is_correct": false, "explanation": "首（shǒu）与收声调不同，意思是古代战争中割下的敌人头颅。"}], "explanations": {"收集": "正确。收集（shōu jí）指把分散的东西集中起来。", "兽迹": "兽（shòu）与收声调不同，迹（jì）与集声调不同，意思是野兽留下的足迹。", "手迹": "手（shǒu）与收（shōu）声调不同，迹（jì）与集（jí）声调不同，意思是亲手写的字。", "首级": "首（shǒu）与收声调不同，意思是古代战争中割下的敌人头颅。"}, "sentence_index": null, "correct_answer": "收集"}, "level_3": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。“收集大家的意见”指把大家的意见集中起来。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、物品，不说“修理意见”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃大家的意见”。"}, {"text": "废除", "is_correct": false, "explanation": "语义：“废除”用于制度、规定，与“新产品的意见”不搭配。"}], "explanations": {"收集": "正确。“收集大家的意见”指把大家的意见集中起来。", "修理": "搭配：“修理”的对象是机器、物品，不说“修理意见”。", "吃": "搭配：“吃”的对象是食物，不能说“吃大家的意见”。", "废除": "语义：“废除”用于制度、规定，与“新产品的意见”不搭配。"}, "sentence_index": 6, "correct_answer": "收集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他毕业后一直在收集一份好工作。", "explanation": "这里应该用〈找〉或〈争取〉。收集指把分散的东西聚到一起，不用于找工作或获得工作。"}, {"text": "这只受伤的小狗被好心人收集了。", "explanation": "这里应该用〈收留〉。收留用于收容人或动物，收集只用于分散的东西。"}, {"text": "政府对烟草收集重税。", "explanation": "这里应该用〈征收〉。征收指国家依法收取税款，收集不用于收税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每个周末都会旧衣服收集起来，送给山区的孩子。", "corrected_sentence": "我每个周末都会把旧衣服收集起来，送给山区的孩子。", "error_description": "错误：“旧衣服收集起来”，缺少“把”字，处置式中宾语前必须加“把”。正确：“把旧衣服收集起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我收集了过很多旧报纸。", "corrected_sentence": "我收集过很多旧报纸。", "error_description": "错误：“收集了过”，同时用了“了”和“过”。正确：“收集过”，表示有过这种经历，不能与“了”同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
