INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从躺、坐等状态转换为站立的状态。", "primary_collocate": null, "pronunciation": "qǐ lái", "ipa": "tɕʰi˨˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "地上很凉，你快起来吧。", "target_word": "起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从沙发上起来，去开门。", "target_word": "起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人坐了很久，慢慢起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家都起来，我们一起唱国歌。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子躺在地上哭，妈妈叫他起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他摔倒了，但是很快就起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别躺着了，起来走走吧。", "target_word": "起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到老师的名字，他马上从座位上起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说病人今天可以起来走路。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家坐了一个小时，都起来活动活动。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "起来了", "label": "体标"}], "register": "口语", "sense_fingerprint": "从躺或坐的状态变为站立；起身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示从躺或坐变为站立，符合“地上很凉，你快……吧”劝人起身的语境。"}, {"text": "躺", "is_correct": false, "explanation": "语义：地上很凉时劝人“快躺吧”与语境相反，躺卧不是离开凉地的动作。"}, {"text": "蹲", "is_correct": false, "explanation": "搭配：“快……吧”劝人离开地面时，不能说“快蹲吧”。"}, {"text": "跪", "is_correct": false, "explanation": "语义：“跪”是屈膝着地，与“地上很凉”劝人离开地面的语境不合。"}], "explanations": {"起来": "起来：表示从躺或坐变为站立，符合“地上很凉，你快……吧”劝人起身的语境。", "躺": "语义：地上很凉时劝人“快躺吧”与语境相反，躺卧不是离开凉地的动作。", "蹲": "搭配：“快……吧”劝人离开地面时，不能说“快蹲吧”。", "跪": "语义：“跪”是屈膝着地，与“地上很凉”劝人离开地面的语境不合。"}, "sentence_index": 0, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他困了，就上床起来睡觉了。", "explanation": "这里应该用〈躺下〉。睡觉要躺下，“起来”是起身，方向相反。"}, {"text": "他走累了，在路边的椅子上起来休息。", "explanation": "这里应该用〈坐下〉。在椅子上休息是坐下，“起来”是从坐变为站。"}, {"text": "早上六点，太阳从东边起来了。", "explanation": "这里应该用〈升起〉。“起来”指人起身，太阳出来要说“升起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示从躺卧变为起身，符合“你别躺着了，……走走吧”的语境。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”不能与“走走”连用表示起身后活动。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”只表示站立不动，与“走走”的活动义不合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：前文已说“你别躺着了”，“睡”与躺卧的语境重复，且与“走走”不合。"}], "explanations": {"起来": "起来：表示从躺卧变为起身，符合“你别躺着了，……走走吧”的语境。", "坐": "搭配：“坐”不能与“走走”连用表示起身后活动。", "站": "语义：“站”只表示站立不动，与“走走”的活动义不合。", "睡": "语义：前文已说“你别躺着了”，“睡”与躺卧的语境重复，且与“走走”不合。"}, "sentence_index": 6, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天很晚了，他关了灯，在床上起来睡了。", "explanation": "这里应该用〈躺下〉。睡觉要躺下，“起来”是起身。"}, {"text": "我腿很疼，想在沙发上起来一会儿。", "explanation": "这里应该用〈坐〉。腿疼要坐着休息，“起来”是站起身。"}, {"text": "气球慢慢起来了，飞上了天。", "explanation": "这里应该用〈升〉。物体向上飞要说“升起来”，单用“起来”指人起身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到铃声，他马上起来着。", "corrected_sentence": "听到铃声，他马上起来了。", "error_description": "错误形式：“起来着”；正确形式：“起来了”。起身是一下完成的动作，用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从椅子上起来的，给客人倒水。", "corrected_sentence": "他从椅子上起来，给客人倒水。", "error_description": "错误形式：“起来的，给客人倒水”；正确形式：“起来，给客人倒水”。“起来”后直接接后续动作，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
