INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水窖是干旱地区用来储存雨水的设施，通常建在地下。", "primary_collocate": null, "pronunciation": "shuǐ jiào", "ipa": "ʂweɪ˨˩˦ tɕjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，有些社区会在雨季时把雨水收集起来，储存在地下的水窖里。", "target_word": "水窖", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个村子在山上，家家都有水窖。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民把雨水存在水窖里。", "target_word": "水窖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱的地方常常挖水窖存水。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在院子里挖了一个大水窖。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水窖里的水很干净，可以喝。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，水窖里又有水了。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶每天从水窖里打水做饭。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水窖上面盖着木板，孩子不会掉下去。", "target_word": "水窖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了有水喝，他们修了三个水窖。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "口", "label": "量词"}], "register": "中性", "sense_fingerprint": "水窖：干旱地区建在地下、储存雨水的设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12767, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水窖", "is_correct": true, "explanation": "正确。水窖（shuǐ jiào）指干旱地区用来储存雨水的地下设施。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡（shuì）与水（shuǐ）声调不同，意思是睡眠。"}, {"text": "水饺", "is_correct": false, "explanation": "饺（jiǎo）与窖（jiào）声调不同，意思是饺子。"}, {"text": "水胶", "is_correct": false, "explanation": "胶（jiāo）与窖（jiào）声调不同，意思是一种胶水。"}], "explanations": {"水窖": "正确。水窖（shuǐ jiào）指干旱地区用来储存雨水的地下设施。", "睡觉": "睡（shuì）与水（shuǐ）声调不同，意思是睡眠。", "水饺": "饺（jiǎo）与窖（jiào）声调不同，意思是饺子。", "水胶": "胶（jiāo）与窖（jiào）声调不同，意思是一种胶水。"}, "sentence_index": null, "correct_answer": "水窖"}, "level_3": {"options": [{"text": "水窖", "is_correct": true, "explanation": "正确。“储存在地下的水窖里”指储存雨水的地下设施。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来保存食物，不在地下，与“地下的……里”不符。"}, {"text": "水塔", "is_correct": false, "explanation": "语义：水塔建在地面高处，与“地下”的位置不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包用来装书本，不能用来储存雨水。"}], "explanations": {"水窖": "正确。“储存在地下的水窖里”指储存雨水的地下设施。", "冰箱": "语义：冰箱用来保存食物，不在地下，与“地下的……里”不符。", "水塔": "语义：水塔建在地面高处，与“地下”的位置不符。", "书包": "语义：书包用来装书本，不能用来储存雨水。"}, "sentence_index": 0, "correct_answer": "水窖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼的水窖把水送到了十层。", "explanation": "这里应该用〈水塔〉。水塔靠高处供水，水窖是地下储存雨水的设施，不负责把水送上楼。"}, {"text": "周末我们在水窖里划船，玩得很开心。", "explanation": "这里应该用〈水库〉或〈湖〉。水窖是小型的地下储水设施，不能划船，划船要用水库或湖这样的大水域。"}, {"text": "奶奶在水窖里煮了一锅面条。", "explanation": "这里应该用〈锅〉或〈炉子〉。水窖是储存雨水的设施，不能用来煮食物，煮面要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水窖", "is_correct": true, "explanation": "正确。“下雨以后，水窖里又有水了”指雨水流入后水窖里又有水。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“面包里”一般不说“有水”，与“下雨以后”的语境也不合。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，不会因为下雨而“又有水了”。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“饼干里”一般不说“有水”，与下雨的语境不合。"}], "explanations": {"水窖": "正确。“下雨以后，水窖里又有水了”指雨水流入后水窖里又有水。", "面包": "搭配：“面包里”一般不说“有水”，与“下雨以后”的语境也不合。", "字典": "语义：字典是书，不会因为下雨而“又有水了”。", "饼干": "搭配：“饼干里”一般不说“有水”，与下雨的语境不合。"}, "sentence_index": 6, "correct_answer": "水窖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把腌好的咸菜装进了水窖里。", "explanation": "这里应该用〈坛子〉。咸菜一般腌在坛子里，水窖是储存雨水的地下设施，不用于盛放食物。"}, {"text": "夏天，小孩子常在水窖里洗澡。", "explanation": "这里应该用〈澡盆〉或〈浴缸〉。澡盆用于洗澡，水窖是储存雨水的地下设施，不能用来洗澡。"}, {"text": "他们在水窖里盖了一间房子，全家都住在里面。", "explanation": "这里应该用〈窑洞〉。窑洞可以住人，水窖只用于储存雨水，不能住人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在山坡上挖了两只水窖。", "corrected_sentence": "他们在山坡上挖了两个水窖。", "error_description": "错误：“两只水窖”，“只”用于动物或成对物品中的一个。正确：“两个水窖”，水窖的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里人一起修了三个的水窖。", "corrected_sentence": "村里人一起修了三个水窖。", "error_description": "错误：“三个的水窖”，数量短语与名词之间不加“的”。正确：“三个水窖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
