INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示等待直到某一时刻或某一事件发生。", "primary_collocate": null, "pronunciation": "děng dào", "ipa": "tɤŋ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "等到水开了，再把面条放进去。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到天黑了，我们再回家。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到你长大了，就会明白。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到雨停了，我们再出去玩。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到我到家，饭已经做好了。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到明年春天，这里的花就开了。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到工作做完，我再给你打电话。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到他赶到车站，火车已经开走了。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别急，等到有空我就帮你修。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到孩子们都睡着了，妈妈才开始看书。", "target_word": "等到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "等到：引出某个时刻或事件，后面常接再／才／就", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示等待直到某个事件发生，与“水开了”和后面的“再”相呼应。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：虽然表示让步，与“再把这些水用来灌溉农田”的先后安排不合。"}, {"text": "所以", "is_correct": false, "explanation": "语义：所以要接在原因之后表示结果，前面没有原因分句，不能引出“水开了”这个时间条件。"}, {"text": "从而", "is_correct": false, "explanation": "语域：从而是偏书面的连词，且表示结果，与这里表示时间的口语语境不合。"}], "explanations": {"等到": "等到表示等待直到某个事件发生，与“水开了”和后面的“再”相呼应。", "虽然": "语义：虽然表示让步，与“再把这些水用来灌溉农田”的先后安排不合。", "所以": "语义：所以要接在原因之后表示结果，前面没有原因分句，不能引出“水开了”这个时间条件。", "从而": "语域：从而是偏书面的连词，且表示结果，与这里表示时间的口语语境不合。"}, "sentence_index": 0, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "等到他很聪明，所以考上了大学。", "explanation": "这里应该用〈因为〉。〈等到〉只表示等待某个时间或事件出现，不能用来说明原因。"}, {"text": "我们等到两个小时的时间，才开始讨论。", "explanation": "这里应该用〈等了〉。〈等到〉表示等来某个时刻，不能直接接一段时长；“两个小时的时间”是时长，应说“等了两个小时”。"}, {"text": "等到他很累，他还坚持工作。", "explanation": "这里应该用〈虽然〉。〈等到〉表示时间或事件，不表示让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示先等待、后发生，与“工作做完”之后“再打电话”的顺序相符。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：尽管表示让步，与“工作做完”之后再打电话的时间顺序不合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：因此表示结果，前面没有原因分句，不能引出“工作做完”这个时间条件。"}, {"text": "然而", "is_correct": false, "explanation": "语域：然而表示转折，偏书面，与这里的顺承关系不合。"}], "explanations": {"等到": "等到表示先等待、后发生，与“工作做完”之后“再打电话”的顺序相符。", "尽管": "语义：尽管表示让步，与“工作做完”之后再打电话的时间顺序不合。", "因此": "语义：因此表示结果，前面没有原因分句，不能引出“工作做完”这个时间条件。", "然而": "语域：然而表示转折，偏书面，与这里的顺承关系不合。"}, "sentence_index": 6, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "等到我做饭，我们同时看电视。", "explanation": "这里应该用〈一边〉。应说“我一边做饭，一边看电视”。〈等到〉表示先等待、后发生，不能和表示同步的〈同时〉一起用。"}, {"text": "等到他考上大学，所以我很骄傲。", "explanation": "这里应该用〈因为〉。〈等到〉只引出时间或事件，不能说明我骄傲的原因。"}, {"text": "我一直等到半个晚上的时间。", "explanation": "这里应该用〈等了〉。〈等到〉表示等来某个时刻或结果，不能直接接一段持续的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "等到到晚饭做好，我们再吃。", "corrected_sentence": "等到晚饭做好，我们再吃。", "error_description": "错误：“到”被重复写了一次，“等到”后面多出一个“到”。正确：“等到”是一个词，后面直接接时间分句“晚饭做好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "等到他回来了，所以我们就一起吃饭。", "corrected_sentence": "等到他回来了，我们就一起吃饭。", "error_description": "错误：“等到……所以”。“等到”引出时间或事件，后面不用表示因果的“所以”。正确：去掉“所以”，说“等到……就”，表示某事发生后接着做另一件事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
