INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来种植农作物（如水稻、蔬菜）的土地。", "primary_collocate": null, "pronunciation": "nóng tián", "ipa": "nʊŋ˧˥ tʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "农田", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "等到干旱时，再把这些水用来灌溉农田。", "target_word": "农田", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "农田里种着水稻和蔬菜。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，农民在农田里忙着种菜。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，农田里全是水。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片农田离村子很近。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天早上去农田浇水。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人在农田旁边修了一条水渠。", "target_word": "农田", "complexity_tier": "T3", "furigana": "gōng rén zài nóng tián páng biān xiū le yì tiáo shuǐ qú", "sentence_source": "generated"}, {"text": "农田里的稻子黄了。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把水引到农田里。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農田", "label": "繁体"}, {"form": "片", "label": "量词"}, {"form": "农田水利", "label": "复合"}], "register": "中性", "sense_fingerprint": "用于种植水稻、蔬菜等农作物的耕地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是灌溉的对象，“引至低地”后面接“海洋”，与句中的灌溉网络不符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室与灌溉无关，句子讲的是把融雪水引到需要浇灌的低地。"}, {"text": "矿山", "is_correct": false, "explanation": "搭配：“灌溉网络”“融雪水”搭配的是耕地，矿山不是引水灌溉的对象。"}, {"text": "农田", "is_correct": true, "explanation": "农田是种植农作物的土地，正是灌溉水要引去的地方。"}], "explanations": {"海洋": "语义：海洋不是灌溉的对象，“引至低地”后面接“海洋”，与句中的灌溉网络不符。", "教室": "语义：教室与灌溉无关，句子讲的是把融雪水引到需要浇灌的低地。", "矿山": "搭配：“灌溉网络”“融雪水”搭配的是耕地，矿山不是引水灌溉的对象。", "农田": "农田是种植农作物的土地，正是灌溉水要引去的地方。"}, "sentence_index": 0, "correct_answer": "农田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学的专业是农田。", "explanation": "这里应该用〈农业〉。农田指种庄稼的土地，专业名称要用农业。"}, {"text": "我家的农田里养着很多鱼和虾。", "explanation": "这里应该用〈鱼塘〉。农田是种植农作物的土地，养鱼养虾的地方要说鱼塘。"}, {"text": "他每天在农田里练习游泳。", "explanation": "这里应该用〈游泳池〉。农田是种植农作物的土地，不是游泳的地方，练游泳要去游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行与浇水无关，去银行浇水不合常理。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是注满水的场所，不需要人去浇水，与句意不合。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：电影院不需要浇水，句子说的是去种植作物的地方。"}, {"text": "农田", "is_correct": true, "explanation": "农田是种植作物的地方，早上去农田浇水符合常识。"}], "explanations": {"银行": "语义：银行与浇水无关，去银行浇水不合常理。", "游泳池": "语义：游泳池是注满水的场所，不需要人去浇水，与句意不合。", "电影院": "语义：电影院不需要浇水，句子说的是去种植作物的地方。", "农田": "农田是种植作物的地方，早上去农田浇水符合常识。"}, "sentence_index": 6, "correct_answer": "农田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们一家住在一间农田里。", "explanation": "这里应该用〈农舍〉。农田是耕地，不是住的地方，住房要说农舍。"}, {"text": "这片农田结满了苹果。", "explanation": "这里应该用〈果园〉。苹果长在树上，种果树的地方要说果园，农田种的是庄稼。"}, {"text": "他每天都在干农田。", "explanation": "这里应该用〈农活〉。农田是土地，不是劳动，干的是农活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子东边有一座农田。", "corrected_sentence": "村子东边有一块农田。", "error_description": "量词错误：“农田”是一大片土地，应该用“块”或“片”，不能用“座”（座多用于山、楼房）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天，农民农田里播种。", "corrected_sentence": "春天，农民在农田里播种。", "error_description": "介词缺失：主语“农民”之后、动词“播种”之前表示动作地点时，要用“在农田里”，不能直接说“农民农田里播种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
