INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12773, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12773, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指植物能够忍受干旱、少雨的环境而正常生长。", "primary_collocate": null, "pronunciation": "nài hàn", "ipa": "nai˥˩ xan˥˩", "syllable_count": 2, "sentences": [{"text": "他们还知道哪些作物耐旱，比如高粱和小米。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "仙人掌非常耐旱，很久不浇水也能活。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很耐旱，夏天不用天天浇水。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植物大多很耐旱。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在干旱的地方种了耐旱的玉米。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高粱比水稻耐旱，所以北方的农民喜欢种。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方雨水少，我们要选耐旱的树。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这种草耐旱又耐热。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台上的花不太耐旱，要常浇水。", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪种蔬菜最耐旱？", "target_word": "耐旱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐旱性", "label": "派生"}], "register": "中性", "sense_fingerprint": "植物能忍受干旱少雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐旱", "is_correct": true, "explanation": "正确：耐旱指植物忍受干旱少雨，与“哪些作物耐旱，比如高粱和小米”的语境相符。"}, {"text": "娇贵", "is_correct": false, "explanation": "语义：“娇贵”说作物娇弱难养，与作为例子的高粱、小米这类耐旱作物相矛盾。"}, {"text": "俊俏", "is_correct": false, "explanation": "搭配：“俊俏”形容人的容貌，不用来形容作物。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描述形体，而高粱长得很高，与例子不符。"}], "explanations": {"耐旱": "正确：耐旱指植物忍受干旱少雨，与“哪些作物耐旱，比如高粱和小米”的语境相符。", "娇贵": "语义：“娇贵”说作物娇弱难养，与作为例子的高粱、小米这类耐旱作物相矛盾。", "俊俏": "搭配：“俊俏”形容人的容貌，不用来形容作物。", "矮小": "体貌：“矮小”描述形体，而高粱长得很高，与例子不符。"}, "sentence_index": 0, "correct_answer": "耐旱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北极的企鹅很耐旱，零下几十度也不怕。", "explanation": "这里应该用〈耐寒〉。耐旱指植物忍受干旱少雨，企鹅抵御的是严寒，不能说“耐旱”。"}, {"text": "这个夏天很热，老张很耐旱，在太阳下干活一整天。", "explanation": "这里应该用〈耐热〉。耐旱是植物忍受缺水，形容人在高温下干活要用“耐热”。"}, {"text": "这种水稻很耐旱，田里积水三天也不烂。", "explanation": "这里应该用〈耐涝〉。耐旱指忍受缺水，田里积水三天要说“耐涝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐旱", "is_correct": true, "explanation": "正确：耐旱指植物忍受缺水，与“雨水少，我们要选……的树”的语境相符。"}, {"text": "耐涝", "is_correct": false, "explanation": "语义：“耐涝”指耐受积水，与“雨水少”的语境相悖。"}, {"text": "喜水", "is_correct": false, "explanation": "语义：“喜水”指需要大量水分，与“雨水少”的语境相矛盾。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”多形容土地或空气，不用来形容树。"}], "explanations": {"耐旱": "正确：耐旱指植物忍受缺水，与“雨水少，我们要选……的树”的语境相符。", "耐涝": "语义：“耐涝”指耐受积水，与“雨水少”的语境相悖。", "喜水": "语义：“喜水”指需要大量水分，与“雨水少”的语境相矛盾。", "湿润": "搭配：“湿润”多形容土地或空气，不用来形容树。"}, "sentence_index": 6, "correct_answer": "耐旱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种轮胎很耐旱，跑十万公里也没问题。", "explanation": "这里应该用〈耐用〉。耐旱只说植物忍受缺水，轮胎的经久使用要用“耐用”。"}, {"text": "这件工作服很耐旱，弄上油污也不怕。", "explanation": "这里应该用〈耐脏〉。耐旱指植物忍受干旱，衣物抗污要说“耐脏”。"}, {"text": "这幅画很耐旱，看多少遍都不腻。", "explanation": "这里应该用〈耐看〉。耐旱不用于形容画作，形容值得反复欣赏要用“耐看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种草没耐旱，要常浇水。", "corrected_sentence": "这种草不耐旱，要常浇水。", "error_description": "否定词选择错误：形容词前应用“不”，不能用“没”。应说“这种草不耐旱”，不说“这种草没耐旱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的玉米最很耐旱，常年不浇水也能长。", "corrected_sentence": "这里的玉米最耐旱，常年不浇水也能长。", "error_description": "程度副词重复：“最”和“很”都表示程度，不能同时修饰“耐旱”。应说“最耐旱”，不说“最很耐旱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一年生草本植物，茎高，叶似玉米，子实可食用或酿酒。", "primary_collocate": null, "pronunciation": "gāo liang", "ipa": "kɑʊ˥ liɑŋ", "syllable_count": 2, "sentences": [{"text": "他们还知道哪些作物耐旱，比如高粱和小米。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷在地里种了一大片高粱。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种红色的粮食叫高粱，常用来酿酒。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高粱长得比人还高，风一吹就摇。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，农民开始收高粱。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高粱的茎很高，叶子像玉米。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的农民把高粱磨成粉做饼。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地里的高粱红了，鸟儿飞来啄食。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用高粱的穗子做了一把扫帚。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种高粱的子实可以吃，也可以酿酒。", "target_word": "高粱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一棵高粱", "label": "量词"}, {"form": "高粱酒", "label": "复合"}], "register": "中性", "sense_fingerprint": "茎高叶似玉米的粮食作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高粱", "is_correct": true, "explanation": "正确：高粱是耐旱的粮食作物，与“哪些作物耐旱，比如……和小米”的语境相符。"}, {"text": "水稻", "is_correct": false, "explanation": "语义：水稻需水多，与“哪些作物耐旱”的语境相悖。"}, {"text": "荷花", "is_correct": false, "explanation": "语义：荷花生长在水中，不是耐旱作物，与前文相悖。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：牛奶不是作物，不能与“小米”并列作耐旱作物的例子。"}], "explanations": {"高粱": "正确：高粱是耐旱的粮食作物，与“哪些作物耐旱，比如……和小米”的语境相符。", "水稻": "语义：水稻需水多，与“哪些作物耐旱”的语境相悖。", "荷花": "语义：荷花生长在水中，不是耐旱作物，与前文相悖。", "牛奶": "搭配：牛奶不是作物，不能与“小米”并列作耐旱作物的例子。"}, "sentence_index": 0, "correct_answer": "高粱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在地里摘高粱，准备脱粒。", "explanation": "这里应该用〈棉花〉。“摘”多用于棉花、瓜果；高粱的穗子要割下来，不说摘高粱。"}, {"text": "农民在地里掰高粱，准备过冬。", "explanation": "这里应该用〈玉米〉。“掰”用于玉米棒子；高粱的穗子要割下来，不说掰高粱。"}, {"text": "秋天，农民把高粱挖出来晒干。", "explanation": "这里应该用〈花生〉。花生长在地下，要挖出来；高粱是直立的植物，收的是穗子，不说挖高粱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高粱", "is_correct": true, "explanation": "正确：高粱可以磨成粉做饼，与“北方的农民把……磨成粉做饼”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能磨成粉做饼，与“做饼”的语境相悖。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料不能食用，磨粉做饼说不通。"}, {"text": "油", "is_correct": false, "explanation": "搭配：“磨成粉”用于固体谷物，油是液体，不能这样磨。"}], "explanations": {"高粱": "正确：高粱可以磨成粉做饼，与“北方的农民把……磨成粉做饼”的语境相符。", "石头": "语义：石头不能磨成粉做饼，与“做饼”的语境相悖。", "塑料": "语义：塑料不能食用，磨粉做饼说不通。", "油": "搭配：“磨成粉”用于固体谷物，油是液体，不能这样磨。"}, "sentence_index": 6, "correct_answer": "高粱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶用纺车纺高粱，织成了一块粗布。", "explanation": "这里应该用〈羊毛〉。“纺”用于棉、麻、毛等纤维，高粱不是纤维，不能纺。"}, {"text": "妈妈用高粱给宝宝织了一件毛衣。", "explanation": "这里应该用〈毛线〉。“织”要用线，高粱不是线材，不能用来织毛衣。"}, {"text": "奶奶用高粱给孙子缝了一双棉鞋。", "explanation": "这里应该用〈棉布〉。“缝”用于布料，高粱不是布料，不能缝鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地里种着一条高粱。", "corrected_sentence": "地里种着一片高粱。", "error_description": "量词错误：成片种植的高粱应用“片”，“条”用于细长的东西，应说“一片高粱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片高粱得穗子很大，红彤彤的。", "corrected_sentence": "这片高粱的穗子很大，红彤彤的。", "error_description": "结构助词错误：“高粱”修饰“穗子”要用“的”，不能用“得”，应说“高粱的穗子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
