INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常有价值，十分珍贵，形容事物值得珍惜和重视。", "primary_collocate": null, "pronunciation": "bǎo guì", "ipa": "pɑʊ̯˨˩ kweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这些农业经验来自多年的观察，是宝贵的本土知识。", "target_word": "宝贵", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "值得注意的是，蜜蜂的社会性结构本身亦为科学研究提供了宝贵模型。", "target_word": "宝贵", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "时间很宝贵，我们别迟到。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你给我这么宝贵的意见。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康比钱更宝贵。", "target_word": "宝贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师的经验对我们很宝贵。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次机会非常宝贵，你要好好用。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生命只有一次，所以特别宝贵。", "target_word": "宝贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把宝贵的时间都用在学习上了。", "target_word": "宝贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片记录着宝贵的回忆。", "target_word": "宝贵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宝贵", "label": "基本形式"}, {"form": "寶貴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容时间、经验、意见、机会等抽象事物很有价值，值得珍惜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b7ca80-ae1c-4e7c-a5ec-daf599d2e99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宝贵", "is_correct": true, "explanation": "正确：“宝贵”形容多年观察得来的知识很有价值，与句意相符。"}, {"text": "廉价", "is_correct": false, "explanation": "语义：“廉价”指价格低，与“多年观察”得来的知识价值相矛盾。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容含水分多、不干燥，不能用来形容知识。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面不平滑，不能用来描述知识。"}], "explanations": {"宝贵": "正确：“宝贵”形容多年观察得来的知识很有价值，与句意相符。", "廉价": "语义：“廉价”指价格低，与“多年观察”得来的知识价值相矛盾。", "潮湿": "搭配：“潮湿”形容含水分多、不干燥，不能用来形容知识。", "粗糙": "搭配：“粗糙”形容表面不平滑，不能用来描述知识。"}, "sentence_index": 0, "correct_answer": "宝贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的价格很宝贵，我买不起。", "explanation": "这里应该用〈昂贵〉。宝贵说的是事物值得珍惜，不用来形容价格；价格高要说昂贵。"}, {"text": "他的身高很宝贵，大家都很羡慕。", "explanation": "这里应该用〈高〉。身高说的是高矮，要说很高；宝贵说的是事物值得珍惜，不用来评价身高。"}, {"text": "这个班的人数很宝贵，老师很高兴。", "explanation": "这里应该用〈多〉。人数的多少要说多或少；宝贵说的是事物值得珍惜，不用来形容数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宝贵", "is_correct": true, "explanation": "正确：“非常宝贵”说明这次机会很有价值，与后面“好好用”相符。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”形容让人提不起兴趣，与“机会”的价值相矛盾。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度感受，不能用来形容机会。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音粗哑，不能用来形容机会。"}], "explanations": {"宝贵": "正确：“非常宝贵”说明这次机会很有价值，与后面“好好用”相符。", "无聊": "语义：“无聊”形容让人提不起兴趣，与“机会”的价值相矛盾。", "冰凉": "搭配：“冰凉”形容温度感受，不能用来形容机会。", "沙哑": "搭配：“沙哑”形容声音粗哑，不能用来形容机会。"}, "sentence_index": 6, "correct_answer": "宝贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他宝贵地说了一句话，大家都愣住了。", "explanation": "这里应该用〈郑重〉。宝贵是形容词，说的是事物值得珍惜，不能修饰“说”这类动作；描述说话的态度要说郑重地。"}, {"text": "这块布的颜色很宝贵，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。宝贵说的是事物值得珍惜，不用来评价颜色；颜色亮丽要说鲜艳。"}, {"text": "他的脾气很宝贵，大家都很喜欢他。", "explanation": "这里应该用〈好〉。宝贵说的是事物值得珍惜，不用来形容脾气；脾气好要说好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我提了一条很宝贵建议。", "corrected_sentence": "他给我提了一条很宝贵的建议。", "error_description": "漏掉“的”：“很宝贵”修饰名词“建议”时要说“很宝贵的建议”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的机会特殊宝贵，我很珍惜。", "corrected_sentence": "这次旅行的机会特别宝贵，我很珍惜。", "error_description": "词语误用：「特殊」是形容词，不能修饰形容词「宝贵」；表示程度应用副词「特别」，说「特别宝贵」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。"}, {"text": "挖掘", "is_correct": false, "explanation": "不是反义：挖掘指掘开土地或矿藏，与“修建”不构成反义。"}, {"text": "装饰", "is_correct": false, "explanation": "不是反义：装饰指美化外观，与“修建”不构成反义。"}, {"text": "种植", "is_correct": false, "explanation": "不是反义：种植指栽培植物，与“修建”不构成反义。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。", "挖掘": "不是反义：挖掘指掘开土地或矿藏，与“修建”不构成反义。", "装饰": "不是反义：装饰指美化外观，与“修建”不构成反义。", "种植": "不是反义：种植指栽培植物，与“修建”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。"}, {"text": "粉刷", "is_correct": false, "explanation": "不是反义：粉刷指给墙面涂上涂料，与“修建”不构成反义。"}, {"text": "改造", "is_correct": false, "explanation": "不是反义：改造指改变原有的样子，与“修建”不构成反义。"}, {"text": "美化", "is_correct": false, "explanation": "不是反义：美化指使事物更美观，与“修建”不构成反义。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：“拆除”与“修建”是一对反义动词，指把建筑或道路拆掉。", "粉刷": "不是反义：粉刷指给墙面涂上涂料，与“修建”不构成反义。", "改造": "不是反义：改造指改变原有的样子，与“修建”不构成反义。", "美化": "不是反义：美化指使事物更美观，与“修建”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对建筑物、道路等进行建造或施工。", "primary_collocate": null, "pronunciation": "xiū jiàn", "ipa": "ɕjoʊ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "另一个常见的做法是修建梯田。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "古时候，人们修建长城是为了防御。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "修建长城用了很多人力和很多年的时间。", "target_word": "修建", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "政府打算在河上修建一座新桥。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里去年修建了一所小学。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在山里修建一条公路。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园是十年前修建的。", "target_word": "修建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了方便老人，小区门口修建了一个小花园。", "target_word": "修建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们很快就修建了这条河堤。", "target_word": "修建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们修建着一条通向海边的铁路。", "target_word": "修建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修建了", "label": "体标（了）"}, {"form": "修建过", "label": "体标（过）"}, {"form": "修建着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "建造建筑物或道路等工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8ad67b-239f-4a6f-82cc-ce442b51a334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": true, "explanation": "正确：“修建”指建造梯田这类工程，符合句中“做法”的语境。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：梯田是为了耕种而修建的地形，不是用来装饰的。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：句子说的是一种常见做法，不是破坏。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能说收割梯田。"}], "explanations": {"修建": "正确：“修建”指建造梯田这类工程，符合句中“做法”的语境。", "装饰": "语义：梯田是为了耕种而修建的地形，不是用来装饰的。", "摧毁": "语义：句子说的是一种常见做法，不是破坏。", "收割": "搭配：“收割”的对象是庄稼，不能说收割梯田。"}, "sentence_index": 0, "correct_answer": "修建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台旧机器坏了，要马上修建。", "explanation": "这里应该用〈修理〉。把坏了的机器弄好用“修理”，“修建”指建造建筑或道路。"}, {"text": "园丁在花园里修建树枝。", "explanation": "这里应该用〈修剪〉。剪掉多余的枝叶用“修剪”，“修建”不用于树枝。"}, {"text": "墙上有个洞，需要修建。", "explanation": "这里应该用〈修补〉。填补墙上的破洞用“修补”，“修建”指建造新的建筑或道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修建", "is_correct": true, "explanation": "正确：“修建”指建造公园，符合句中“十年前建成”的语境。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”多用于土地、矿藏，不说挖掘一个公园。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：“编写”用于文字或程序，不能说编写一个公园。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指用烤箱制作食品，与公园无关。"}], "explanations": {"修建": "正确：“修建”指建造公园，符合句中“十年前建成”的语境。", "挖掘": "搭配：“挖掘”多用于土地、矿藏，不说挖掘一个公园。", "编写": "搭配：“编写”用于文字或程序，不能说编写一个公园。", "烘焙": "语义：“烘焙”指用烤箱制作食品，与公园无关。"}, "sentence_index": 6, "correct_answer": "修建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅古画破损了，需要修建。", "explanation": "这里应该用〈修复〉。古画损坏后要修复，“修建”指建造建筑或道路，不用于古画。"}, {"text": "她每天花时间修建指甲。", "explanation": "这里应该用〈修剪〉。剪短、修整指甲用“修剪”，“修建”指建造建筑或道路。"}, {"text": "他把作文修建了三遍。", "explanation": "这里应该用〈修改〉。修改文章用“修改”，“修建”只用于建筑、道路等工程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在修建了一条新公路。", "corrected_sentence": "工人们正在修建一条新公路。", "error_description": "“正在”表示动作正在进行，不能与“了”同用。“修建”后面应去掉“了”，说“正在修建一条新公路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把修建了一条铁路。", "corrected_sentence": "工人们修建了一条铁路。", "error_description": "“把”字要放在处置对象前，“把修建”不通。“修建”是普通的及物动词，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
