INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12778, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在山坡上建造的像台阶一样一层一层的农田。", "primary_collocate": null, "pronunciation": "tī tián", "ipa": "tʰi˥ tʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "另一个常见的做法是修建梯田。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "山上的梯田一层一层，像台阶一样。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在梯田里种水稻。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南有很多漂亮的梯田。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，梯田里的水像一面面镜子。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着小路走到梯田旁边。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片梯田已经有几百年的历史了。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上修了梯田，雨水就不容易把土冲走。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天梯田变成了金黄色，游客都来拍照。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯田太窄，大机器开不进去。", "target_word": "梯田", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片梯田", "label": "量词"}, {"form": "一块梯田", "label": "量词"}], "register": "中性", "sense_fingerprint": "山坡上修成台阶状的农田", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb51345-e098-436a-9cfa-5ee1a13ef7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "梯田", "is_correct": true, "explanation": "正确：修建梯田是在山坡上修台阶式的农田，与句意相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑或设施，不说“修建歌曲”。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不能修建。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏是一段时间，不是可以修建的东西。"}], "explanations": {"梯田": "正确：修建梯田是在山坡上修台阶式的农田，与句意相符。", "歌曲": "搭配：“修建”的对象是建筑或设施，不说“修建歌曲”。", "咖啡": "语义：咖啡是饮料，不能修建。", "黄昏": "语义：黄昏是一段时间，不是可以修建的东西。"}, "sentence_index": 0, "correct_answer": "梯田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在山坡上种梯田。", "explanation": "这里应该用〈茶树〉。梯田是地块，不是作物，不能说种梯田；种的应是茶树等作物。"}, {"text": "这栋楼外面有很多梯田。", "explanation": "这里应该用〈台阶〉。梯田是山坡上的农田，楼前的台阶不能说梯田。"}, {"text": "平原上有大片梯田。", "explanation": "这里应该用〈稻田〉。梯田修在山坡上，平原上的成片农田应说稻田。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梯田", "is_correct": true, "explanation": "正确：这片梯田修了几百年，与句意相符。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是饮料，没有几百年的历史。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“片”一般不用于手机；另外手机也没有几百年的历史。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是近代才有的交通工具，不会有几百年的历史。"}], "explanations": {"梯田": "正确：这片梯田修了几百年，与句意相符。", "果汁": "语义：果汁是饮料，没有几百年的历史。", "手机": "搭配：量词“片”一般不用于手机；另外手机也没有几百年的历史。", "汽车": "语义：汽车是近代才有的交通工具，不会有几百年的历史。"}, "sentence_index": 6, "correct_answer": "梯田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在公园里玩梯田。", "explanation": "这里应该用〈滑梯〉。梯田是农田，不能用来玩耍。"}, {"text": "他推开梯田走进了教室。", "explanation": "这里应该用〈门〉。推开的是门、窗等，梯田是农田，不能推开。"}, {"text": "我们走梯田上楼。", "explanation": "这里应该用〈楼梯〉。上楼要走楼梯，梯田是农田，不能用来上楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们看见了一条梯田。", "corrected_sentence": "我们看见了一片梯田。", "error_description": "量词错误：梯田是成片的农田，应说“一片梯田”或“一块梯田”，不用“条”（“条”用于河、路等长条形的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家后面的山上有一本梯田。", "corrected_sentence": "我家后面的山上有一片梯田。", "error_description": "量词错误：「一本梯田」应为「一片梯田」。梯田是成片的农田，用〈片〉；〈本〉用于书、本子等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24acb26d-05d9-4bc5-91bc-51c93823c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
