INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12781, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山坡上修成的平坦地块，用于种植作物", "primary_collocate": null, "pronunciation": "píng tái", "ipa": "pʰiŋ˧˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "山坡被改成一层一层的平台，这样可以减少水土流失。", "target_word": "平台", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "农民在山坡上修了一层层平台，用来种茶。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的平台很窄，只能种几行玉米。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些山上的平台是几代人一点一点修出来的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨时，山坡上的平台能留住水土。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在山坡的平台上种了很多土豆。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山下往上看，一层层平台像楼梯一样。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在最高的一层平台上种了茶树。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡太陡不能种地，所以人们修了平台。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块平台的土很好，种出来的菜特别大。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "山地平台", "label": "复合"}], "register": "中性", "sense_fingerprint": "山坡上修成的种庄稼的平地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 山坡 (Zipf 3.79), 留住 (Zipf 3.67), 水土 (Zipf 3.49)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 山坡 (Zipf 3.79), 陡 (Zipf 2.96), 种地 (Zipf 3.24)']::text[], '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "正确。“一层一层的平台”指山坡上修成的平地，符合“减少水土流失”的语境。"}, {"text": "平房", "is_correct": false, "explanation": "语义：“平房”指房屋，不是种庄稼的平地，句中“一层一层的平房”没有意义。"}, {"text": "高原", "is_correct": false, "explanation": "语义：“高原”指大面积的高地，不是人工修成的一层层地块。"}, {"text": "平原", "is_correct": false, "explanation": "语义：“平原”指大面积的平地，不是山坡上一层层修出来的地块。"}], "explanations": {"平台": "正确。“一层一层的平台”指山坡上修成的平地，符合“减少水土流失”的语境。", "平房": "语义：“平房”指房屋，不是种庄稼的平地，句中“一层一层的平房”没有意义。", "高原": "语义：“高原”指大面积的高地，不是人工修成的一层层地块。", "平原": "语义：“平原”指大面积的平地，不是山坡上一层层修出来的地块。"}, "sentence_index": 0, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷把金鱼放进了山坡的平台里，每天都换水。", "explanation": "这里应该用「池塘」。平台是旱地，没有水，金鱼放不进去。"}, {"text": "山上的平台很甜，孩子们都爱吃。", "explanation": "这里应该用「果子」。平台是地块，没有甜味，「甜」只能形容果实。"}, {"text": "山坡上的平台会飞，一下子飞到了天上。", "explanation": "这里应该用「鸟」。平台是地块，不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "正确。“一层层平台”指山坡上修出的平地，像楼梯一样分层，符合语境。"}, {"text": "平面", "is_correct": false, "explanation": "语义：“平面”是几何概念，不能堆成一层层像楼梯的地块。"}, {"text": "平原", "is_correct": false, "explanation": "语义：平原是大面积的平坦地带，不是一层层人工修成的地块，「像楼梯一样」说不通。"}, {"text": "平板", "is_correct": false, "explanation": "语义：“平板”指薄的平面物体，不能用来描述山坡上层层修成的种植地块。"}], "explanations": {"平台": "正确。“一层层平台”指山坡上修出的平地，像楼梯一样分层，符合语境。", "平面": "语义：“平面”是几何概念，不能堆成一层层像楼梯的地块。", "平原": "语义：平原是大面积的平坦地带，不是一层层人工修成的地块，「像楼梯一样」说不通。", "平板": "语义：“平板”指薄的平面物体，不能用来描述山坡上层层修成的种植地块。"}, "sentence_index": 6, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民把这块平台放进锅里煮了。", "explanation": "这里应该用「土豆」。平台是一块地，不能放进锅里煮。"}, {"text": "这块平台很会游泳，一下子就游到了河对岸。", "explanation": "这里应该用「鱼」。平台是旱地上的地块，不会游泳。"}, {"text": "这块平台的土很会唱歌，大家都围过来听。", "explanation": "平台是地块，不会唱歌，「会唱歌」只能用于人或音响。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在山上修了三只平台。", "corrected_sentence": "他们在山上修了三个平台。", "error_description": "错误在于量词用错。「平台」应用量词「个」或「层」，不能用「只」，正确说法是「他们在山上修了三个平台」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只平台的地很平。", "corrected_sentence": "这个平台的地很平。", "error_description": "错误在于量词用错。“平台”指地块时应用量词“个”或“块”，不能用“只”，正确说法是“这个平台的地很平”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
