INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体流动而消失；也比喻时间等逝去。", "primary_collocate": null, "pronunciation": "liú zǒu", "ipa": "li̯oʊ̯˧˥ tsoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "下雨时，水不会很快流走，而是慢慢渗入土壤。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "浴缸里的水慢慢流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水带着树叶流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开门，房间里的水很快就流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间像水一样，一天天流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水流走了，只剩下石头。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从屋顶流走，不会留在院子里。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那片叶子跟着水流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在河边，看着水慢慢流走。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美好的日子慢慢流走，再也回不来。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流走了", "label": "体标（了）"}, {"form": "流不走", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "动词：液体流开不见了，也比喻时间逝去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走：液体流开消失，与“慢慢渗入土壤”形成对比，符合句意。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：下雨时的水不会沸腾，与“下雨时”的情境矛盾。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：句子说水没有停在地表，而是渗进土壤，“结冰”会让水留下，与句意矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "搭配：水一般说“结冰”，“凝固”多用于血液、水泥等物质。"}], "explanations": {"流走": "流走：液体流开消失，与“慢慢渗入土壤”形成对比，符合句意。", "沸腾": "语义：下雨时的水不会沸腾，与“下雨时”的情境矛盾。", "结冰": "语义：句子说水没有停在地表，而是渗进土壤，“结冰”会让水留下，与句意矛盾。", "凝固": "搭配：水一般说“结冰”，“凝固”多用于血液、水泥等物质。"}, "sentence_index": 0, "correct_answer": "流走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他趁老师不注意，悄悄流走了。", "explanation": "这里应该用〈溜走〉。流走指液体流开不见，人悄悄离开要用溜走。"}, {"text": "石头从山坡上流走了。", "explanation": "这里应该用〈滚走〉。流走用于液体、时间等流动的东西，石头被推下山要用滚走。"}, {"text": "洪水流走了村里的房子。", "explanation": "这里应该用〈冲走〉。流走是不及物动词，不能带“房子”作宾语，把东西冲离原处要用冲走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走：液体离开屋顶、不再留存，与“不会留在院子里”呼应。"}, {"text": "上升", "is_correct": false, "explanation": "语义：雨水从屋顶向下流，不会向上升，与句中的走向矛盾。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：“漂浮”要说“在水面上漂浮”，不能直接接“从屋顶”。"}, {"text": "倒流", "is_correct": false, "explanation": "语义：“倒流”指逆向流回，与“从屋顶”的下流路线矛盾。"}], "explanations": {"流走": "流走：液体离开屋顶、不再留存，与“不会留在院子里”呼应。", "上升": "语义：雨水从屋顶向下流，不会向上升，与句中的走向矛盾。", "漂浮": "搭配：“漂浮”要说“在水面上漂浮”，不能直接接“从屋顶”。", "倒流": "语义：“倒流”指逆向流回，与“从屋顶”的下流路线矛盾。"}, "sentence_index": 6, "correct_answer": "流走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌在民间流走了几百年。", "explanation": "这里应该用〈流传〉。流走表示消失，歌曲代代传下去要用流传。"}, {"text": "她想起母亲，眼泪忍不住流走了。", "explanation": "这里应该用〈流下〉。流走指液体流开消失，眼泪沿脸颊往下淌要用流下。"}, {"text": "小鸟停在树枝上，忽然流走了。", "explanation": "这里应该用〈飞走〉。流走用于液体、时间等流动的东西，鸟离开要用飞走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房水槽里的水很快就把流走了。", "corrected_sentence": "厨房水槽里的水很快就流走了。", "error_description": "“流走”是不及物动词，不能用在“把”字句里作处置，应去掉“把”，说“水很快就流走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水一会儿就把屋檐流走了。", "corrected_sentence": "雨水一会儿就从屋檐流走了。", "error_description": "“流走”表示液体从某处流开，起点要用“从”引出，不能用“把”处置，应说“从屋檐流走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
