INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "粮食产量是指在一定时期内，从土地上收获的谷物、豆类、薯类等农作物的总数量。", "primary_collocate": null, "pronunciation": "liáng shi chǎn liàng", "ipa": "ljɑŋ˧˥ ʂɨ tʂʰan˨˩ ljɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种传统技术不仅保护了土地，也提高了粮食产量。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "今年雨水多，粮食产量比去年高。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用了新种子，粮食产量增加了。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村的粮食产量每年都在上升。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太干，今年的粮食产量会下降。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很关心全国的粮食产量。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办法提高粮食产量，让大家吃饱饭。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，今年的粮食产量是近十年最高的。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了好肥料以后，这块地的粮食产量多了一倍。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，南方的粮食产量受到了大雨的影响。", "target_word": "粮食产量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粮食总产量", "label": "复合"}, {"form": "粮食年产量", "label": "复合"}], "register": "中性", "sense_fingerprint": "一定时期内从土地上收获的谷物、豆类、薯类等农作物的总数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粮食产量", "is_correct": true, "explanation": "正确。“提高”可以搭配“粮食产量”，指收获的粮食总数增加，与前一分句“保护了土地”的作用相连。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水体，不能被“提高”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄只会增长，不能说被“提高”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“提高”多用于水平、质量，体重要说“增加”。"}], "explanations": {"粮食产量": "正确。“提高”可以搭配“粮食产量”，指收获的粮食总数增加，与前一分句“保护了土地”的作用相连。", "河流": "语义：河流是自然水体，不能被“提高”。", "年龄": "语义：年龄只会增长，不能说被“提高”。", "体重": "搭配：“提高”多用于水平、质量，体重要说“增加”。"}, "sentence_index": 0, "correct_answer": "粮食产量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府每年都要检查仓库里的粮食产量。", "explanation": "这里应该用〈粮食储量〉。粮食产量指一定时期内收获的总数量，仓库里存放的数量要用粮食储量来说。"}, {"text": "我每天早上去市场买粮食产量。", "explanation": "这里应该用〈大米〉。粮食产量是收获的总数量，是统计数字，市场上卖的是大米这类实物，不能买粮食产量。"}, {"text": "农民把粮食产量堆在院子里，晒了三天才干。", "explanation": "这里应该用〈谷物〉。粮食产量是收获的总数量，是抽象的统计数字，不能堆在院子里晒干；堆放、晒干的是谷物本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粮食产量", "is_correct": true, "explanation": "正确。“提高粮食产量”与后一分句“让大家吃饱饭”的意思相符。"}, {"text": "房价", "is_correct": false, "explanation": "语义：房价与“让大家吃饱饭”无关，句意不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历与“吃饱饭”无关，句意不通。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“提高”不用于人数，人数要说“增加”或“增长”。"}], "explanations": {"粮食产量": "正确。“提高粮食产量”与后一分句“让大家吃饱饭”的意思相符。", "房价": "语义：房价与“让大家吃饱饭”无关，句意不通。", "学历": "语义：学历与“吃饱饭”无关，句意不通。", "人数": "搭配：“提高”不用于人数，人数要说“增加”或“增长”。"}, "sentence_index": 6, "correct_answer": "粮食产量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "南方种了很多粮食产量。", "explanation": "这里应该用〈粮食作物〉。粮食产量是收获的总数量，不能拿来种植。"}, {"text": "妈妈把粮食产量放进了冰箱。", "explanation": "这里应该用〈粮食〉。粮食产量是收获的总数量，是统计数字，不能放进冰箱。"}, {"text": "工厂每天加工很多粮食产量。", "explanation": "这里应该用〈大米〉。粮食产量是收获的总数量，不是可以加工的实物，工厂加工的是大米等原料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前年的一个粮食产量减少了一半。", "corrected_sentence": "前年的粮食产量减少了一半。", "error_description": "“粮食产量”是收获总数的统计概念，前面不能加“一个”这类个体量词；正确说法是“前年的粮食产量减少了一半”，不说“前年的一个粮食产量……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的粮食产量比去年很高。", "corrected_sentence": "今年的粮食产量比去年高很多。", "error_description": "“比”字句中形容词前不能加“很”，程度要放在形容词后面，应说“比去年高很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
