INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12787, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用机械原理将水从低处提升到高处或增加水压的装置。", "primary_collocate": null, "pronunciation": "chōu shuǐ jī", "ipa": "tʂʰou˥ ʂwei˨˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "虽然现在有了抽水机和水库，但很多人仍然相信这些古老的方法。", "target_word": "抽水机", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "田里没有水，农民用抽水机把河水抽上来。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台抽水机坏了，我们要找人修一修。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的井很深，爷爷买了一台抽水机。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽水机一开，水就从管子里流出来了。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨后，地下室进了水，工人用抽水机排水。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有河，村里人靠抽水机把水送到田里。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里开抽水机的声音很大，邻居睡不好。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电的时候，抽水机就不能用了。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂买了两台大抽水机，用来抽地下的水。", "target_word": "抽水机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "电动抽水机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把水从低处提升到高处或增加水压的机械装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26277819-a66e-4f55-abd3-b39720fefbb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽水机", "is_correct": true, "explanation": "正确。抽水机是现代机器，与“现在有了”相符，并与后半句“古老的方法”形成对比。"}, {"text": "马车", "is_correct": false, "explanation": "语义：马车是古老的交通工具，与“现在有了”的现代语境冲突。"}, {"text": "轿子", "is_correct": false, "explanation": "语义：轿子同样是古代的交通工具，与“现在”的语境矛盾。"}, {"text": "石磨", "is_correct": false, "explanation": "语义：石磨是古老的粮食加工工具，与“现在有了”的现代语境冲突。"}], "explanations": {"抽水机": "正确。抽水机是现代机器，与“现在有了”相符，并与后半句“古老的方法”形成对比。", "马车": "语义：马车是古老的交通工具，与“现在有了”的现代语境冲突。", "轿子": "语义：轿子同样是古代的交通工具，与“现在”的语境矛盾。", "石磨": "语义：石磨是古老的粮食加工工具，与“现在有了”的现代语境冲突。"}, "sentence_index": 0, "correct_answer": "抽水机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里的井很深，爷爷买了一只抽水机。", "explanation": "这里应该用〈台〉。抽水机是机器，量词用“台”，“只”多用于动物。"}, {"text": "奶奶拎着抽水机去井边打水。", "explanation": "这里应该用〈水桶〉。抽水机是大型机器，不能拎着去打水。"}, {"text": "我口渴了，就用抽水机喝水。", "explanation": "这里应该用〈水杯〉。抽水机只能把水从低处提到高处，不能用来喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽水机", "is_correct": true, "explanation": "正确。“靠抽水机把水送到田里”符合“山上没有河”的语境。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能把水送到田里，与语境不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来冷藏食物，不能把水送到田里。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“把水送到田里”需要能完成输送动作的工具，“课本”不具备这一功能。"}], "explanations": {"抽水机": "正确。“靠抽水机把水送到田里”符合“山上没有河”的语境。", "雨伞": "语义：雨伞不能把水送到田里，与语境不合。", "冰箱": "语义：冰箱用来冷藏食物，不能把水送到田里。", "课本": "配价：“把水送到田里”需要能完成输送动作的工具，“课本”不具备这一功能。"}, "sentence_index": 6, "correct_answer": "抽水机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂买了两台抽水机，用来给机器供电。", "explanation": "这里应该用〈发电机〉。抽水机只负责抽水，不能给机器供电。"}, {"text": "这家工厂买了两台抽水机，用来切菜。", "explanation": "这里应该用〈切菜机〉。抽水机是用来抽水的，不能用来切菜。"}, {"text": "这家工厂买了两台抽水机，用来冷藏食品。", "explanation": "这里应该用〈冰箱〉。抽水机不能冷藏食品，它的作用是把水抽上来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天这台抽水坏了，我们找人修好了。", "corrected_sentence": "昨天这台抽水机坏了，我们找人修好了。", "error_description": "“抽水”是动词，后面漏掉了“机”，不能直接接量词“台”作名词；应说“抽水机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们村买了两只新抽水机。", "corrected_sentence": "我们村买了两台新抽水机。", "error_description": "量词错误：抽水机是机器，量词应用“台”，不能用“只”。“只”多用于动物或成对的小物件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0abc94b7-4340-487e-a489-904c227e0f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
