INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在山沟或河流上修建的、用于蓄水和调节水流的建筑物，常用于灌溉、发电、供水等。", "primary_collocate": null, "pronunciation": "shuǐ kù", "ipa": "ʂweɪ˨˩˦ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "虽然现在有了抽水机和水库，但很多人仍然相信这些古老的方法。", "target_word": "水库", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这座水库可以发电，也可以灌溉农田。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里新修了一座水库，夏天不怕缺水了。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨以后，水库的水位升高了。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水库旁边的村子用这里的水种稻子。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在河上修水库，花了三年时间。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年雨少，水库里的水只剩一半了。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的自来水来自附近的水库。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水库的大坝很高，里面能存很多水。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了防洪，水库提前放了一些水。", "target_word": "水库", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "水库大坝", "label": "复合"}, {"form": "水庫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拦河筑坝修成、用来蓄水并调节水流的水利工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水库", "is_correct": true, "explanation": "正确：抽水机和水库都是用水的设施，并列合理，符合“现在有了”的语境。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠是干旱的地貌，不是用水设施，与抽水机并列不通。"}, {"text": "神话", "is_correct": false, "explanation": "语义：神话是虚构的故事，不是设施，与前文的抽水机并列不通。"}, {"text": "语文", "is_correct": false, "explanation": "搭配：“有了……和……”并列的应是同类设施，“语文”是学科，不能与抽水机并列。"}], "explanations": {"水库": "正确：抽水机和水库都是用水的设施，并列合理，符合“现在有了”的语境。", "沙漠": "语义：沙漠是干旱的地貌，不是用水设施，与抽水机并列不通。", "神话": "语义：神话是虚构的故事，不是设施，与前文的抽水机并列不通。", "语文": "搭配：“有了……和……”并列的应是同类设施，“语文”是学科，不能与抽水机并列。"}, "sentence_index": 0, "correct_answer": "水库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把水库放在灶上烧水煮饭。", "explanation": "这里应该用〈锅〉。水库是大型蓄水工程，不能放在灶上烧水；烧水煮饭要用锅。"}, {"text": "村里修了一座水库，专门用来把田里的积水排出去。", "explanation": "这里应该用〈排水沟〉。水库的主要功能是蓄水、调节水流，排出田里的积水要用排水沟，而不是修水库。"}, {"text": "后院的水库里养着几条金鱼。", "explanation": "这里应该用〈水池〉。水库是大型蓄水工程，后院的小水体要用水池，水库不会建在后院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水库", "is_correct": true, "explanation": "正确：水库是能蓄水的大型水体，“里的水只剩一半”与“雨少”的语境一致。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能盛水，“天空里的水”说不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能盛水，与“水只剩一半”的说法不符。"}, {"text": "烟囱", "is_correct": false, "explanation": "搭配：“……里的水”要求能盛水的容器，烟囱不能盛水，搭配不当。"}], "explanations": {"水库": "正确：水库是能蓄水的大型水体，“里的水只剩一半”与“雨少”的语境一致。", "天空": "语义：天空不能盛水，“天空里的水”说不通。", "沙发": "语义：沙发不能盛水，与“水只剩一半”的说法不符。", "烟囱": "搭配：“……里的水”要求能盛水的容器，烟囱不能盛水，搭配不当。"}, "sentence_index": 6, "correct_answer": "水库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的水库坏了，水一直在流。", "explanation": "这里应该用〈水龙头〉。水库是大型蓄水工程，不会装在厨房里；厨房里出水的设施是水龙头。"}, {"text": "这座水库很长，流过了好几个村庄。", "explanation": "这里应该用〈河流〉。河流会流动、流过村庄；水库是静止的蓄水体，不能说流过村庄。"}, {"text": "家里的水库装满了雨水。", "explanation": "这里应该用〈水缸〉。水库是大型工程，家里装雨水的容器要用水缸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条水库很深，周围都是树。", "corrected_sentence": "那座水库很深，周围都是树。", "error_description": "“水库”的量词应用“座”，不能用“条”（“条”多用于河流、路等长条形事物）。错误形式：那条水库；正确形式：那座水库。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村的用水来自远处的水库们。", "corrected_sentence": "这个村的用水来自远处的水库。", "error_description": "“水库”是非人名词，不能加“们”表示复数。错误形式：远处的水库们；正确形式：远处的水库。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：相信与怀疑意义相对，一个表示认为某事是真的，一个表示对它持疑问。"}, {"text": "忘记", "is_correct": false, "explanation": "无关：忘记表示不再记得，与相信不构成反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：讨论表示交换意见，与相信不构成反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "无关：观察表示仔细看，与相信不构成反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：相信与怀疑意义相对，一个表示认为某事是真的，一个表示对它持疑问。", "忘记": "无关：忘记表示不再记得，与相信不构成反义关系。", "讨论": "无关：讨论表示交换意见，与相信不构成反义关系。", "观察": "无关：观察表示仔细看，与相信不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：相信与怀疑意义相对，二者分别表示认为真实与心存疑问。"}, {"text": "解释", "is_correct": false, "explanation": "无关：解释表示说明道理，与相信不构成反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "无关：提醒表示促使对方注意，与相信不构成反义关系。"}, {"text": "欣赏", "is_correct": false, "explanation": "无关：欣赏表示认为好而喜爱，与相信不构成反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：相信与怀疑意义相对，二者分别表示认为真实与心存疑问。", "解释": "无关：解释表示说明道理，与相信不构成反义关系。", "提醒": "无关：提醒表示促使对方注意，与相信不构成反义关系。", "欣赏": "无关：欣赏表示认为好而喜爱，与相信不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为某个事情或某人的话是真实的，不怀疑。", "primary_collocate": null, "pronunciation": "xiāng xìn", "ipa": "ɕjɑŋ˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "虽然现在有了抽水机和水库，但很多人仍然相信这些古老的方法。", "target_word": "相信", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我相信他说的是真话。", "target_word": "相信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我相信地球是圆的。", "target_word": "相信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不相信这个消息是真的。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师相信每个学生都能学好。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说得很认真，我就相信了。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人相信吃苹果对身体好。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从来没有相信过他的话。", "target_word": "相信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都相信明天会下雨。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子相信妈妈说的每一句话。", "target_word": "相信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相信了", "label": "体标"}, {"form": "相信过", "label": "体标"}], "register": "中性", "sense_fingerprint": "认为某事或某人的话是真的、可靠的而不怀疑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相信", "is_correct": true, "explanation": "正确：“仍然相信”表示即使有了新方法，人们依然认为古老的方法可靠，符合“虽然……但……”的语境。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“古老的方法”已经存在，不能再说“发明”，与“古老”矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，后面不能直接带“这些古老的方法”作宾语。"}, {"text": "研制", "is_correct": false, "explanation": "语义：“研制”指新近造出，而“古老的方法”已经存在，二者矛盾，不能说研制这些古老的方法。"}], "explanations": {"相信": "正确：“仍然相信”表示即使有了新方法，人们依然认为古老的方法可靠，符合“虽然……但……”的语境。", "发明": "语义：“古老的方法”已经存在，不能再说“发明”，与“古老”矛盾。", "出生": "配价：“出生”是不及物动词，后面不能直接带“这些古老的方法”作宾语。", "研制": "语义：“研制”指新近造出，而“古老的方法”已经存在，二者矛盾，不能说研制这些古老的方法。"}, "sentence_index": 0, "correct_answer": "相信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在森林里相信了一种新鸟。", "explanation": "这里应该用〈发现〉。相信表示认为某件事是真的，不能用来表示找到新的事物。"}, {"text": "妈妈很相信我的安全。", "explanation": "这里应该用〈担心〉。相信的宾语应是一件事的真实性，不说“相信我的安全”；牵挂安全要用〈担心〉。"}, {"text": "他相信了我的名字。", "explanation": "这里应该用〈询问〉。相信表示认为某件事是真的，不能表示提问；问别人的名字要用〈询问〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相信", "is_correct": true, "explanation": "正确：“相信吃苹果对身体好”是一个判断，符合“很多人”的语境。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所或展览，不能带“吃苹果对身体好”这样的判断。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的宾语应是具体的物品，不能与“吃苹果对身体好”搭配。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，后面不能带小句作宾语。"}], "explanations": {"相信": "正确：“相信吃苹果对身体好”是一个判断，符合“很多人”的语境。", "参观": "语义：“参观”的对象是场所或展览，不能带“吃苹果对身体好”这样的判断。", "搬运": "搭配：“搬运”的宾语应是具体的物品，不能与“吃苹果对身体好”搭配。", "生长": "配价：“生长”是不及物动词，后面不能带小句作宾语。"}, "sentence_index": 6, "correct_answer": "相信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我相信妹妹的生日礼物。", "explanation": "这里应该用〈准备〉。相信接的是判断、人或事情的真实性，不能接“礼物”这类物品；准备礼物要用〈准备〉。"}, {"text": "我很相信这个假期。", "explanation": "这里应该用〈享受〉。相信接的是判断或事情的真实性，不表示享受时光；享受假期要用〈享受〉。"}, {"text": "我相信黑夜。", "explanation": "这里应该用〈害怕〉。相信不能表示心里的惧怕，表示害怕要用〈害怕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈从来没相信了我的话。", "corrected_sentence": "妈妈从来没相信过我的话。", "error_description": "“从来没有……过”结构中应用“过”，不能用“了”。错误形式：从来没相信了；正确形式：从来没相信过。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没相信了他说的话。", "corrected_sentence": "我没相信他说的话。", "error_description": "错误：用“没”否定的动作不能再加“了”。错误形式：没相信了；正确形式：没相信。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "反义：“大”与“小”相对，表示体积、面积、数量等超过比较对象。"}, {"text": "重", "is_correct": false, "explanation": "无关：“重”指分量大或程度深，与“小”不构成反义或近义关系。"}, {"text": "快", "is_correct": false, "explanation": "无关：“快”指速度高，与“小”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无关：“深”指距离或程度深，与“小”不构成反义关系。"}], "correct_answer": "大", "explanations": {"大": "反义：“大”与“小”相对，表示体积、面积、数量等超过比较对象。", "重": "无关：“重”指分量大或程度深，与“小”不构成反义或近义关系。", "快": "无关：“快”指速度高，与“小”没有反义关系。", "深": "无关：“深”指距离或程度深，与“小”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "反义：“大”与“小”相对，表示体积、面积、数量等超过比较对象。"}, {"text": "远", "is_correct": false, "explanation": "无关：“远”指距离长，与“小”不构成反义或近义关系。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”指物体上下两面之间的距离大，与“小”没有反义关系。"}, {"text": "暖", "is_correct": false, "explanation": "无关：“暖”指温度适中偏高，与“小”不构成反义关系。"}], "correct_answer": "大", "explanations": {"大": "反义：“大”与“小”相对，表示体积、面积、数量等超过比较对象。", "远": "无关：“远”指距离长，与“小”不构成反义或近义关系。", "厚": "无关：“厚”指物体上下两面之间的距离大，与“小”没有反义关系。", "暖": "无关：“暖”指温度适中偏高，与“小”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在体积、面积、数量、力量等方面不及一般的或比较的对象（与“大”相对）。", "primary_collocate": null, "pronunciation": "xiǎo", "ipa": "ɕjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他们认为，这些做法更适应本地环境，对自然的伤害也小。", "target_word": "小", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这件衣服太小了，我穿不下。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天风很小，我们可以出去玩。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的房子比他家的小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子太小，只能装一点水。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视的声音太小，我听不清。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年下的雨比去年小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这双鞋太小，我的脚很疼。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的力气小，搬不动这张桌子。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方太小，放不下三张床。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小", "label": "重叠"}], "register": "中性", "sense_fingerprint": "与“大”相对，体积、面积、数量、力量等不及比较对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），指体积、面积、数量、力量等不及一般或比较的对象。"}, {"text": "笑", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。"}, {"text": "校", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。"}, {"text": "想", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。"}, {"text": "消", "is_correct": false, "explanation": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），指体积、面积、数量、力量等不及一般或比较的对象。", "笑": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。", "校": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。", "想": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。", "消": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“对自然的伤害也小”指危害较轻，“小”与“伤害”搭配自然。"}, {"text": "好", "is_correct": false, "explanation": "语义：“好”是褒义，与“伤害”的负面含义冲突，“伤害也好”说不通。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能修饰“伤害”。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌美好，不能用来形容“伤害”。"}], "explanations": {"小": "正确：“对自然的伤害也小”指危害较轻，“小”与“伤害”搭配自然。", "好": "语义：“好”是褒义，与“伤害”的负面含义冲突，“伤害也好”说不通。", "厚": "搭配：“厚”形容物体的厚度，不能修饰“伤害”。", "漂亮": "体貌：“漂亮”形容外貌美好，不能用来形容“伤害”。"}, "sentence_index": 0, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来参加比赛的人很小，只有五个。", "explanation": "这里应该用〈少〉。“小”说体积不大，说人数少要用“少”；“人很小”会被理解为人的个子或年龄小。"}, {"text": "我家离学校很小，要坐一个小时车。", "explanation": "这里应该用〈远〉。“小”说体积、数量不大，说距离要用“远”，“离学校很小”不这么说。"}, {"text": "这间屋子的温度很小，大家都冷得发抖。", "explanation": "这里应该用〈低〉。“小”说体积、面积、数量不大，不说温度高低；温度不高要用“低”，“温度很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），指体积、面积、数量、力量等不及一般或比较的对象。"}, {"text": "脚", "is_correct": false, "explanation": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。"}, {"text": "效", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。"}, {"text": "险", "is_correct": false, "explanation": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。"}, {"text": "享", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），指体积、面积、数量、力量等不及一般或比较的对象。", "脚": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。", "效": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。", "险": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。", "享": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“比去年小”指雨量比去年少，“小”用于数量，句意通顺。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”形容宽度，不能用来修饰雨量。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度或身高，不能用于雨量。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”指速度，与“雨量”的比较不相符，句意不通。"}], "explanations": {"小": "正确：“比去年小”指雨量比去年少，“小”用于数量，句意通顺。", "窄": "搭配：“窄”形容宽度，不能用来修饰雨量。", "矮": "体貌：“矮”形容高度或身高，不能用于雨量。", "慢": "语义：“慢”指速度，与“雨量”的比较不相符，句意不通。"}, "sentence_index": 6, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次见面的时间很小，我们聊得很开心。", "explanation": "这里应该用〈短〉。“小”说体积或数量不大，说时间长短要用“短”，“时间很小”不这么用。"}, {"text": "这列火车跑得很小。", "explanation": "这里应该用〈快〉。“小”说体积、面积、数量不大，不用来形容“跑得”的快慢；说快慢要用“快”或“慢”，“跑得很小”不这么用。"}, {"text": "他们之间的感情很小，几乎不往来。", "explanation": "这里应该用〈淡〉。“小”说大小、多少，不说感情的深浅；感情淡薄要用“淡”，“感情很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子小装不下那台电脑。", "corrected_sentence": "这个箱子小得装不下那台电脑。", "error_description": "补语错误：“小”作谓语时后接补语“装不下”，中间须用“得”连接，应说“小得装不下”；漏掉“得”，“小装不下”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间卧室小很，放不下一张大床。", "corrected_sentence": "这间卧室很小，放不下一张大床。", "error_description": "位置错误：“很”是程度副词，应放在形容词前，说“很小”，不说“小很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
