INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一个地方（比如省、市、县）负责管理公共事务的机构和组织。", "primary_collocate": null, "pronunciation": "dāng dì zhèng fǔ", "ipa": "tɑŋ˥ ti˥˩ ʈʂɤŋ˥˩ fu˨˩˦", "syllable_count": 4, "sentences": [{"text": "当地政府也开始重视这些传统智慧，鼓励农民结合现代科技使用它们。", "target_word": "当地政府", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "当地政府在河边修了一座新桥。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府给老人发了生活补助。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨以后，当地政府马上通知了居民。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府打算明年建一所新学校。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子的路是当地政府修的。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府鼓励年轻人回家工作。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客太多，当地政府限制了人数。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先问问当地政府能不能在这里开店。", "target_word": "当地政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地政府每个月都会检查河水。", "target_word": "当地政府", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "省、市、县等某地负责管理公共事务的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当地政府", "is_correct": true, "explanation": "正确：“当地政府”是有能力“重视”并“鼓励”农民的主体，句意通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“重视”和“鼓励”要求有意识的施事，“椅子”不能作其主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能“重视”传统智慧或“鼓励”农民，句意不通。"}, {"text": "河水", "is_correct": false, "explanation": "语义：“河水”是自然物，不能“重视”或“鼓励”他人，句意不通。"}], "explanations": {"当地政府": "正确：“当地政府”是有能力“重视”并“鼓励”农民的主体，句意通顺。", "椅子": "配价：“重视”和“鼓励”要求有意识的施事，“椅子”不能作其主语。", "冰箱": "语义：“冰箱”是家用电器，不能“重视”传统智慧或“鼓励”农民，句意不通。", "河水": "语义：“河水”是自然物，不能“重视”或“鼓励”他人，句意不通。"}, "sentence_index": 0, "correct_answer": "当地政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当地政府每天都在街上卖水果。", "explanation": "这里应该用〈水果摊〉。当地政府管理公共事务，不做买卖；卖水果要靠水果摊或商店，不是当地政府的工作。"}, {"text": "当地政府每天都生产很多汽车。", "explanation": "这里应该用〈工厂〉。当地政府管理公共事务，不生产产品，生产汽车是工厂的工作。"}, {"text": "这起纠纷由当地政府判决。", "explanation": "这里应该用〈法院〉。判决案件由法院负责，当地政府不负责审判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当地政府", "is_correct": true, "explanation": "正确：“当地政府”是能够“鼓励”年轻人回家工作的管理机构，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“鼓励”需要有意识的施事，“桌子”不能作其主语。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：“公交车”是交通工具，不能“鼓励”年轻人回家工作，句意不通。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：“动物园”是场所，不能发出“鼓励”的行为，句意不通。"}], "explanations": {"当地政府": "正确：“当地政府”是能够“鼓励”年轻人回家工作的管理机构，句意通顺。", "桌子": "配价：“鼓励”需要有意识的施事，“桌子”不能作其主语。", "公交车": "语义：“公交车”是交通工具，不能“鼓励”年轻人回家工作，句意不通。", "动物园": "语义：“动物园”是场所，不能发出“鼓励”的行为，句意不通。"}, "sentence_index": 6, "correct_answer": "当地政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当地政府每天都接诊很多病人。", "explanation": "这里应该用〈医院〉。当地政府管理公共事务，不接诊病人，接诊病人要用医院。"}, {"text": "当地政府每年都招收很多新生。", "explanation": "这里应该用〈学校〉。招收新生是学校的职能，当地政府不负责招生。"}, {"text": "当地政府每天都给客户办理存款。", "explanation": "这里应该用〈银行〉。当地政府管理公共事务，不办理存款业务，存款要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当地政府上个月被公布了新的交通规划。", "corrected_sentence": "当地政府上个月公布了新的交通规划。", "error_description": "错误：“当地政府被公布了”；正确：“当地政府公布了”。“当地政府”是发出“公布”动作的主体，不能用“被”字句，应删去“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个当地政府们都支持这个项目。", "corrected_sentence": "三个当地政府都支持这个项目。", "error_description": "词缀错误：“政府”是机构名词，后面不加“们”；应说“三个当地政府”，不能说“当地政府们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
