INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人与人之间，或人与自然等事物之间彼此交往、共处，并在互动中形成某种关系。", "primary_collocate": null, "pronunciation": "xiāng chǔ", "ipa": "ɕiɑŋ˥ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些传统的水资源保护实践，体现了人与自然和谐相处的智慧。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我和新同事相处得很好。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相处了三年，感情很深。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和不同性格的人相处，需要耐心。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该学会与邻居和平相处。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生相处得像朋友一样。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很好相处，大家都喜欢她。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刚认识，还不太会相处。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们相处过一个夏天，成了好朋友。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在一起相处，要互相帮助。", "target_word": "相处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相处了", "label": "完成体"}, {"form": "相处过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "人与人或人与自然等彼此交往、共处并形成关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相处", "is_correct": true, "explanation": "正确。“和谐相处”指人与自然彼此和睦地共存，与句子的语义和搭配相合。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：“和谐”与“竞争”意思相反，“和谐竞争”自相矛盾，与句子表达的意思不符。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“和谐”与“破坏”相矛盾，人与自然的关系不会被说成“和谐破坏”。"}, {"text": "打架", "is_correct": false, "explanation": "语义：“和谐”与“打架”相矛盾，“人与自然和谐打架”说不通。"}], "explanations": {"相处": "正确。“和谐相处”指人与自然彼此和睦地共存，与句子的语义和搭配相合。", "竞争": "语义：“和谐”与“竞争”意思相反，“和谐竞争”自相矛盾，与句子表达的意思不符。", "破坏": "语义：“和谐”与“破坏”相矛盾，人与自然的关系不会被说成“和谐破坏”。", "打架": "语义：“和谐”与“打架”相矛盾，“人与自然和谐打架”说不通。"}, "sentence_index": 0, "correct_answer": "相处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国相处了协议。", "explanation": "这里应该用〈签订〉。“相处”不能带“协议”作宾语，两国签订协议要用〈签订〉。"}, {"text": "两家公司相处开发了新产品。", "explanation": "这里应该用〈合作〉。“相处”强调人与人之间的相处关系，不能用来说共同做事或开发产品。"}, {"text": "我们相处了很多想法。", "explanation": "这里应该用〈交流〉。“相处”不能直接带“想法”作宾语，交换意见要用〈交流〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相处", "is_correct": true, "explanation": "正确。“很好相处”说她容易和人融洽地交往，与“大家都喜欢她”的语境相合。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“很好吵架”说她爱和人争吵，与“大家都喜欢她”的语境矛盾。"}, {"text": "说谎", "is_correct": false, "explanation": "语义：“很好说谎”说她爱撒谎，与“大家都喜欢她”的语境相矛盾。"}, {"text": "发火", "is_correct": false, "explanation": "语义：“很好发火”说她脾气差、容易生气，与“大家都喜欢她”相矛盾。"}], "explanations": {"相处": "正确。“很好相处”说她容易和人融洽地交往，与“大家都喜欢她”的语境相合。", "吵架": "语义：“很好吵架”说她爱和人争吵，与“大家都喜欢她”的语境矛盾。", "说谎": "语义：“很好说谎”说她爱撒谎，与“大家都喜欢她”的语境相矛盾。", "发火": "语义：“很好发火”说她脾气差、容易生气，与“大家都喜欢她”相矛盾。"}, "sentence_index": 6, "correct_answer": "相处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "代表团相处了三个国家。", "explanation": "这里应该用〈访问〉。“相处”指人与人之间的交往，不能用于到不同国家去拜访。"}, {"text": "志愿者相处了灾区的人。", "explanation": "这里应该用〈帮助〉。“相处”表示彼此交往、共同生活，不表示施以援助。"}, {"text": "他把这件事相处得很好。", "explanation": "这里应该用〈处理〉。“相处”的对象是人，不能用来说处理事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和爸爸相处的很融洽。", "corrected_sentence": "我和爸爸相处得很融洽。", "error_description": "结构助词错误：动词与程度补语之间应用“得”，不能用“的”。正确的说法是“我和爸爸相处得很融洽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前没有相处了，所以不太了解。", "corrected_sentence": "我们以前没有相处过，所以不太了解。", "error_description": "助词错误：“没有”后面表示未曾经历的动作要用“过”，不能用“了”。正确的说法是“我们以前没有相处过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
