INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某种资源或物品的数量非常少，不能满足需要。", "primary_collocate": null, "pronunciation": "xī quē xìng", "ipa": "ɕi˥ tɕʰɥe˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "在极端干旱的环境中，水资源的稀缺性催生了人类文明最为精妙的生存智慧。", "target_word": "稀缺性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水的稀缺性让人们学会了节约。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄金的稀缺性使它价格很高。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学认为稀缺性是价格的基础。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种矿产的稀缺性越来越明显。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地的稀缺性让城市房价上涨。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人才的稀缺性是公司面临的问题。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油的稀缺性影响着世界经济。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为稀缺性，这种药材卖得很贵。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提醒大家注意淡水的稀缺性。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "资源或物品数量很少、不能满足需要的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺性", "is_correct": true, "explanation": "正确。“稀缺性”指资源少、不能满足需要，与“极端干旱”的语境吻合。"}, {"text": "丰富性", "is_correct": false, "explanation": "语义：“丰富性”指数量多，与“极端干旱”的语境相反，无法解释生存智慧的来源。"}, {"text": "便利性", "is_correct": false, "explanation": "搭配：“便利性”多用于交通、服务等，不说“水资源的便利性”。"}, {"text": "充足性", "is_correct": false, "explanation": "语义：“充足性”指足够，与“极端干旱”的语境相反。"}], "explanations": {"稀缺性": "正确。“稀缺性”指资源少、不能满足需要，与“极端干旱”的语境吻合。", "丰富性": "语义：“丰富性”指数量多，与“极端干旱”的语境相反，无法解释生存智慧的来源。", "便利性": "搭配：“便利性”多用于交通、服务等，不说“水资源的便利性”。", "充足性": "语义：“充足性”指足够，与“极端干旱”的语境相反。"}, "sentence_index": 0, "correct_answer": "稀缺性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的稀缺性很红。", "explanation": "这里应该用〈颜色〉。“稀缺性”指东西少的属性，不能用来描述颜色。"}, {"text": "这种水果的稀缺性很甜。", "explanation": "这里应该用〈味道〉。“稀缺性”指东西少的属性，不能用来描述味道甜不甜。"}, {"text": "我在超市买到了一种稀缺性。", "explanation": "“稀缺性”指事物的属性，不是可以买卖的东西；应说“买到了很稀缺的东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺性", "is_correct": true, "explanation": "正确。“人才的稀缺性”是企业常见的问题，句意通顺。"}, {"text": "灵活性", "is_correct": false, "explanation": "语义：“灵活性”是正面特点，不能说它是公司面临的问题。"}, {"text": "普遍性", "is_correct": false, "explanation": "语义：“普遍性”指到处都有，与“是公司面临的问题”的语境不符。"}, {"text": "时效性", "is_correct": false, "explanation": "搭配：“时效性”多用于信息、政策，不说“人才的时效性”。"}], "explanations": {"稀缺性": "正确。“人才的稀缺性”是企业常见的问题，句意通顺。", "灵活性": "语义：“灵活性”是正面特点，不能说它是公司面临的问题。", "普遍性": "语义：“普遍性”指到处都有，与“是公司面临的问题”的语境不符。", "时效性": "搭配：“时效性”多用于信息、政策，不说“人才的时效性”。"}, "sentence_index": 6, "correct_answer": "稀缺性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的供水出现了稀缺性。", "explanation": "这里应该用〈短缺〉。“稀缺性”指资源本身的属性，不能说“出现稀缺性”；供应不足的状况要用“短缺”。"}, {"text": "这位老师的稀缺性很受学生欢迎。", "explanation": "“稀缺性”指资源的属性，不用来形容人的才能；说人的才能要用“难得”。"}, {"text": "我们用节水的稀缺性来解决缺水问题。", "explanation": "这里应该用〈办法〉。“稀缺性”指资源少的属性，不能作为解决问题的手段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种木材的稀缺性越来越多。", "corrected_sentence": "这种木材的稀缺性越来越明显。", "error_description": "“稀缺性”是一种属性，不能说“多”；应说“越来越明显”。正确形式：稀缺性越来越明显。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "钻石很稀缺性，所以价格很高。", "corrected_sentence": "钻石很稀缺，所以价格很高。", "error_description": "“稀缺性”是名词，不能受“很”修饰作谓语；作谓语要用形容词“稀缺”。正确形式：很稀缺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
