INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "单位水量产生最大效益的能力", "primary_collocate": null, "pronunciation": "lì yòng xiào lǜ", "ipa": "li˥˩ yʊŋ˥˩ ɕiɑʊ˥˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "此类传统实践往往植根于长期的环境观察与代际传承，其核心在于最大化水分利用效率，同时维持生态系统的可持续性。", "target_word": "利用效率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "滴灌能提高水的利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种农作物的水分利用效率很高。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱地区更要重视水资源利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的灌溉系统提高了灌溉水的利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物用同样的水长得更多，水分利用效率更高。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "覆盖地膜可以提高土壤水的利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民改用节水灌溉后，水的利用效率提高了。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家农业用水的利用效率还不高。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的利用效率低，就会浪费很多水。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "水资源被利用的效益高低（如水分利用效率、水资源利用效率）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63fd2d9a-045d-4a1d-8a34-0bec3e8012e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“水分价格”不成立，水分的多少没有价格可以被最大化。"}, {"text": "利用效率", "is_correct": true, "explanation": "正确。“水分利用效率”指单位水量产生效益的能力，与“最大化”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观特征，不是可以最大化来追求的指标，不能用于“水分”。"}, {"text": "含糖量", "is_correct": false, "explanation": "搭配：“含糖量”多用于食品饮料，不能与“水分”搭配作“最大化”的对象。"}], "explanations": {"价格": "语义：“水分价格”不成立，水分的多少没有价格可以被最大化。", "利用效率": "正确。“水分利用效率”指单位水量产生效益的能力，与“最大化”搭配，符合句意。", "颜色": "语义：“颜色”是外观特征，不是可以最大化来追求的指标，不能用于“水分”。", "含糖量": "搭配：“含糖量”多用于食品饮料，不能与“水分”搭配作“最大化”的对象。"}, "sentence_index": 0, "correct_answer": "利用效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的水的利用效率很高，适合去游泳。", "explanation": "这里应该用〈水温〉。利用效率指水的效益高低，说水的冷热要用〈水温〉。"}, {"text": "这条河的水的利用效率很好，鱼很多。", "explanation": "这里应该用〈水质〉。利用效率不描述水的清洁程度，说水好不好要用〈水质〉。"}, {"text": "他的利用效率比去年重了三公斤。", "explanation": "这里应该用〈体重〉。利用效率不能用于人的重量，说体重增减要用〈体重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "销量", "is_correct": false, "explanation": "语义：“销量”是商品卖出的数量，不能作为“土壤水”的修饰对象。"}, {"text": "利用效率", "is_correct": true, "explanation": "正确。“土壤水的利用效率”指土壤水被利用的效益，与“提高”搭配，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，与土壤水无关，不能被提高。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“驾照”是驾驶许可，不能与“土壤水”搭配作提高的对象。"}], "explanations": {"销量": "语义：“销量”是商品卖出的数量，不能作为“土壤水”的修饰对象。", "利用效率": "正确。“土壤水的利用效率”指土壤水被利用的效益，与“提高”搭配，符合句意。", "身高": "体貌：“身高”是人的外形特征，与土壤水无关，不能被提高。", "驾照": "搭配：“驾照”是驾驶许可，不能与“土壤水”搭配作提高的对象。"}, "sentence_index": 6, "correct_answer": "利用效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项工程的利用效率很快，两个月就完成了。", "explanation": "这里应该用〈进度〉。利用效率说资源被用得是否高效，说工程快慢要用〈进度〉。"}, {"text": "明天的利用效率会降到零下。", "explanation": "这里应该用〈温度〉。利用效率不指冷热，说气温下降要用〈温度〉。"}, {"text": "这家餐厅的利用效率越来越旺。", "explanation": "这里应该用〈人气〉。利用效率指资源被用到的程度，不指受欢迎的程度，说餐厅受欢迎要用〈人气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统投入使用后，水的利用效率提高得一倍。", "corrected_sentence": "这套系统投入使用后，水的利用效率提高了一倍。", "error_description": "补语错误：“提高”接表示增加幅度的数量补语时，完成的变化要说“提高了一倍”，不能说“提高得一倍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套节水系统的一个水的利用效率很高。", "corrected_sentence": "这套节水系统的水的利用效率很高。", "error_description": "量词错误：“水”是物质名词，不能用个体量词“一个”计量，“一个水”不成立；应去掉“一个”，说“水的利用效率很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a5c6e7-f1d9-4de4-aeed-bd7437ca25e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
