INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坎儿井是新疆干旱地区利用地下水源的古老灌溉工程，通过地下暗渠将地下水引至地面。", "primary_collocate": null, "pronunciation": "kǎn ér jǐng", "ipa": "kʰan˨˩ ɚ˧˥ tɕiŋ˨˩", "syllable_count": 3, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "坎儿井", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "坎儿井在新疆已经有很多年了。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新疆很干，农民用坎儿井浇地。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井把地下的水引到田里。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条坎儿井有几百年的历史。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去吐鲁番看了坎儿井。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井的水在地下流，太阳晒不到。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，坎儿井是祖先留下的。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有坎儿井，沙漠边的人才有水喝。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井的水一年四季都有。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "坎兒井", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新疆干旱区利用地下暗渠引水的古老灌溉工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c14fd65d-7562-43e3-b9a1-66b88150ec98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坎儿井", "is_correct": true, "explanation": "正确。“如坎儿井（qanat）”指地下引水的暗渠，与句中的灌溉网络和融雪水相符。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是地面上的蓄水工程，不是地下引水的暗渠，与句意不符。"}, {"text": "风车", "is_correct": false, "explanation": "搭配：风车不是引水的地下通道，“如风车（qanat）”对不上括注的意思。"}, {"text": "沙丘", "is_correct": false, "explanation": "语义：沙丘是风吹沙子堆成的，不能用来把高山融雪水引至农田。"}], "explanations": {"坎儿井": "正确。“如坎儿井（qanat）”指地下引水的暗渠，与句中的灌溉网络和融雪水相符。", "水库": "语义：水库是地面上的蓄水工程，不是地下引水的暗渠，与句意不符。", "风车": "搭配：风车不是引水的地下通道，“如风车（qanat）”对不上括注的意思。", "沙丘": "语义：沙丘是风吹沙子堆成的，不能用来把高山融雪水引至农田。"}, "sentence_index": 0, "correct_answer": "坎儿井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在吐鲁番看了坎儿井，它是用来防御敌人的城楼。", "explanation": "这里应该用〈城楼〉。城楼是建在城墙上用来防御的建筑；坎儿井是地下引水的水渠，不能用来防御。"}, {"text": "坎儿井把地面的河水引到田里。", "explanation": "这里应该用〈水渠〉。坎儿井是地下暗渠，引的是地下水，不走地面，不能说引地面的河水。"}, {"text": "坎儿井是战争时用来躲藏的。", "explanation": "这里应该用〈地道〉。坎儿井是引水的水渠，不是躲藏用的通道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坎儿井", "is_correct": true, "explanation": "正确。坎儿井是地下的暗渠，水在地下流，太阳晒不到。"}, {"text": "水塔", "is_correct": false, "explanation": "语义：水塔是立在地面上的高塔，水储在塔内，不会在地下流，与句意不符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：大海是地表的大水域，“大海的水在地下流”不成立。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊的水在地表，太阳是晒得到的，与“太阳晒不到”矛盾。"}], "explanations": {"坎儿井": "正确。坎儿井是地下的暗渠，水在地下流，太阳晒不到。", "水塔": "语义：水塔是立在地面上的高塔，水储在塔内，不会在地下流，与句意不符。", "大海": "搭配：大海是地表的大水域，“大海的水在地下流”不成立。", "湖泊": "语义：湖泊的水在地表，太阳是晒得到的，与“太阳晒不到”矛盾。"}, "sentence_index": 6, "correct_answer": "坎儿井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "坎儿井在冬天会结冰，人们在上面滑冰。", "explanation": "这里应该用〈冰湖〉。冰湖冬天结冰后可供人滑冰；坎儿井是地下引水的暗渠，水在地下流，人不能在上面滑冰。"}, {"text": "坎儿井是一种在山顶上修的高塔。", "explanation": "这里应该用〈烽火台〉。烽火台是建在山顶、用来传递军情的高台；坎儿井是地下的水渠，不是地面上的高塔。"}, {"text": "坎儿井让乘客快速到达市中心。", "explanation": "这里应该用〈地铁〉。地铁是在地下运行、载客到市中心的交通工具；坎儿井是引水的水渠，不能载客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子里有一把坎儿井。", "corrected_sentence": "村子里有一条坎儿井。", "error_description": "量词错误：坎儿井应用“条”，“把”用于有柄的器具。正确说法是“一条坎儿井”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吐鲁番有一张很长的坎儿井。", "corrected_sentence": "吐鲁番有一条很长的坎儿井。", "error_description": "量词错误：坎儿井是长长的地下水渠，应用“条”；“张”用于纸、桌子等平面的东西。正确说法是“一条很长的坎儿井”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
