INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12810, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指雪融化后形成的水，通常出现在春季或气温升高时。", "primary_collocate": null, "pronunciation": "róng xuě shuǐ", "ipa": "ʐʊŋ˧˥ ɕɥe˨˩˦ ʂueɪ˨˩˦", "syllable_count": 3, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "融雪水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "春天到了，融雪水流进了小河。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的融雪水很干净，也很凉。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用融雪水浇地。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "融雪水让河里的水多了起来。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上到处都是融雪水，鞋都湿了。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "融雪水从屋顶慢慢滴下来。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子喝的是山里的融雪水。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变暖后，融雪水会流到山下。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在融雪水旁边玩儿。", "target_word": "融雪水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "春天或气温升高时雪化成的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融雪水", "is_correct": true, "explanation": "融雪水指雪化成的水，此处作“引至”的宾语，与“将高山……引至低地农田”相合。"}, {"text": "石块", "is_correct": false, "explanation": "语义：“引至”输送的是水等流体，石块不能经灌溉网络引送到农田。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是水汽凝结成的，不是可以用渠道引送的液体，无法引至农田。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子是固体颗粒，不能像水一样经渠道引至农田。"}], "explanations": {"融雪水": "融雪水指雪化成的水，此处作“引至”的宾语，与“将高山……引至低地农田”相合。", "石块": "语义：“引至”输送的是水等流体，石块不能经灌溉网络引送到农田。", "云": "语义：云是水汽凝结成的，不是可以用渠道引送的液体，无法引至农田。", "沙子": "语义：沙子是固体颗粒，不能像水一样经渠道引至农田。"}, "sentence_index": 0, "correct_answer": "融雪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场暴雨过后，马路上到处都是融雪水。", "explanation": "这里应该用〈雨水〉。融雪水指雪化后形成的水，暴雨后的积水要说雨水。"}, {"text": "他跑完步，全身都是融雪水。", "explanation": "这里应该用〈汗水〉。融雪水指雪化后的水，跑步后身上的是汗水。"}, {"text": "他哭了很久，脸上全是融雪水。", "explanation": "这里应该用〈泪水〉。融雪水指雪化后的水，脸上流的眼泪要说泪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融雪水", "is_correct": true, "explanation": "融雪水是雪化成的水，能从屋顶慢慢滴下来，符合句意。"}, {"text": "砖块", "is_correct": false, "explanation": "语义：砖块是固体，不会从屋顶滴下来。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“滴”用于液体一点一点地落，不能说歌声滴下来。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是飘落的，不会“滴”下来，“滴”指液体一滴一滴落下。"}], "explanations": {"融雪水": "融雪水是雪化成的水，能从屋顶慢慢滴下来，符合句意。", "砖块": "语义：砖块是固体，不会从屋顶滴下来。", "歌声": "搭配：“滴”用于液体一点一点地落，不能说歌声滴下来。", "树叶": "语义：树叶是飘落的，不会“滴”下来，“滴”指液体一滴一滴落下。"}, "sentence_index": 6, "correct_answer": "融雪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "融雪水放在桌子上，很快就化了。", "explanation": "这里应该用〈冰块〉。融雪水已经是液体，不会再“化”，固体的冰块放久了才会化。"}, {"text": "早晨的大雾很浓，空气里弥漫着融雪水。", "explanation": "这里应该用〈雾气〉。融雪水是雪化后的水，弥漫在空中的雾气不是融雪水。"}, {"text": "他的钢笔漏墨了，桌上流的全是融雪水。", "explanation": "这里应该用〈墨水〉。融雪水指雪化后的水，钢笔里漏出的要说墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天，一只融雪水流进了小河。", "corrected_sentence": "春天，一股融雪水流进了小河。", "error_description": "错误在于量词：融雪水是液体，应用“股”，“只”用于动物等，不能修饰融雪水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋檐下的一只融雪水滴得很慢。", "corrected_sentence": "屋檐下的融雪水滴得很慢。", "error_description": "错误在于在“融雪水”前加了量词“只”。融雪水是液体，不能用“只”计量，应直接说“融雪水”或用“股”“滴”等词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
