INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水、电等引导输送到某处。", "primary_collocate": null, "pronunciation": "yǐn zhì", "ipa": "in˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "引至", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人们把河水引至山下的村子。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条水渠将山上的泉水引至田里。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们修了一条管道，把湖水引至城里。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把井水引至菜地，浇灌蔬菜。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师设计了新方案，将河水引至工厂。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们想把山泉引至每家每户。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河的水可以引至果园。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用竹管把泉水引至院子里。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府计划将海水引至干旱的地区。", "target_word": "引至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "把水等引导输送到某处，书面用法，常见于「将/把……引至……」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把水等引导输送到某处，正是本句的词。"}, {"text": "银制", "is_correct": false, "explanation": "yín 与 yǐn 声调不同，“银制”指用银做的。"}, {"text": "印制", "is_correct": false, "explanation": "yìn 与 yǐn 声调不同，“印制”意思是印刷制作。"}, {"text": "引子", "is_correct": false, "explanation": "zi（轻声）与 zhì 声母（z/zh）和声调不同，“引子”指开头或引语。"}], "explanations": {"引至": "引至：把水等引导输送到某处，正是本句的词。", "银制": "yín 与 yǐn 声调不同，“银制”指用银做的。", "印制": "yìn 与 yǐn 声调不同，“印制”意思是印刷制作。", "引子": "zi（轻声）与 zhì 声母（z/zh）和声调不同，“引子”指开头或引语。"}, "sentence_index": null, "correct_answer": "引至"}, "level_3": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把水引导输送到某处，与“将高山融雪水……低地农田”相合。"}, {"text": "关至", "is_correct": false, "explanation": "语义：关是关闭，不能指把水输送到农田。"}, {"text": "抱至", "is_correct": false, "explanation": "搭配：“抱”指用手臂搂，不用于把水输送到某处。"}, {"text": "烧至", "is_correct": false, "explanation": "语义：烧是加热，“烧至农田”没有意义。"}], "explanations": {"引至": "引至：把水引导输送到某处，与“将高山融雪水……低地农田”相合。", "关至": "语义：关是关闭，不能指把水输送到农田。", "抱至": "搭配：“抱”指用手臂搂，不用于把水输送到某处。", "烧至": "语义：烧是加热，“烧至农田”没有意义。"}, "sentence_index": 0, "correct_answer": "引至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们把礼物引至朋友家。", "explanation": "这里应该用〈送〉。引至指把水、电等引导输送，送礼物应说“送”。"}, {"text": "工人用车把煤引至码头。", "explanation": "这里应该用〈运〉。引至用于水、电等流体，煤是固体，运输应说“运”。"}, {"text": "他把书引至北京。", "explanation": "这里应该用〈寄〉。引至不用于邮件，寄书应说“寄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12811, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把水等引导输送到某处，正是本句的词。"}, {"text": "隐士", "is_correct": false, "explanation": "sh 与 zh 声母不同，“隐士”指隐居的人，不是输送。"}, {"text": "银质", "is_correct": false, "explanation": "yín 与 yǐn 声调不同，“银质”指银的质地。"}, {"text": "音质", "is_correct": false, "explanation": "yīn 与 yǐn 声调不同，“音质”指声音的质量。"}], "explanations": {"引至": "引至：把水等引导输送到某处，正是本句的词。", "隐士": "sh 与 zh 声母不同，“隐士”指隐居的人，不是输送。", "银质": "yín 与 yǐn 声调不同，“银质”指银的质地。", "音质": "yīn 与 yǐn 声调不同，“音质”指声音的质量。"}, "sentence_index": null, "correct_answer": "引至"}, "level_3": {"options": [{"text": "引至", "is_correct": true, "explanation": "引至：把山泉引导输送到每家每户，符合句意。"}, {"text": "砍至", "is_correct": false, "explanation": "语义：砍是用刀斩，不能把山泉砍至每户。"}, {"text": "扛至", "is_correct": false, "explanation": "搭配：“扛”用于搬运重物，山泉是水，不宜用“扛”输送。"}, {"text": "装至", "is_correct": false, "explanation": "语义：装是装载，山泉不能被装到每家每户。"}], "explanations": {"引至": "引至：把山泉引导输送到每家每户，符合句意。", "砍至": "语义：砍是用刀斩，不能把山泉砍至每户。", "扛至": "搭配：“扛”用于搬运重物，山泉是水，不宜用“扛”输送。", "装至": "语义：装是装载，山泉不能被装到每家每户。"}, "sentence_index": 6, "correct_answer": "引至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府计划把粮食引至灾区。", "explanation": "这里应该用〈调〉。引至用于水、电等流体，调拨粮食要用“调”。"}, {"text": "工人把桌子引至屋里。", "explanation": "这里应该用〈搬〉。引至用于流体或管线，搬桌子要用“搬”。"}, {"text": "他们把沙子引至墙角。", "explanation": "这里应该用〈堆〉。引至不用于沙子，把沙子放到墙角应说“堆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人山泉引至果园。", "corrected_sentence": "工人把山泉引至果园。", "error_description": "错误在于漏掉“把”：“把……引至……”结构中，“把”要引出被引导的东西，应说“工人把山泉引至果园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新建的水渠把溪水引至在果园。", "corrected_sentence": "新建的水渠把溪水引至果园。", "error_description": "错误在于补语重复：“引至”的“至”已表示到达，后面不能再加“在”。应说“引至果园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
