INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水流产生的能量，常用于发电或作为动力来源。", "primary_collocate": null, "pronunciation": "shuǐ lì", "ipa": "ʂweɪ˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这座小镇利用落差很大的河流，让水力带动发电机，至今仍被能源专家视为清洁发电的典范。", "target_word": "水力", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个小镇的电主要靠水力来产生。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里水多，所以水力很丰富。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的水力非常丰富，适合发电。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老工厂过去用水力带动机器。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家想多用水力，少用煤。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水落差大，水力就很强。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想利用水力给村子发电。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水多的年份，水力更充足。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与煤相比，水力不会产生污染。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水力发电", "label": "复合"}, {"form": "水力资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "水流产生的能量，用于发电或提供动力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水力", "is_correct": true, "explanation": "水力（shuǐ lì）指水流产生的能量，是这个词的正确读音。"}, {"text": "水里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是在水中。"}, {"text": "水梨", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是一种水果。"}, {"text": "税利", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是税收和利润。"}], "explanations": {"水力": "水力（shuǐ lì）指水流产生的能量，是这个词的正确读音。", "水里": "lǐ（第三声）与 lì（第四声）声调不同，意思是在水中。", "水梨": "lí（第二声）与 lì（第四声）声调不同，意思是一种水果。", "税利": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是税收和利润。"}, "sentence_index": null, "correct_answer": "水力"}, "level_3": {"options": [{"text": "水力", "is_correct": true, "explanation": "水力指水流产生的能量，此处用来带动发电机，与“发电”的语境一致。"}, {"text": "电力", "is_correct": false, "explanation": "语义：电力是发电的结果，不能用来带动发电机。"}, {"text": "水位", "is_correct": false, "explanation": "语义：水位指水面的高低，本身不能带动发电机。"}, {"text": "水质", "is_correct": false, "explanation": "语义：水质指水的好坏，与带动发电机无关。"}], "explanations": {"水力": "水力指水流产生的能量，此处用来带动发电机，与“发电”的语境一致。", "电力": "语义：电力是发电的结果，不能用来带动发电机。", "水位": "语义：水位指水面的高低，本身不能带动发电机。", "水质": "语义：水质指水的好坏，与带动发电机无关。"}, "sentence_index": 0, "correct_answer": "水力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车需要很大的水力才能上坡。", "explanation": "这里应该用〈动力〉。水力特指水流产生的能量，车辆自身的动力不能说水力。"}, {"text": "这个村子去年修了水力。", "explanation": "这里应该用〈水利〉。修的是水利工程，水力是能量，不能说“修”。"}, {"text": "他的水力很大，一拳就打碎了木板。", "explanation": "这里应该用〈力量〉。水力只指水流产生的能量，人的力气要用力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水力", "is_correct": true, "explanation": "水力指水流的能量，落差大则能量强，与“强”搭配。"}, {"text": "水位", "is_correct": false, "explanation": "搭配：“强”用来说力量或能量，不能用于水位。"}, {"text": "水温", "is_correct": false, "explanation": "语义：水温指水的冷热，与落差大无关。"}, {"text": "水深", "is_correct": false, "explanation": "语义：水深指水的深度，与“落差”和“强”的意思都对不上。"}], "explanations": {"水力": "水力指水流的能量，落差大则能量强，与“强”搭配。", "水位": "搭配：“强”用来说力量或能量，不能用于水位。", "水温": "语义：水温指水的冷热，与落差大无关。", "水深": "语义：水深指水的深度，与“落差”和“强”的意思都对不上。"}, "sentence_index": 6, "correct_answer": "水力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的水力来自电池。", "explanation": "这里应该用〈能量〉。水力指水流的能量，电池提供的能量不能说水力。"}, {"text": "这条河的水力很急，冲得船直晃。", "explanation": "这里应该用〈水流〉。水力指能量，形容水的流动快慢要用水流。"}, {"text": "工厂里有一台水力，正在发电。", "explanation": "这里应该去掉量词。水力是不可数的能量，不用“台”计量，“台”用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小镇靠一台水力发电。", "corrected_sentence": "这座小镇靠水力发电。", "error_description": "“水力”是表示能量的名词，不能用量词“台”计量。应去掉“一台”，说“靠水力发电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把水力磨面粉。", "corrected_sentence": "他们靠水力磨面粉。", "error_description": "表示凭借的手段要用“靠”或“用”引出，说“靠水力磨面粉”。“把”字句的宾语要是被处置的对象，而“水力”是用来磨面粉的能量，不是被处置的对象，不能用“把”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指自然界中水的各种现象及其变化规律，如河流、湖泊、海洋的水位、流量等。", "primary_collocate": null, "pronunciation": "shuǐ wén", "ipa": "ʂweɪ˨˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "水文", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "水文", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的水文资料保存得很完整。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，当地的水文情况变了。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就留意河里水文的变化，毕业后去了水文站工作。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要建桥，先得了解这里的水文。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水文变化会影响附近农民的生活。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告写了湖泊的水文和天气。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雪化了，河流的水文也变了。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的水文很复杂，渔民都知道。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水文站", "label": "复合"}, {"form": "水文地质", "label": "复合"}], "register": "书面", "sense_fingerprint": "自然界中水的现象及变化规律，如水位、流量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "水文指自然界中水的现象和变化规律，可以被专家研究，与前文相符。"}, {"text": "气象", "is_correct": false, "explanation": "语义：气象指天气现象，与输水结构和水利技术无关。"}, {"text": "医学", "is_correct": false, "explanation": "语义：医学与输水工程原理无关，医学专家不研究这类技术。"}, {"text": "水流", "is_correct": false, "explanation": "搭配：“专家”前应是学科或领域，“水流”是现象，不能说“水流专家”。"}], "explanations": {"水文": "水文指自然界中水的现象和变化规律，可以被专家研究，与前文相符。", "气象": "语义：气象指天气现象，与输水结构和水利技术无关。", "医学": "语义：医学与输水工程原理无关，医学专家不研究这类技术。", "水流": "搭配：“专家”前应是学科或领域，“水流”是现象，不能说“水流专家”。"}, "sentence_index": 0, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的水文很好，适合出门。", "explanation": "这里应该用〈气象〉。水文指水的现象和变化规律，不能用来说天气好不好。"}, {"text": "河里的水文很急，船不能过。", "explanation": "这里应该用〈水流〉。水文不指水的流动速度，形容流动要用水流。"}, {"text": "河里的水文升高了三米。", "explanation": "这里应该用〈水位〉。水文是现象和规律的总称，不能说升高多少，水位才能升高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "水文指水的现象和变化规律，水文变化会影响农民的生活，与句意相符。"}, {"text": "水文学", "is_correct": false, "explanation": "语义：“水文学”是研究水文的学科名，学科本身不会发生影响农民生活的自然变化，这里要说的是水的现象本身。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体指文字的样式，与农民的生活无关。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱指记录音乐的符号，与水和农民生活都无关。"}], "explanations": {"水文": "水文指水的现象和变化规律，水文变化会影响农民的生活，与句意相符。", "水文学": "语义：“水文学”是研究水文的学科名，学科本身不会发生影响农民生活的自然变化，这里要说的是水的现象本身。", "字体": "语义：字体指文字的样式，与农民的生活无关。", "乐谱": "语义：乐谱指记录音乐的符号，与水和农民生活都无关。"}, "sentence_index": 6, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个周末的水文很冷，别忘了带外套。", "explanation": "这里应该用〈天气〉。水文不指冷暖，说天气冷要用天气。"}, {"text": "这里的水文超过了三米。", "explanation": "这里应该用〈水深〉。水文指水的现象和变化规律，不指某处水有多深，说水深超过三米要用水深。"}, {"text": "这片海的水文很低，游泳的人很少。", "explanation": "这里应该用〈水温〉。水温指水的冷热，可以说“低”，水文不指冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年研究着水文。", "corrected_sentence": "我们去年研究过水文。", "error_description": "表示曾经做过的经历要用体态助词“过”，说“研究过水文”。“着”表示动作持续或正在进行，去年已经完成的研究不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的水文变的很复杂。", "corrected_sentence": "这里的水文变得很复杂。", "error_description": "程度补语要用“得”引出，说“变得很复杂”。“的”是定语标记，不能用来引出补语，这里用“的”是误用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
