INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12818, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指在使用过程中消耗较少的能源，通常用于描述设备或建筑节能的特点。", "primary_collocate": null, "pronunciation": "dī néng hào", "ipa": "ti˥ nɤŋ˧˥ xaʊ˥˩", "syllable_count": 3, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "低能耗", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种灯是低能耗的，用一年也不贵。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家买了一台低能耗冰箱。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子是低能耗建筑，冬天不用开太多暖气。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想做低能耗的新手机。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低能耗设备能帮学校省不少电费。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种空调不仅安静，而且低能耗。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电器时，他喜欢选低能耗的。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市鼓励大家用低能耗产品。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低能耗的汽车对环境更好。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "设备或建筑使用时消耗能源少、节能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低能耗", "is_correct": true, "explanation": "低能耗：修饰“水利技术”，指耗能少，与前文“减少蒸发损耗”的节能语境一致。"}, {"text": "高能耗", "is_correct": false, "explanation": "语义：“高能耗”指耗能多，与“典范”的褒义评价以及前文的节能语境相反。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”与“典范”矛盾，前文称该技术值得学习。"}, {"text": "低效", "is_correct": false, "explanation": "搭配：“低效”多说效率低，与“典范”的褒义不搭。"}], "explanations": {"低能耗": "低能耗：修饰“水利技术”，指耗能少，与前文“减少蒸发损耗”的节能语境一致。", "高能耗": "语义：“高能耗”指耗能多，与“典范”的褒义评价以及前文的节能语境相反。", "落后": "语义：“落后”与“典范”矛盾，前文称该技术值得学习。", "低效": "搭配：“低效”多说效率低，与“典范”的褒义不搭。"}, "sentence_index": 0, "correct_answer": "低能耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要想办法低能耗，少开空调。", "explanation": "这里应该用〈节能〉。低能耗是形容词，说设备或建筑耗能少，不能作“想办法”的对象来表示节约能源这一动作。"}, {"text": "他的工资很低能耗，每个月只能存一点钱。", "explanation": "这里应该用〈少〉。低能耗只说设备、建筑等的耗能少，不能用来形容收入；收入少要说“工资很少”。"}, {"text": "这台机器的工作效率很低能耗，做事很快。", "explanation": "这里应该用〈高效〉。低能耗说耗能少，不能用来说工作效率高；效率高要说“工作效率很高”或“高效”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低能耗", "is_correct": true, "explanation": "低能耗：与“安静”并列，都说空调的优点，语义一致。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”与“安静”相反，不能和“不仅……而且……”并列的优点搭配。"}, {"text": "笨重", "is_correct": false, "explanation": "体貌：“笨重”说外形或体积大，前文谈的是安静与耗能，不宜并列。"}, {"text": "脆弱", "is_correct": false, "explanation": "搭配：“脆弱”多用于人或易损的材料，不能与“安静”并列描述空调。"}], "explanations": {"低能耗": "低能耗：与“安静”并列，都说空调的优点，语义一致。", "吵闹": "语义：“吵闹”与“安静”相反，不能和“不仅……而且……”并列的优点搭配。", "笨重": "体貌：“笨重”说外形或体积大，前文谈的是安静与耗能，不宜并列。", "脆弱": "搭配：“脆弱”多用于人或易损的材料，不能与“安静”并列描述空调。"}, "sentence_index": 6, "correct_answer": "低能耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜是低能耗的，很适合减肥。", "explanation": "这里应该用〈低热量〉。低能耗指设备或建筑耗能少，不能用来说食物的热量。"}, {"text": "这种包装袋很低能耗，可以降解。", "explanation": "这里应该用〈环保〉。低能耗只说耗能少，不说对环境的影响或能否降解。"}, {"text": "这次考试他复习得很低能耗。", "explanation": "这里应该用〈认真〉。低能耗指设备或建筑耗能少，不能用来形容人复习的投入程度；用心复习要说“复习得很认真”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家买了一台很低能耗冰箱。", "corrected_sentence": "我家买了一台很低能耗的冰箱。", "error_description": "“很低能耗”修饰名词“冰箱”时须加“的”，应说“很低能耗的冰箱”；漏掉“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂鼓励大家用一台低能耗产品。", "corrected_sentence": "这家工厂鼓励大家用一种低能耗产品。", "error_description": "“产品”的量词应用“种”，“台”多用于机器、设备，不能说“一台低能耗产品”，应说“一种低能耗产品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
