INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12819, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对水资源进行控制、调配和利用，以服务于农业、工业、生活等方面的工程和措施。", "primary_collocate": null, "pronunciation": "shuǐ lì", "ipa": "ʂweɪ̯˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "水利", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些水利系统背后所蕴藏的，是一整套关于水权、劳动组织与社会协作的文化制度。", "target_word": "水利", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "值得注意的是，这些传统水利实践已被联合国教科文组织列为重要的非物质文化遗产。", "target_word": "水利", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古代中国十分重视水利建设。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项水利工程让几十万农民受益。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兴修水利是发展农业的重要基础。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都江堰是中国古代著名的水利工程。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府今年投入大量资金改善农村水利。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位专家长期研究水利与生态的关系。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水利设施老化，影响了农田灌溉。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水利工程", "label": "复合"}, {"form": "水利设施", "label": "复合"}], "register": "书面", "sense_fingerprint": "控制调配利用水资源的工程和措施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12819, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：对水资源进行控制、调配和利用的工程和措施，是正确答案。"}, {"text": "水里", "is_correct": false, "explanation": "shuǐ lǐ（第三声）与 shuǐ lì（第四声）声调不同，意思是“在水中”。"}, {"text": "税利", "is_correct": false, "explanation": "shuì lì（第四声）与 shuǐ lì 的第一个音节声调不同，意思是“税收与利润”。"}, {"text": "水梨", "is_correct": false, "explanation": "shuǐ lí（第二声）与 shuǐ lì 声调不同，意思是一种梨。"}], "explanations": {"水利": "水利：对水资源进行控制、调配和利用的工程和措施，是正确答案。", "水里": "shuǐ lǐ（第三声）与 shuǐ lì（第四声）声调不同，意思是“在水中”。", "税利": "shuì lì（第四声）与 shuǐ lì 的第一个音节声调不同，意思是“税收与利润”。", "水梨": "shuǐ lí（第二声）与 shuǐ lì 声调不同，意思是一种梨。"}, "sentence_index": null, "correct_answer": "水利"}, "level_3": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：修饰“技术”，指水资源的工程与技术，与前文的输水结构语境一致。"}, {"text": "医疗", "is_correct": false, "explanation": "语义：“医疗技术”与前文的输水结构、水文专家语境不符。"}, {"text": "美容", "is_correct": false, "explanation": "搭配：“美容技术”多指人体护理，不能与“典范”及水利工程并列。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪技术”与“输水”“蒸发损耗”的水利语境无关。"}], "explanations": {"水利": "水利：修饰“技术”，指水资源的工程与技术，与前文的输水结构语境一致。", "医疗": "语义：“医疗技术”与前文的输水结构、水文专家语境不符。", "美容": "搭配：“美容技术”多指人体护理，不能与“典范”及水利工程并列。", "烹饪": "语义：“烹饪技术”与“输水”“蒸发损耗”的水利语境无关。"}, "sentence_index": 0, "correct_answer": "水利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的水利很高，考试总是考第一。", "explanation": "这里应该用〈水平〉。水利指水资源的工程和措施，不能用来形容人的能力或成绩。"}, {"text": "这辆水利跑得很快，司机很满意。", "explanation": "这里应该用〈汽车〉。水利指水资源的工程和措施，不指可以行驶的车辆。"}, {"text": "他在游泳比赛中得了水利冠军。", "explanation": "这里应该用〈水上〉。水利指治理、调配水资源的工程和措施，不指水上运动，更不能作冠军的修饰语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：修饰“工程”，指古代的水利工程，与“都江堰”的语境一致。"}, {"text": "航空", "is_correct": false, "explanation": "语义：古代没有“航空工程”，与“古代著名”矛盾。"}, {"text": "电子", "is_correct": false, "explanation": "搭配：“电子工程”多指现代电子技术，与“古代”和“都江堰”不搭。"}, {"text": "太空", "is_correct": false, "explanation": "语义：古代没有“太空工程”，与“古代”矛盾。"}], "explanations": {"水利": "水利：修饰“工程”，指古代的水利工程，与“都江堰”的语境一致。", "航空": "语义：古代没有“航空工程”，与“古代著名”矛盾。", "电子": "搭配：“电子工程”多指现代电子技术，与“古代”和“都江堰”不搭。", "太空": "语义：古代没有“太空工程”，与“古代”矛盾。"}, "sentence_index": 6, "correct_answer": "水利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面的水利很足，吃了很饱。", "explanation": "这里应该用〈分量〉。水利指水资源的工程和措施，不能用来形容食物的多少；分量足要说“分量很足”。"}, {"text": "这幅画的水利很好，颜色很亮。", "explanation": "这里应该用〈构图〉。水利指治水用水的工程和措施，不能用来评价画面的布局。"}, {"text": "这家餐厅的水利很干净，食客很满意。", "explanation": "这里应该用〈卫生〉。水利指水资源的工程和措施，不能用来评价餐厅的卫生状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把水利工程让很多村子受益。", "corrected_sentence": "这座水利工程让很多村子受益。", "error_description": "“工程”的量词应用“座”（或“项”），“把”多用于有柄的器具，不能修饰“水利工程”；应说“这座水利工程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府去年投入大量资金改善了一把农村水利。", "corrected_sentence": "政府去年投入大量资金改善了农村水利。", "error_description": "“把”多用于有柄的器具，不能用来计量“水利”；“水利”作为泛称不加量词，应去掉“一把”，说“改善了农村水利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
