INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "典范指可以作为榜样的人或事物，具有示范作用。", "primary_collocate": null, "pronunciation": "diǎn fàn", "ipa": "tjɛn˨˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "典范", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座桥是现代建筑的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的敬业精神成了同事心中的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章是语言简洁的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生清廉，是官员学习的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的垃圾分类做法成为全国的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多人把这部电影看作爱情片的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的教学方法是我们学习的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城是保护古建筑的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家公司的合作是行业的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "典範", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可作榜样、起示范作用的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "典范", "is_correct": true, "explanation": "典范指值得效仿的标准，与“视为……的典范”搭配，表示被当作可以学习的榜样。"}, {"text": "障碍", "is_correct": false, "explanation": "语义：“视为低能耗水利技术的障碍”与句中对该技术的肯定评价相矛盾。"}, {"text": "废料", "is_correct": false, "explanation": "语义：废料指无用的废弃物，与“低能耗水利技术”的正面评价相反。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“视为”所接的对象应是可以肯定的事物，“噪音”是负面的干扰物，与句中的正面语境不搭。"}], "explanations": {"典范": "典范指值得效仿的标准，与“视为……的典范”搭配，表示被当作可以学习的榜样。", "障碍": "语义：“视为低能耗水利技术的障碍”与句中对该技术的肯定评价相矛盾。", "废料": "语义：废料指无用的废弃物，与“低能耗水利技术”的正面评价相反。", "噪音": "搭配：“视为”所接的对象应是可以肯定的事物，“噪音”是负面的干扰物，与句中的正面语境不搭。"}, "sentence_index": 0, "correct_answer": "典范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上有很多典范的北方人特征。", "explanation": "这里应该用〈典型〉。典范指值得效仿的榜样，形容有代表性的特征要用典型。"}, {"text": "这把尺子的刻度很典范，量得很准。", "explanation": "这里应该用〈标准〉。典范指值得效仿的榜样，形容刻度符合规范要用标准。"}, {"text": "这套家具的颜色很典范，一看就是红木。", "explanation": "这里应该用〈典型〉。典范指值得效仿的榜样，形容有代表性的外观特征要用典型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典范", "is_correct": true, "explanation": "典范指可作榜样的类型代表，与“看作……的典范”搭配。"}, {"text": "疟疾", "is_correct": false, "explanation": "语义：疟疾是一种疾病，不能被看作爱情片的类别。"}, {"text": "煤渣", "is_correct": false, "explanation": "搭配：“看作”后应接可以归类的事物，煤渣不能被归为爱情片。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：废墟指被毁坏的遗迹，与“爱情片”的评价不相容。"}], "explanations": {"典范": "典范指可作榜样的类型代表，与“看作……的典范”搭配。", "疟疾": "语义：疟疾是一种疾病，不能被看作爱情片的类别。", "煤渣": "搭配：“看作”后应接可以归类的事物，煤渣不能被归为爱情片。", "废墟": "语义：废墟指被毁坏的遗迹，与“爱情片”的评价不相容。"}, "sentence_index": 6, "correct_answer": "典范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次调查抽取了五百个典范。", "explanation": "这里应该用〈样本〉。典范指值得效仿的榜样，统计调查抽取的对象要用样本。"}, {"text": "这座桥的典范做得很精细。", "explanation": "这里应该用〈模型〉。典范指榜样，缩小仿制的实物要用模型。"}, {"text": "这只鸟的典范很完整。", "explanation": "这里应该用〈标本〉。典范指榜样，制成的动物实物要用标本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位医生是医疗行业的一本典范。", "corrected_sentence": "这位医生是医疗行业的一个典范。", "error_description": "错误：量词用了“本”。典范是抽象名词，量词应用“个”，“本”用于书籍。正确形式：“一个典范”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位科学家是研究领域地典范。", "corrected_sentence": "这位科学家是研究领域的典范。", "error_description": "错误：用了“地”。“典范”是名词，前面的定语“研究领域”要用定语标记“的”，不能用状语标记“地”。正确形式：“研究领域的典范”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
