INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12821, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物内部蓄积、隐藏着某种东西，尚未显露或开发。", "primary_collocate": null, "pronunciation": "yùn cáng", "ipa": "ɥn˥˩ tsʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这些水利系统背后所蕴藏的，是一整套关于水权、劳动组织与社会协作的文化制度。", "target_word": "蕴藏", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片海底蕴藏着丰富的石油。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下蕴藏着大量的煤炭资源。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山里蕴藏了很多稀有金属。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间故事中蕴藏着人们的智慧。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家蕴藏的水能资源十分可观。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个孩子身上都蕴藏着巨大的潜力。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西部沙漠下面蕴藏着不少天然气。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首古诗蕴藏的感情很深。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青藏高原蕴藏着丰富的矿产。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴藏着", "label": "体标"}, {"form": "蕴藏了", "label": "体标"}, {"form": "蘊藏", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物内部蓄积隐藏着尚未显露或开发的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蕴藏", "is_correct": true, "explanation": "蕴藏指事物内部蓄积着尚未显露的东西，与“所蕴藏的”搭配，表示背后隐含的内容。"}, {"text": "清扫", "is_correct": false, "explanation": "搭配：“清扫”的对象是垃圾、地面等有形之物，不能与“文化制度”搭配。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”用于墙面等表面，不能用于制度这类抽象内容。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买指花钱获得实物，与“背后蕴藏着制度”的含义不符。"}], "explanations": {"蕴藏": "蕴藏指事物内部蓄积着尚未显露的东西，与“所蕴藏的”搭配，表示背后隐含的内容。", "清扫": "搭配：“清扫”的对象是垃圾、地面等有形之物，不能与“文化制度”搭配。", "粉刷": "搭配：“粉刷”用于墙面等表面，不能用于制度这类抽象内容。", "购买": "语义：购买指花钱获得实物，与“背后蕴藏着制度”的含义不符。"}, "sentence_index": 0, "correct_answer": "蕴藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙蕴藏在花盆下面。", "explanation": "这里应该用〈隐藏〉。蕴藏指事物内部蓄积着尚未显露的东西，人为藏起来的物品要用隐藏。"}, {"text": "冬天，农民把土豆蕴藏在地窖里。", "explanation": "这里应该用〈储藏〉。蕴藏强调事物内部本身含有东西，储存食物等物资要用储藏。"}, {"text": "这份合同蕴藏三个部分。", "explanation": "这里应该用〈包含〉。蕴藏指内部藏着尚未显露的东西，合同的组成部分要用包含。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蕴藏", "is_correct": true, "explanation": "蕴藏指内部含有某种东西，与“身上都蕴藏着”搭配，表示孩子身上具有潜在的力量。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，与“巨大的潜力”不搭配。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：拆卸是把物体分开，与“身上潜力”的内在存在不符。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：砍伐指伐树，与人身上的潜力毫无关系。"}], "explanations": {"蕴藏": "蕴藏指内部含有某种东西，与“身上都蕴藏着”搭配，表示孩子身上具有潜在的力量。", "收割": "搭配：“收割”的对象是庄稼，与“巨大的潜力”不搭配。", "拆卸": "语义：拆卸是把物体分开，与“身上潜力”的内在存在不符。", "砍伐": "语义：砍伐指伐树，与人身上的潜力毫无关系。"}, "sentence_index": 6, "correct_answer": "蕴藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喜欢蕴藏老邮票。", "explanation": "这里应该用〈收藏〉。蕴藏指事物内部藏着未被发现的东西，主动搜集保存的物品要用收藏。"}, {"text": "他把一锅汤蕴藏进碗里。", "explanation": "这里应该用〈装〉。蕴藏不能表示把东西盛入容器，盛放食物要用装。"}, {"text": "他把书蕴藏在桌子上。", "explanation": "这里应该用〈放〉。蕴藏强调藏在事物内部，不能指放在表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片山谷下面蕴藏得很多金矿。", "corrected_sentence": "这片山谷下面蕴藏着很多金矿。", "error_description": "错误：“蕴藏得很多金矿”。“蕴藏”表示存在的状态，应以“着”表示状态持续，说“蕴藏着很多金矿”，不用“得”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片海底深处蕴藏着了丰富的天然气。", "corrected_sentence": "这片海底深处蕴藏着丰富的天然气。", "error_description": "错误：“蕴藏着了”。“着”表示状态持续，“了”表示完成，二者在“蕴藏”后语义冲突，只用“着”即可。正确形式：“蕴藏着丰富的天然气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "义务", "is_correct": true, "explanation": "《反义词词典》中“权利”与“义务”互为反义，对应本义项。"}, {"text": "河流", "is_correct": false, "explanation": "河流是地理事物，与“合法权利”没有反义关系。"}, {"text": "工具", "is_correct": false, "explanation": "工具是用来做事的物件，与“合法权利”没有反义关系。"}, {"text": "土壤", "is_correct": false, "explanation": "土壤是自然物质，与“合法权利”没有反义关系。"}], "correct_answer": "义务", "explanations": {"义务": "《反义词词典》中“权利”与“义务”互为反义，对应本义项。", "河流": "河流是地理事物，与“合法权利”没有反义关系。", "工具": "工具是用来做事的物件，与“合法权利”没有反义关系。", "土壤": "土壤是自然物质，与“合法权利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "义务", "is_correct": true, "explanation": "《反义词词典》中“权利”与“义务”互为反义，对应本义项。"}, {"text": "木材", "is_correct": false, "explanation": "木材是建筑或家具用料，与“合法权利”没有反义关系。"}, {"text": "电话", "is_correct": false, "explanation": "电话是通讯工具，与“合法权利”没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是地理事物，与“合法权利”没有反义关系。"}], "correct_answer": "义务", "explanations": {"义务": "《反义词词典》中“权利”与“义务”互为反义，对应本义项。", "木材": "木材是建筑或家具用料，与“合法权利”没有反义关系。", "电话": "电话是通讯工具，与“合法权利”没有反义关系。", "海洋": "海洋是地理事物，与“合法权利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某种资源使用和分配的合法权利", "primary_collocate": null, "pronunciation": "quán", "ipa": "tɕʰɥɛn˧˥", "syllable_count": 1, "sentences": [{"text": "这套制度规定，谁有权分配河水，须由全体村民集体协商决定，不能由某一家独断。", "target_word": "权", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "在某些地区，用水的权可以世代相传，并由专门的管理者监督执行。", "target_word": "权", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "村民有权使用村里的井水。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外人无权随便取用村里的水。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每家都有权按时用水。", "target_word": "权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁有权决定河水怎么分配？", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水渠是大家的，没有人有权独占。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂无权把河水都抽走。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民有权使用自己承包的土地。", "target_word": "权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有权用这口井，别人不能拦着她。", "target_word": "权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水权", "label": "复合"}, {"form": "使用权", "label": "复合"}, {"form": "權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "资源使用和分配的合法权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "权", "is_correct": true, "explanation": "正确答案：权（quán），指对资源使用和分配的合法权利。"}, {"text": "劝", "is_correct": false, "explanation": "劝（quàn）与权（quán）声调不同，第四声，意思是劝说。"}, {"text": "圈", "is_correct": false, "explanation": "圈（quān）与权（quán）声调不同，第一声，意思是圆圈。"}, {"text": "钱", "is_correct": false, "explanation": "钱（qián）与权（quán）韵母不同（介音 i 与 u），意思是钱财。"}], "explanations": {"权": "正确答案：权（quán），指对资源使用和分配的合法权利。", "劝": "劝（quàn）与权（quán）声调不同，第四声，意思是劝说。", "圈": "圈（quān）与权（quán）声调不同，第一声，意思是圆圈。", "钱": "钱（qián）与权（quán）韵母不同（介音 i 与 u），意思是钱财。"}, "sentence_index": null, "correct_answer": "权"}, "level_3": {"options": [{"text": "权", "is_correct": true, "explanation": "“有权分配河水”表示拥有分配河水的合法权利，与“须由全体村民集体协商决定”的语境相符。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是自然现象，不能作为“谁有……分配河水”中的资格，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书是物件，手里有书并不能获得分配河水的资格，句意不通。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“有饭”与“分配河水”不搭配，句意不通。"}], "explanations": {"权": "“有权分配河水”表示拥有分配河水的合法权利，与“须由全体村民集体协商决定”的语境相符。", "雨": "语义：雨是自然现象，不能作为“谁有……分配河水”中的资格，句意不通。", "书": "语义：书是物件，手里有书并不能获得分配河水的资格，句意不通。", "饭": "搭配：“有饭”与“分配河水”不搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他获得了一只用水权。", "explanation": "这里应该用〈项〉。“权”指权利，要用“项”，不能用“只”（“只”多用于动物或成对的东西）。"}, {"text": "这口井是村里唯一的权，全村人都靠它吃水。", "explanation": "这里应该用〈水源〉。“权”指合法的权利，不能指供水的来源；此处说的是井本身，要用“水源”。"}, {"text": "他很努力，有权考上好大学。", "explanation": "这里应该用〈能力〉。“权”指合法的权利，表示有本事做到某事要用〈能力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "权", "is_correct": true, "explanation": "正确答案：权（quán），指对资源使用和分配的合法权利。"}, {"text": "券", "is_correct": false, "explanation": "券（quàn）与权（quán）声调不同，第四声，意思是凭证，如优惠券。"}, {"text": "前", "is_correct": false, "explanation": "前（qián）与权（quán）韵母不同（介音 i 与 u），意思是前面。"}, {"text": "悬", "is_correct": false, "explanation": "悬（xuán）与权（quán）声母不同（x 与 q），意思是悬挂。"}], "explanations": {"权": "正确答案：权（quán），指对资源使用和分配的合法权利。", "券": "券（quàn）与权（quán）声调不同，第四声，意思是凭证，如优惠券。", "前": "前（qián）与权（quán）韵母不同（介音 i 与 u），意思是前面。", "悬": "悬（xuán）与权（quán）声母不同（x 与 q），意思是悬挂。"}, "sentence_index": null, "correct_answer": "权"}, "level_3": {"options": [{"text": "权", "is_correct": true, "explanation": "“有权独占”表示拥有权利去独占，与“大家的”“没有人”的语境相符。"}, {"text": "份", "is_correct": false, "explanation": "语义：“有份”表示拥有一份，与“独占”的排他意思相冲突。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是自然现象，不能被“独占”，句意不通。"}, {"text": "票", "is_correct": false, "explanation": "搭配：“票”是凭证，不能与“有……独占”构成合理的权利搭配。"}], "explanations": {"权": "“有权独占”表示拥有权利去独占，与“大家的”“没有人”的语境相符。", "份": "语义：“有份”表示拥有一份，与“独占”的排他意思相冲突。", "雨": "语义：雨是自然现象，不能被“独占”，句意不通。", "票": "搭配：“票”是凭证，不能与“有……独占”构成合理的权利搭配。"}, "sentence_index": 6, "correct_answer": "权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这孩子五岁就有权背下整首唐诗。", "explanation": "这里应该用〈会〉。“权”指合法权利，表示能做某事要用〈会〉。"}, {"text": "井里的权很多，够全村人喝。", "explanation": "这里应该用〈水〉。“权”指合法的权利，不能拿来喝；此处说的是井里的水，要用“水”。"}, {"text": "这家公司获得了一台用水权。", "explanation": "这里应该用〈项〉。“权”是抽象的权利，用“项”，不能用“台”（“台”多用于机器）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "居民权有参与村里的用水决定。", "corrected_sentence": "居民有权参与村里的用水决定。", "error_description": "“有权”是固定搭配，“权”应紧接在“有”之后。“权有”语序错误，应说“有权参与”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村委会无只权把井水卖给外人。", "corrected_sentence": "村委会无权把井水卖给外人。", "error_description": "“无权”是固定搭配，“权”指抽象的权利，中间不能插入量词“只”，应删去“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
