INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12823, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类创造物质或精神财富的活动。", "primary_collocate": null, "pronunciation": "láo dòng", "ipa": "lɑʊ˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这些水利系统背后所蕴藏的，是一整套关于水权、劳动组织与社会协作的文化制度。", "target_word": "劳动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "劳动创造了世界上的财富。", "target_word": "劳动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的劳动养活全家。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "劳动是人类生活的基础。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的劳动都应该得到尊重。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民的劳动让我们有饭吃。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的劳动得到了大家的认可。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是工人们辛勤劳动的结果。", "target_word": "劳动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有劳动，就没有收获。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个靠劳动换来的好结果。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "劳动力", "label": "复合"}, {"form": "劳动者", "label": "复合"}, {"form": "勞動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人类创造物质或精神财富的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳动", "is_correct": true, "explanation": "“劳动组织”指组织劳动的方式，与“水权”“社会协作”并列为制度内容，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能与“社会协作”一起构成文化制度。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是娱乐活动，不是组织制度所针对的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色组织”不成词，颜色与水权、社会协作的制度无关。"}], "explanations": {"劳动": "“劳动组织”指组织劳动的方式，与“水权”“社会协作”并列为制度内容，符合句意。", "天气": "语义：天气是自然现象，不能与“社会协作”一起构成文化制度。", "游戏": "语义：游戏是娱乐活动，不是组织制度所针对的对象。", "颜色": "语义：“颜色组织”不成词，颜色与水权、社会协作的制度无关。"}, "sentence_index": 0, "correct_answer": "劳动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的劳动在公司里很稳定。", "explanation": "这里应该用〈工作〉。“劳动”指创造财富的活动，指岗位或职务要用“工作”。"}, {"text": "这家工厂生产的劳动很受欢迎。", "explanation": "这里应该用〈产品〉。“劳动”指人创造财富的活动，不是生产出来的东西，不能说“很受欢迎”。"}, {"text": "他完成了一只劳动。", "explanation": "这里应该用〈项〉。“劳动”是抽象活动，用“项”，不能用“只”（“只”多用于动物等）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳动", "is_correct": true, "explanation": "“她的劳动”指她付出的劳动成果，与“得到大家的认可”相符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物件，不是可以被大家认可的成果。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然物，不是可以得到认可的成果。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”是具体物件，与“得到认可”这种抽象评价不搭配。"}], "explanations": {"劳动": "“她的劳动”指她付出的劳动成果，与“得到大家的认可”相符。", "闹钟": "语义：闹钟是物件，不是可以被大家认可的成果。", "雨水": "语义：雨水是自然物，不是可以得到认可的成果。", "冰箱": "搭配：“冰箱”是具体物件，与“得到认可”这种抽象评价不搭配。"}, "sentence_index": 6, "correct_answer": "劳动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用很大的劳动推开了门。", "explanation": "这里应该用〈力气〉。“劳动”指创造财富的活动，不能当体力用。"}, {"text": "他的成绩是靠一辆劳动换来的。", "explanation": "这里应该用〈项〉。“劳动”是抽象活动，量词用“项”，不能用“辆”（“辆”用于车）。"}, {"text": "这套劳动很大，他住得很舒服。", "explanation": "这里应该用〈房子〉。“劳动”指人创造财富的活动，不是房屋，不能用“套”来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人的劳动了创造了社会财富。", "corrected_sentence": "工人的劳动创造了社会财富。", "error_description": "“劳动”作名词时不能带“了”，“的劳动”后应直接接动词。应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民的一台劳动让全村人吃饱了饭。", "corrected_sentence": "农民的劳动让全村人吃饱了饭。", "error_description": "“劳动”是抽象活动，前面不能加量词“一台”（“台”用于机器）。应删去“一台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
