INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们集中居住的村庄，一般规模较小。", "primary_collocate": null, "pronunciation": "cūn luò", "ipa": "tsʰwən˥ lwo˥˩", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "村落", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水的分配通常由村落集体协商决定，依循季节、作物类型与土地面积进行动态调整，体现了高度制度化的资源管理逻辑。", "target_word": "村落", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "山脚下有一个安静的小村落。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村落只有三十多户人家。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着小路走进了村落。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村落四周都是绿色的田地。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个古老的村落已经有五百年历史了。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，村落里的孩子常在河边玩水。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上看，村落像一幅画。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个偏远的村落去年修了一条新路。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "人们集中居住的小规模村庄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司", "is_correct": false, "explanation": "语义：“公司”是经营单位，不是人们集中居住的地方，与“边缘”和“村民自发组织的运动”的语境不符。"}, {"text": "村落", "is_correct": true, "explanation": "“村落”指人们集中居住的小规模村庄，与“边缘”和“村民”的语境相合。"}, {"text": "超市", "is_correct": false, "explanation": "语义：“超市”是买东西的商店，不是村民集中居住的地方，不能说“边缘超市”里有村民运动。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“村民自发组织的运动”发生在居民聚居地，“工厂”不是居住的地方，二者搭配不通。"}], "explanations": {"公司": "语义：“公司”是经营单位，不是人们集中居住的地方，与“边缘”和“村民自发组织的运动”的语境不符。", "村落": "“村落”指人们集中居住的小规模村庄，与“边缘”和“村民”的语境相合。", "超市": "语义：“超市”是买东西的商店，不是村民集中居住的地方，不能说“边缘超市”里有村民运动。", "工厂": "搭配：“村民自发组织的运动”发生在居民聚居地，“工厂”不是居住的地方，二者搭配不通。"}, "sentence_index": 0, "correct_answer": "村落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村落在村口吃了一碗面。", "explanation": "这里应该用〈村民〉。吃东西的是人，村落指聚居的地方，不能吃东西。"}, {"text": "这个村落明年将在股票市场上市。", "explanation": "这里应该用〈公司〉。上市的是公司，村落是聚居的地方，不能上市。"}, {"text": "这个村落每年招收新生。", "explanation": "这里应该用〈学校〉。招收新生的是学校，村落是聚居的地方，不能招生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑技术的历史远不到五百年，与“五百年历史”的说法冲突。"}, {"text": "村落", "is_correct": true, "explanation": "“村落”可以古老，也可以有五百年的历史，与句意相符。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“古老”修饰地方或事物，不修饰人，“古老的学生”搭配不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机的使用历史不足五百年，不可能有五百年历史。"}], "explanations": {"电脑": "语义：电脑技术的历史远不到五百年，与“五百年历史”的说法冲突。", "村落": "“村落”可以古老，也可以有五百年的历史，与句意相符。", "学生": "搭配：“古老”修饰地方或事物，不修饰人，“古老的学生”搭配不通。", "手机": "语义：手机的使用历史不足五百年，不可能有五百年历史。"}, "sentence_index": 6, "correct_answer": "村落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只村落去年修了一条新路。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对的东西，村落应用量词“个”。"}, {"text": "这张村落很安静，我很喜欢。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，村落应用量词“个”。"}, {"text": "这把村落的路很窄。", "explanation": "这里应该用〈个〉。“把”用于有柄或可以握住的东西，村落应用量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山谷里有一条古老的村落。", "corrected_sentence": "山谷里有一个古老的村落。", "error_description": "量词错误：“村落”应该用量词“个”，“条”用于细长的东西，如道路、河流，不能用于村落。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们一直住村落里。", "corrected_sentence": "村民们一直住在村落里。", "error_description": "介词缺失：表示居住地点的“村落”前要加介词“在”，应说“住在村落里”，漏掉“在”就不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
