INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12825, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照某种标准或规则进行，表示遵循、依照。", "primary_collocate": null, "pronunciation": "yī xún", "ipa": "i˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "水的分配通常由村落集体协商决定，依循季节、作物类型与土地面积进行动态调整，体现了高度制度化的资源管理逻辑。", "target_word": "依循", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们依循老师的办法做练习。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他依循既定的程序办理了手续。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事要依循规矩。", "target_word": "依循", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家依循顺序排队进去。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司依循法律办事。", "target_word": "依循", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她依循地图找到了那家店。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生依循医院的规定给病人开药。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子应该依循家里的规矩。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛依循去年的办法进行。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依循了", "label": "体标"}, {"form": "依循着", "label": "体标"}, {"form": "依循过", "label": "体标"}], "register": "书面", "sense_fingerprint": "按照某种标准或规则进行，遵循、依照", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依循", "is_correct": true, "explanation": "依循：遵照季节、作物类型等条件进行调整，与“制度化”的语境相合。"}, {"text": "无视", "is_correct": false, "explanation": "语义：“无视”表示不理会，与“动态调整”所依据的条件相抵触，句意不通。"}, {"text": "收集", "is_correct": false, "explanation": "搭配：“收集”不能与“季节、作物类型”等条件搭配，句意不通。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”表示违反，与“体现了高度制度化的资源管理逻辑”相矛盾。"}], "explanations": {"依循": "依循：遵照季节、作物类型等条件进行调整，与“制度化”的语境相合。", "无视": "语义：“无视”表示不理会，与“动态调整”所依据的条件相抵触，句意不通。", "收集": "搭配：“收集”不能与“季节、作物类型”等条件搭配，句意不通。", "违背": "语义：“违背”表示违反，与“体现了高度制度化的资源管理逻辑”相矛盾。"}, "sentence_index": 0, "correct_answer": "依循"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依循朋友的帮助完成了这份工作。", "explanation": "这里应该用〈依靠〉。依循指按照规则或办法行事，凭借他人的帮助要用依靠。"}, {"text": "藤蔓依循大树生长。", "explanation": "这里应该用〈依附〉。依循指遵照规则行事，表示攀附在他物上要用依附。"}, {"text": "她始终依循故乡，舍不得离开。", "explanation": "这里应该用〈依恋〉。依循指遵照规则，表示对人或地方的眷恋要用依恋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依循", "is_correct": true, "explanation": "依循：按照地图的指引行事，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能以“地图”为宾语，句意荒谬。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：“朗读”的宾语应是文字或作品，不能说“朗读地图”。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语应是交通工具，不能说“驾驶地图”。"}], "explanations": {"依循": "依循：按照地图的指引行事，句意通顺。", "吃": "语义：“吃”不能以“地图”为宾语，句意荒谬。", "朗读": "搭配：“朗读”的宾语应是文字或作品，不能说“朗读地图”。", "驾驶": "配价：“驾驶”的宾语应是交通工具，不能说“驾驶地图”。"}, "sentence_index": 6, "correct_answer": "依循"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司依循雄厚的资金发展。", "explanation": "这里应该用〈依托〉。依循指遵照规则行事，凭借资金等条件发展要用依托。"}, {"text": "他依循父亲的权势行事。", "explanation": "这里应该用〈依仗〉。依循指遵照规则，依仗指倚仗某种权势，两者不能互换。"}, {"text": "他依循努力获得了成功。", "explanation": "这里应该用〈凭借〉。依循指遵照规则，凭借指依靠某种条件，此处应说凭借努力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他依循在规定办事。", "corrected_sentence": "他依循规定办事。", "error_description": "错误形式：“依循”后面直接接宾语时加了“在”。正确形式：“他依循规定办事”。原因：“依循”是及物动词，宾语前不加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直把依循规矩做事。", "corrected_sentence": "他一直依循规矩做事。", "error_description": "错误形式：在“依循”前多加了“把”。正确形式：“他一直依循规矩做事”。原因：“把”字句要求“把+宾语+动词”，此处“依循规矩”不能作“把”的宾语，应删去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
