INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指具有共同特征的事物所形成的种类。", "primary_collocate": null, "pronunciation": "lèi xíng", "ipa": "lei˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "水的分配通常由村落集体协商决定，依循季节、作物类型与土地面积进行动态调整，体现了高度制度化的资源管理逻辑。", "target_word": "类型", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两本书是不同类型的故事。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢哪种类型的电影？", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多类型的餐馆。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格属于安静的类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把水果按类型分开。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种类型的手机很受年轻人欢迎。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请选择你想看的书的类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐有很多不同的类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门做新类型的游戏。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "类型学", "label": "复合"}, {"form": "类型化", "label": "复合"}], "register": "中性", "sense_fingerprint": "具有共同特征的事物所归成的种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类型", "is_correct": true, "explanation": "类型：指作物的种类，与“作物类型与土地面积”相合，句意通顺。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：作物一般不与“时间”组合，说“作物时间”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能作为调整资源的依据，与句意不符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”与资源分配无关，句意不通。"}], "explanations": {"类型": "类型：指作物的种类，与“作物类型与土地面积”相合，句意通顺。", "时间": "搭配：作物一般不与“时间”组合，说“作物时间”不通。", "颜色": "语义：“颜色”不能作为调整资源的依据，与句意不符。", "名字": "语义：“名字”与资源分配无关，句意不通。"}, "sentence_index": 0, "correct_answer": "类型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的类型是一米二。", "explanation": "这里应该用〈身高〉。类型指种类，表示人的身高要用身高，不能说“类型是一米二”。"}, {"text": "这件衣服的类型很鲜艳。", "explanation": "这里应该用〈颜色〉。类型不能修饰“鲜艳”，说颜色鲜艳要用颜色。"}, {"text": "这件商品的类型是一百块。", "explanation": "这里应该用〈价格〉。类型指种类，不能表示金额，说价格多少要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类型", "is_correct": true, "explanation": "类型：指手机的种类，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”一般用于人，不能修饰手机。"}, {"text": "气味", "is_correct": false, "explanation": "语义：手机不讲“气味”，说“这种气味的手机”句意荒谬。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”用于人或生物，不修饰手机。"}], "explanations": {"类型": "类型：指手机的种类，句意通顺。", "身高": "搭配：“身高”一般用于人，不能修饰手机。", "气味": "语义：手机不讲“气味”，说“这种气味的手机”句意荒谬。", "年龄": "搭配：“年龄”用于人或生物，不修饰手机。"}, "sentence_index": 6, "correct_answer": "类型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的类型是三十岁。", "explanation": "这里应该用〈年龄〉。类型指种类，表示人的岁数要用年龄。"}, {"text": "从这里到车站的类型是两公里。", "explanation": "这里应该用〈距离〉。类型指种类，表示路程远近要用距离。"}, {"text": "今天的类型是三十度。", "explanation": "这里应该用〈温度〉。类型指种类，表示冷热要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店有三只类型的小说。", "corrected_sentence": "这家书店有三种类型的小说。", "error_description": "错误形式：“类型”前用了量词“只”。正确形式：“三种类型”。原因：“只”用于动物等，修饰“类型”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先类型分开水果。", "corrected_sentence": "我们先按类型分开水果。", "error_description": "错误形式：漏掉了介词“按”。正确形式：“按类型分开”。原因：“按类型”是介词结构，不能省略“按”，否则句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
