INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12828, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指依法或依约对某物进行使用的权利。", "primary_collocate": null, "pronunciation": "shǐ yòng quán", "ipa": "ʂɻ̩˨˩˦ yŋ˥˩ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "在某些地区，水的使用权甚至以世袭方式传承，并由专门的管理者（称为“水官”）监督执行，确保公平与秩序。", "target_word": "使用权", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块地的使用权属于村里。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了房子，但没有土地的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同上写着公司有十年的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房的人只有房子的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的使用权已经给了那家公司。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有这间会议室的使用权吗？", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把球场的使用权借给了社区。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签了合同，我们就有了机器的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有使用权的人不能进这个院子。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "土地使用权", "label": "复合"}], "register": "书面", "sense_fingerprint": "依法律或合同对某物享有的使用权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用权", "is_correct": true, "explanation": "正确：使用权可以世袭传承，并由管理者监督执行，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观，不能“以世袭方式传承”，也不需要“监督执行”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是一个数额，不能被世袭传承，也不由管理者监督执行。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不与“以世袭方式传承”“监督执行”搭配，句子说不通。"}], "explanations": {"使用权": "正确：使用权可以世袭传承，并由管理者监督执行，符合句意。", "颜色": "语义：颜色是事物的外观，不能“以世袭方式传承”，也不需要“监督执行”。", "价格": "语义：价格是一个数额，不能被世袭传承，也不由管理者监督执行。", "温度": "搭配：“温度”不与“以世袭方式传承”“监督执行”搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "使用权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套设备的使用权太高了，我们每个月都付不起。", "explanation": "这里应该用〈使用费〉。使用费是为使用某物付的钱，可以说“太高”；使用权是权利，不能说“太高”。"}, {"text": "买机器时，商家附上了一份使用权，教我们怎么操作。", "explanation": "这里应该用〈使用说明〉。使用说明是教人怎么使用的文字；使用权是依法或依约使用某物的权利，不能教人操作。"}, {"text": "这间屋子的使用权很暖和。", "explanation": "这里误把使用权当成了〈房屋实体〉。使用权是依法或依约使用某物的抽象权利，没有温度，不能说“暖和”；“暖和”形容的是屋子本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用权", "is_correct": true, "explanation": "正确：“你有……的使用权”表示拥有使用这间会议室的权利，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：会议室的味道是气味，不是可以“拥有”的权利。"}, {"text": "面积", "is_correct": false, "explanation": "配价：“有”后面要接可以被拥有的权利或物品，“面积”是房间的属性，不能这样搭配。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：会议室没有嗓音，这个词不能用于房间。"}], "explanations": {"使用权": "正确：“你有……的使用权”表示拥有使用这间会议室的权利，符合句意。", "味道": "语义：会议室的味道是气味，不是可以“拥有”的权利。", "面积": "配价：“有”后面要接可以被拥有的权利或物品，“面积”是房间的属性，不能这样搭配。", "嗓音": "语义：会议室没有嗓音，这个词不能用于房间。"}, "sentence_index": 6, "correct_answer": "使用权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位局长拥有很大的使用权，可以随意调动下属。", "explanation": "这里应该用〈权力〉。使用权只是依法或依约使用某物的权利，调动下属属于权力。"}, {"text": "这台机器的使用权很高，他每天都在用它。", "explanation": "这里应该用〈使用率〉。使用率指被使用的频繁程度，可以说“很高”；使用权是权利，不能说“很高”。"}, {"text": "这条路的使用权在河边。", "explanation": "使用权是抽象的权利，不是地点，不能说“在河边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司买到了这栋楼的一把使用权。", "corrected_sentence": "公司买到了这栋楼的一项使用权。", "error_description": "量词错误：“使用权”的量词应为“项”，“把”用于有柄的器物，不能修饰这类权利。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有这间仓库的一台使用权。", "corrected_sentence": "他有这间仓库的一项使用权。", "error_description": "量词错误：“使用权”应用量词“项”，“台”用于机器，不能修饰这类权利。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
