INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12829, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12829, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指职位、爵位或财产等世代继承。", "primary_collocate": null, "pronunciation": "shì xí", "ipa": "ʂʅ˥˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "在某些地区，水的使用权甚至以世袭方式传承，并由专门的管理者（称为“水官”）监督执行，确保公平与秩序。", "target_word": "世袭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古代的王位常常是世袭的。", "target_word": "世袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在古代，皇位是世袭的，一般传给嫡长子。", "target_word": "世袭", "complexity_tier": "T3", "furigana": "shì xí", "sentence_source": "generated"}, {"text": "这个爵位可以世袭，儿子能接着当。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的土地是世袭的，不能卖给别人。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的国家不再让官职世袭了。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个家族的爵位是世袭的，传了好几代。", "target_word": "世袭", "complexity_tier": "T3", "furigana": "shì xí", "sentence_source": "generated"}, {"text": "古时候，村长的位子也是世袭的。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王死后，王位世袭下来，传给了大儿子。", "target_word": "世袭", "complexity_tier": "T3", "furigana": "shì xí", "sentence_source": "generated"}, {"text": "这种世袭的制度让穷人没有机会当官。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "世袭制", "label": "复合词"}], "register": "书面", "sense_fingerprint": "世袭：职位、爵位、财产等由后代世代继承", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世袭", "is_correct": true, "explanation": "正确答案，读作 shì xí，指职位、爵位或财产世代继承。"}, {"text": "实习", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是实习。"}, {"text": "市集", "is_correct": false, "explanation": "jí 与 xí 声母不同（j 与 x），意思是集市。"}, {"text": "世系", "is_correct": false, "explanation": "xì（第四声）与 xí（第二声）声调不同，意思是家族世代相传的系统。"}, {"text": "市旗", "is_correct": false, "explanation": "qí 与 xí 声母不同（q 与 x），意思是城市的旗帜。"}], "explanations": {"世袭": "正确答案，读作 shì xí，指职位、爵位或财产世代继承。", "实习": "shí（第二声）与 shì（第四声）声调不同，意思是实习。", "市集": "jí 与 xí 声母不同（j 与 x），意思是集市。", "世系": "xì（第四声）与 xí（第二声）声调不同，意思是家族世代相传的系统。", "市旗": "qí 与 xí 声母不同（q 与 x），意思是城市的旗帜。"}, "sentence_index": null, "correct_answer": "世袭"}, "level_3": {"options": [{"text": "世袭", "is_correct": true, "explanation": "正确答案。“以世袭方式传承”指按血缘代代承继，与句中的“传承”一致。"}, {"text": "抽签", "is_correct": false, "explanation": "语义：“抽签”靠随机抽取决定，与“传承”的代代相传不合。"}, {"text": "借用", "is_correct": false, "explanation": "语义：“借用”是暂时使用、之后要归还，与“传承”的永久交接相反。"}, {"text": "白送", "is_correct": false, "explanation": "语域：“白送”是口语，与这句书面语的“传承”语域不合，意思也对不上。"}], "explanations": {"世袭": "正确答案。“以世袭方式传承”指按血缘代代承继，与句中的“传承”一致。", "抽签": "语义：“抽签”靠随机抽取决定，与“传承”的代代相传不合。", "借用": "语义：“借用”是暂时使用、之后要归还，与“传承”的永久交接相反。", "白送": "语域：“白送”是口语，与这句书面语的“传承”语域不合，意思也对不上。"}, "sentence_index": 0, "correct_answer": "世袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他世袭了父亲的公司。", "explanation": "这里应该用〈继承〉。世袭多用于爵位、官职、财产的代代相传；个人接手公司或家业一般说继承。"}, {"text": "学校世袭了一位新老师。", "explanation": "这里应该用〈聘请〉。聘用教师要说聘请，世袭只用于职位、爵位、财产的代代承继，不能用于聘用人员。"}, {"text": "他世袭了律师资格。", "explanation": "这里应该用〈考取〉。律师资格要靠考试取得，世袭只用于职位、爵位、财产的代代承继。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世袭", "is_correct": true, "explanation": "正确答案。“那个家族的爵位是世袭的”指爵位代代相传，与“传了好几代”一致。"}, {"text": "选举", "is_correct": false, "explanation": "语义：“选举”指投票产生，与“传了好几代”的代代相传矛盾。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”指把东西送给别人，与爵位代代留在家族内的语境不合。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象多为商品，爵位不说购买。"}], "explanations": {"世袭": "正确答案。“那个家族的爵位是世袭的”指爵位代代相传，与“传了好几代”一致。", "选举": "语义：“选举”指投票产生，与“传了好几代”的代代相传矛盾。", "赠送": "语义：“赠送”指把东西送给别人，与爵位代代留在家族内的语境不合。", "购买": "搭配：“购买”的对象多为商品，爵位不说购买。"}, "sentence_index": 6, "correct_answer": "世袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他世袭成了班长。", "explanation": "这里应该用〈竞选〉。班长靠竞选或选举产生，世袭只用于由血缘代代相传的职位。"}, {"text": "他世袭了厂长。", "explanation": "这里应该用〈继任〉。厂长靠任命或选拔，不是家族传下来的职位，世袭不能用于此。"}, {"text": "爱迪生世袭了电灯。", "explanation": "这里应该用〈发明〉。世袭只用于职位、爵位、财产的代代承继，不能用于创造新东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套老宅是世袭，不能随便卖掉。", "corrected_sentence": "这套老宅是世袭的，不能随便卖掉。", "error_description": "“是……的”句式末尾要带“的”。“世袭”作谓语时应为“是世袭的”，漏掉“的”是错误形式，正确形式为“是世袭的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个家族的爵位世袭得五代。", "corrected_sentence": "这个家族的爵位世袭了五代。", "error_description": "“得”不能直接接表示代数的数量词，“世袭得五代”不成立；表示已经发生的承继应用“了”，正确形式为“世袭了五代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
