INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12831, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指某事物被赋予某个名称或描述。", "primary_collocate": null, "pronunciation": "chēng wéi", "ipa": "ʈʂʰɤŋ˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "人们把这种小鸟称为“山雀”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国人把大熊猫称为“国宝”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把一年的第一天称为“元旦”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河很长，人们把它称为“母亲河”。", "target_word": "称为", "complexity_tier": "T3", "furigana": "chēng wéi", "sentence_source": "generated"}, {"text": "朋友们把他称为“小博士”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在我们那里，人们把外婆称为“阿婆”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山常年有云，当地人把它称为“云山”。", "target_word": "称为", "complexity_tier": "T3", "furigana": "chēng wéi", "sentence_source": "generated"}, {"text": "医生把这种小病称为“感冒”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们把冬至后的八十一天称为“数九”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把我们的班称为“快乐一家”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "被称为", "label": "被动结构"}], "register": "中性", "sense_fingerprint": "称为：给事物或人起名、命名，常用“把……称为……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12831, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "称为", "is_correct": true, "explanation": "正确答案，读作 chēng wéi，指给事物起名或说成是某个名称。"}, {"text": "成为", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是变成。"}, {"text": "升为", "is_correct": false, "explanation": "shēng 与 chēng 声母不同（sh 与 ch），意思是提升为某个职位。"}, {"text": "称谓", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是称呼。"}], "explanations": {"称为": "正确答案，读作 chēng wéi，指给事物起名或说成是某个名称。", "成为": "chéng（第二声）与 chēng（第一声）声调不同，意思是变成。", "升为": "shēng 与 chēng 声母不同（sh 与 ch），意思是提升为某个职位。", "称谓": "wèi（第四声）与 wéi（第二声）声调不同，意思是称呼。"}, "sentence_index": null, "correct_answer": "称为"}, "level_3": {"options": [{"text": "称为", "is_correct": true, "explanation": "正确答案。“人们把这种小鸟称为“山雀””指给小鸟起这个名字。"}, {"text": "变为", "is_correct": false, "explanation": "语义：“变为”指事物本身转化成另一种状态，小鸟不会变成名称。"}, {"text": "晋升为", "is_correct": false, "explanation": "语义：“晋升为”用于人的职位或等级提高，不能用来给小鸟起名。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接受的人作对象，“山雀”是名称，不能作为送的对象。"}], "explanations": {"称为": "正确答案。“人们把这种小鸟称为“山雀””指给小鸟起这个名字。", "变为": "语义：“变为”指事物本身转化成另一种状态，小鸟不会变成名称。", "晋升为": "语义：“晋升为”用于人的职位或等级提高，不能用来给小鸟起名。", "送给": "配价：“送给”需要接受的人作对象，“山雀”是名称，不能作为送的对象。"}, "sentence_index": 0, "correct_answer": "称为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋大米称为十斤。", "explanation": "这里应该用〈称重〉。用秤量轻重要说称重，称为只表示给人或事物起名，不能表示称量。"}, {"text": "他的个子被称为一米八。", "explanation": "这里应该用〈有〉。身高要说有或达到，称为只表示起名，不能表示身高。"}, {"text": "这个箱子被称为二十升。", "explanation": "这里应该用〈容纳〉。容量要说容纳或盛，称为只表示给事物起名，不能表示容积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称为", "is_correct": true, "explanation": "正确答案。“当地人把它称为“云山””指给这座山起名，与“常年有云”的描述相合。"}, {"text": "砍成", "is_correct": false, "explanation": "语义：“砍成”指用刀斧把东西切成某种形状，不能用来给山起名。"}, {"text": "刷成", "is_correct": false, "explanation": "语义：“刷成”指涂成某种颜色或样子，山不能刷成一个名称。"}, {"text": "卖给", "is_correct": false, "explanation": "配价：“卖给”需要买方是人，“云山”是名称，不能作为卖的对象。"}], "explanations": {"称为": "正确答案。“当地人把它称为“云山””指给这座山起名，与“常年有云”的描述相合。", "砍成": "语义：“砍成”指用刀斧把东西切成某种形状，不能用来给山起名。", "刷成": "语义：“刷成”指涂成某种颜色或样子，山不能刷成一个名称。", "卖给": "配价：“卖给”需要买方是人，“云山”是名称，不能作为卖的对象。"}, "sentence_index": 6, "correct_answer": "称为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工资被称为一百元。", "explanation": "这里应该用〈定为〉。金额、数额要说定为，称为只表示给事物起名。"}, {"text": "他的年龄被称为二十岁。", "explanation": "这里应该用〈满〉。年龄达到某个数要说满，称为不能用来表示数量。"}, {"text": "我们的教室被称为三百平米。", "explanation": "这里应该用〈有〉。面积要说有，称为表示叫做某个名称，不能表示数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鸟把称为“报春鸟”。", "corrected_sentence": "这种鸟被称为“报春鸟”。", "error_description": "此处应用被动标记“被”，构成固定格式“被称为”。这里误用“把”，“把称为”缺少宾语，属于把字句的错误。正确形式为“被称为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛被称为的“海上明珠”。", "corrected_sentence": "这座岛被称为“海上明珠”。", "error_description": "“被称为”后面不能直接加“的”。“的”用于修饰语和中心语之间，这里“海上明珠”是称呼本身，正确形式为“被称为“海上明珠””，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
