INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水官是中国古代负责水利、治水、管理河道等事务的官职。", "primary_collocate": null, "pronunciation": "shuǐ guān", "ipa": "ʂweɪ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "在某些地区，水的使用权甚至以世袭方式传承，并由专门的管理者（称为“水官”）监督执行，确保公平与秩序。", "target_word": "水官", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古代的水官负责管理河道。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水官每年春天都要去检查河道。", "target_word": "水官", "complexity_tier": "T3", "furigana": "shuǐ guān měi nián chūn tiān dōu yào qù jiǎn chá hé dào", "sentence_source": "generated"}, {"text": "河水涨了，水官带着人去修堤。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位水官一辈子都在治水。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皇帝派了一位水官去管黄河。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水官告诉大家，今年雨水会很多。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的人都很尊敬那位水官。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水官每天要检查河里的水位。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做水官的人，要懂得水的脾气。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "水官：中国古代负责水利、治水、管理河道的官职", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12832, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水官", "is_correct": true, "explanation": "正确答案。shuǐ guān 指古代负责治水、管理河道的官职。"}, {"text": "水管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）只在第二个音节声调不同，意思是输水的管道。"}, {"text": "税官", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是收税的官员，不是管水的官。"}, {"text": "水光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（ang 与 an），意思是水面反射的光。"}, {"text": "税关", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ 声调不同，意思是海关，即收税的关卡。"}], "explanations": {"水官": "正确答案。shuǐ guān 指古代负责治水、管理河道的官职。", "水管": "guǎn（第三声）与 guān（第一声）只在第二个音节声调不同，意思是输水的管道。", "税官": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是收税的官员，不是管水的官。", "水光": "guāng 与 guān 韵母不同（ang 与 an），意思是水面反射的光。", "税关": "shuì（第四声）与 shuǐ 声调不同，意思是海关，即收税的关卡。"}, "sentence_index": null, "correct_answer": "水官"}, "level_3": {"options": [{"text": "水官", "is_correct": true, "explanation": "正确。句中指由专门的人负责监督执行的管理者。"}, {"text": "水神", "is_correct": false, "explanation": "语义：水神是神灵，不是由人担任、负责监督执行的管理者。"}, {"text": "水手", "is_correct": false, "explanation": "语义：水手是船上干活的人，不是负责监督执行水权的管理者。"}, {"text": "河伯", "is_correct": false, "explanation": "语义：河伯是传说中的河神，不是可以担任管理者、监督执行的人。"}], "explanations": {"水官": "正确。句中指由专门的人负责监督执行的管理者。", "水神": "语义：水神是神灵，不是由人担任、负责监督执行的管理者。", "水手": "语义：水手是船上干活的人，不是负责监督执行水权的管理者。", "河伯": "语义：河伯是传说中的河神，不是可以担任管理者、监督执行的人。"}, "sentence_index": 0, "correct_answer": "水官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在小区当水官，每天帮居民修理坏了的水管。", "explanation": "这里应该用〈水管工〉。“水官”是古代负责治水、管理河道的官职，不能用来称呼现代修水管的工人。"}, {"text": "他在公司当水官，专门负责给员工订购桶装水。", "explanation": "这里应该用〈采购员〉。“水官”专指古代管水利的官职，不能用来称呼现代公司里负责订水的人。"}, {"text": "这位水官负责管理全县的治安和税收。", "explanation": "这里应该用〈县令〉。水官只负责水利和治水，不管治安和税收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水官", "is_correct": true, "explanation": "正确。“告诉大家”需要能说话的人或机构作主语，水官符合。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是无生命的设施，不能主动“告诉大家”。"}, {"text": "河道", "is_correct": false, "explanation": "配价：“告诉大家”需要有施事者，河道不能担任施事。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能主动“告诉大家”。"}], "explanations": {"水官": "正确。“告诉大家”需要能说话的人或机构作主语，水官符合。", "水库": "语义：水库是无生命的设施，不能主动“告诉大家”。", "河道": "配价：“告诉大家”需要有施事者，河道不能担任施事。", "水果": "语义：水果是食物，不能主动“告诉大家”。"}, "sentence_index": 6, "correct_answer": "水官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐在医院当水官，每天给病人量体温。", "explanation": "这里应该用〈护士〉。“水官”指古代负责治水的官职，不能用来称呼现代医院里的护士。"}, {"text": "这台抽水机就是我们村的水官，每天自动工作。", "explanation": "这里应该用〈机器〉之类的名称。“水官”指古代治水的官员，是人，不能用来称呼抽水机这类器械。"}, {"text": "班里的水官是小明，他每天负责给大家倒水。", "explanation": "这里应该用〈班长〉之类的职务名。“水官”特指古代管水、管河的官职，不用于班级里的职务称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古代有一只水官，专门负责治理黄河。", "corrected_sentence": "古代有一位水官，专门负责治理黄河。", "error_description": "量词错误：“水官”指人，应用量词“位”，不能用“只”（“只”多用于动物或小物件）。错误只在量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做水官人，要了解河道的情况。", "corrected_sentence": "做水官的人，要了解河道的情况。", "error_description": "漏掉定语标志“的”：“做水官”修饰“人”时，中间须加“的”，即“做水官的人”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
