INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指将原本非商业性的领域或活动，转变为按照市场规律进行运作和交换的过程。", "primary_collocate": null, "pronunciation": "shì chǎng huà", "ipa": "ʂɻ̩˥˩ tʂʰɑŋ˨˩˦ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这种对水资源的社会调控机制，本质上是一种非市场化的治理模式，其合法性源于共同体内部的文化共识，而非现代法律条文。", "target_word": "市场化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个国家的医疗市场化进行得很慢。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住房市场化改变了许多城市家庭的生活。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育的完全市场化，很多专家并不支持。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农产品价格的市场化提高了农民的收入。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电力市场化改革需要很长时间。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场化的程度越高，价格越由供求决定。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究中国经济市场化的历史。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共服务的市场化引起了很多讨论。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行利率市场化后，储户有了更多选择。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非市场化", "label": "否定"}, {"form": "市场化改革", "label": "复合"}, {"form": "市場化", "label": "繁体"}], "register": "正式", "sense_fingerprint": "市场化|名词|非商业领域转为按市场规律运作和交换的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市场化", "is_correct": true, "explanation": "正确。“非市场化的治理模式”指不以市场规律运作的模式，符合句意。"}, {"text": "本土化", "is_correct": false, "explanation": "语义：“非本土化”指不依本地方式，与“合法性源于共同体内部的文化共识”相矛盾。"}, {"text": "民间化", "is_correct": false, "explanation": "语义：“非民间化”指不由民间自发形成，与源于共同体文化共识的调控机制相矛盾。"}, {"text": "社区化", "is_correct": false, "explanation": "语义：“非社区化”指不由社区内部管理，与“共同体内部的文化共识”相矛盾。"}], "explanations": {"市场化": "正确。“非市场化的治理模式”指不以市场规律运作的模式，符合句意。", "本土化": "语义：“非本土化”指不依本地方式，与“合法性源于共同体内部的文化共识”相矛盾。", "民间化": "语义：“非民间化”指不由民间自发形成，与源于共同体文化共识的调控机制相矛盾。", "社区化": "语义：“非社区化”指不由社区内部管理，与“共同体内部的文化共识”相矛盾。"}, "sentence_index": 0, "correct_answer": "市场化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个星期天都去市场化买菜。", "explanation": "这里应该用〈市场〉。市场化是名词，指转变的过程，不指买菜的场所。"}, {"text": "这位同学的性格很市场化，总是讨价还价。", "explanation": "这里应该用〈精明〉。“市场化”指领域转向市场运作，不用来形容人的性格，形容人会算计应说〈精明〉。"}, {"text": "今天这种苹果的市场化是每斤十块钱。", "explanation": "这里应该用〈市场价〉。“市场化”指非商业领域转向市场运作的过程，不能用来表示价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市场化", "is_correct": true, "explanation": "正确。“市场化的程度越高”与“价格越由供求决定”前后呼应。"}, {"text": "国有化", "is_correct": false, "explanation": "语义：“国有化”指收归国家所有，与“价格由供求决定”的说法相矛盾。"}, {"text": "行政化", "is_correct": false, "explanation": "搭配：“行政化的程度越高”时，价格应由行政决定，不能说“由供求决定”。"}, {"text": "垄断化", "is_correct": false, "explanation": "语义：垄断化程度越高，价格越由垄断者决定，与“由供求决定”相矛盾。"}], "explanations": {"市场化": "正确。“市场化的程度越高”与“价格越由供求决定”前后呼应。", "国有化": "语义：“国有化”指收归国家所有，与“价格由供求决定”的说法相矛盾。", "行政化": "搭配：“行政化的程度越高”时，价格应由行政决定，不能说“由供求决定”。", "垄断化": "语义：垄断化程度越高，价格越由垄断者决定，与“由供求决定”相矛盾。"}, "sentence_index": 6, "correct_answer": "市场化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的市场化让人们可以自由地出国旅游。", "explanation": "这里应该用〈自由化〉。市场化指非商业领域转向按市场规律运作，与出国自由无关。"}, {"text": "这间屋子的市场化很干净。", "explanation": "这里的“市场化”指经济领域的转变，不用来形容屋子的清洁程度，形容屋子应说〈整洁〉。"}, {"text": "这次考试的市场化让大家很紧张。", "explanation": "这里应该用〈改革〉。“市场化”指非商业领域转向市场运作的过程，用来说一次具体的考试并不通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在推进医疗市场化的。", "corrected_sentence": "政府正在推进医疗市场化。", "error_description": "“的”多余：“推进医疗市场化”是动宾结构，句末的“的”没有所指，应去掉，说“政府正在推进医疗市场化。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个行业的市场化很高。", "corrected_sentence": "这个行业的市场化程度很高。", "error_description": "“市场化”是一个过程，本身不能用“高”来形容；表示深浅应说“市场化程度很高”。正确形式为“市场化程度很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
