INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12835, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指符合法律、规则或道德规范的性质或状态。", "primary_collocate": null, "pronunciation": "hé fǎ xìng", "ipa": "xɤ˧˥ fa˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种对水资源的社会调控机制，本质上是一种非市场化的治理模式，其合法性源于共同体内部的文化共识，而非现代法律条文。", "target_word": "合法性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "律师先检查了这份合同的合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法的合法性，法院还要再研究。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项措施的合法性必须经过严格审查。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂没有执照，经营缺少合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定让网约车有了合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者调查了拍卖会的合法性问题。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买卖野生动物没有任何合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要证明这笔钱来源的合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律专家认为这项决定的合法性没有问题。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合法性危机", "label": "复合"}, {"form": "合法性问题", "label": "复合"}], "register": "正式", "sense_fingerprint": "合法性|名词|符合法律、规则或道德规范的性质或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合法性", "is_correct": true, "explanation": "正确：“合法性”指符合法律规范的性质，与“现代法律条文”形成对照，句意相合。"}, {"text": "时效性", "is_correct": false, "explanation": "语义：“时效性”指有效的时间限制，与“源于共同体内部的文化共识”的来源说法不合。"}, {"text": "市场性", "is_correct": false, "explanation": "语义：前文已说“非市场化”，填入“市场性”会与之矛盾。"}, {"text": "营利性", "is_correct": false, "explanation": "搭配：“营利性”说以盈利为目的，不能说治理模式的“营利性”源于文化共识。"}], "explanations": {"合法性": "正确：“合法性”指符合法律规范的性质，与“现代法律条文”形成对照，句意相合。", "时效性": "语义：“时效性”指有效的时间限制，与“源于共同体内部的文化共识”的来源说法不合。", "市场性": "语义：前文已说“非市场化”，填入“市场性”会与之矛盾。", "营利性": "搭配：“营利性”说以盈利为目的，不能说治理模式的“营利性”源于文化共识。"}, "sentence_index": 0, "correct_answer": "合法性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项工程的合法性很快。", "explanation": "这里应该用〈进度〉。合法性说事情符合法律，工程推进的快慢要说进度。"}, {"text": "这份报纸的合法性很厚，我一个星期才读完。", "explanation": "这里应该用〈厚度〉。合法性说符合法律，报纸的厚薄要说厚度。"}, {"text": "这个孩子的合法性很小。", "explanation": "这里应该用〈年龄〉。合法性说事情符合法律，说人的岁数要用年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合法性", "is_correct": true, "explanation": "正确：“拍卖会的合法性问题”指拍卖活动是否符合法律，句意相合。"}, {"text": "可塑性", "is_correct": false, "explanation": "语义：“可塑性”指能被塑造成形的性质，与调查拍卖活动不合。"}, {"text": "可读性", "is_correct": false, "explanation": "语义：“可读性”说文字易读，用在拍卖会上语义不通。"}, {"text": "腐蚀性", "is_correct": false, "explanation": "搭配：“腐蚀性”多指物质侵蚀事物，不能用来修饰拍卖会。"}], "explanations": {"合法性": "正确：“拍卖会的合法性问题”指拍卖活动是否符合法律，句意相合。", "可塑性": "语义：“可塑性”指能被塑造成形的性质，与调查拍卖活动不合。", "可读性": "语义：“可读性”说文字易读，用在拍卖会上语义不通。", "腐蚀性": "搭配：“腐蚀性”多指物质侵蚀事物，不能用来修饰拍卖会。"}, "sentence_index": 6, "correct_answer": "合法性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天外面的合法性很高，大家都穿短袖。", "explanation": "这里应该用〈温度〉。合法性说事情符合法律，天气冷热要说温度。"}, {"text": "这座桥的合法性很长，大家每天都要过。", "explanation": "这里应该用〈长度〉。合法性说符合法律，桥的长短要说长度。"}, {"text": "这个学校有很多合法性。", "explanation": "这里应该用〈规矩〉。合法性是抽象的性质，不能说“很多”；学校的规章要说规矩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项决定的一个合法性很清楚。", "corrected_sentence": "这项决定的合法性很清楚。", "error_description": "量词错误：“合法性”是抽象名词，不能用“个”计量；应去掉“一个”，说“这项决定的合法性很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他合法性很快就得到了认可。", "corrected_sentence": "他的合法性很快就得到了认可。", "error_description": "应为“他的合法性”。“他”修饰“合法性”时要加“的”，漏掉后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
