INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一群共享文化、历史和价值观的人所组成的群体", "primary_collocate": null, "pronunciation": "gòng tóng tǐ", "ipa": "kʊŋ˥˩ tʰʊŋ˧˥ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "这种对水资源的社会调控机制，本质上是一种非市场化的治理模式，其合法性源于共同体内部的文化共识，而非现代法律条文。", "target_word": "共同体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个共同体有自己的语言和历史。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个共同体的人，往往有相似的价值观。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给共同体里的年轻人讲祖先的故事。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛上的共同体保留着古老的习俗。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小生活在一个重视传统的共同体里。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同体的文化需要一代一代传下去。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "移民常常会组成自己的文化共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共同体的节日，外人很少了解。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共同的历史让他们成为一个共同体。", "target_word": "共同体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "文化共同体", "label": "复合"}, {"form": "共同體", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "共享文化、历史和价值观的群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305dd323-afa7-44a8-b982-43b80d121d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共同体", "is_correct": true, "explanation": "正确：“源于共同体内部的文化共识”指人群内部共享文化的群体，与“内部的文化共识”相符。"}, {"text": "法律", "is_correct": false, "explanation": "语义：前文说合法性源于内部文化共识，而非法律条文，不能说“源于法律内部的文化共识”。"}, {"text": "市场", "is_correct": false, "explanation": "语义：前文说这一机制是“非市场化”的，不能说合法性源于市场。"}, {"text": "货币", "is_correct": false, "explanation": "搭配：“内部的文化共识”指人群内部的文化认同，“货币”不能有内部的文化共识。"}], "explanations": {"共同体": "正确：“源于共同体内部的文化共识”指人群内部共享文化的群体，与“内部的文化共识”相符。", "法律": "语义：前文说合法性源于内部文化共识，而非法律条文，不能说“源于法律内部的文化共识”。", "市场": "语义：前文说这一机制是“非市场化”的，不能说合法性源于市场。", "货币": "搭配：“内部的文化共识”指人群内部的文化认同，“货币”不能有内部的文化共识。"}, "sentence_index": 0, "correct_answer": "共同体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种共同体已经流传了千年，村里人都很重视。", "explanation": "这里应该用〈风俗〉。风俗可以流传，共同体指人的集体，不能说流传。"}, {"text": "见面时大家要行这个共同体。", "explanation": "这里应该用〈礼仪〉。礼仪可以行，共同体不能被施行。"}, {"text": "村里的老人都会唱这种共同体。", "explanation": "这里应该用〈民歌〉。民歌可以唱，共同体指人的集体，不能被唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同体", "is_correct": true, "explanation": "正确：“共同体的文化”指共享文化的群体的文化，能够一代一代传下去。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有文化，不能说它的文化需要一代一代传下去。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器是无生命的器物，不是人群，不能说它的文化需要一代代传下去。"}, {"text": "伤口", "is_correct": false, "explanation": "搭配：“文化”与“伤口”不搭配，伤口不能有文化，也不能被传下去。"}], "explanations": {"共同体": "正确：“共同体的文化”指共享文化的群体的文化，能够一代一代传下去。", "石头": "语义：石头没有文化，不能说它的文化需要一代一代传下去。", "机器": "语义：机器是无生命的器物，不是人群，不能说它的文化需要一代代传下去。", "伤口": "搭配：“文化”与“伤口”不搭配，伤口不能有文化，也不能被传下去。"}, "sentence_index": 6, "correct_answer": "共同体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个共同体的电池很耐用。", "explanation": "这里应该用〈手机〉。手机有电池，共同体指人的集体，没有电池，不能说耐用。"}, {"text": "这个共同体的重量是五公斤。", "explanation": "这里应该用〈包裹〉。包裹有重量，共同体指人的集体，不能用重量来描述。"}, {"text": "这个共同体有十个抽屉，都装满了东西。", "explanation": "这里应该用〈柜子〉。柜子有抽屉，共同体指人的集体，没有抽屉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些移民结了一个文化共同体。", "corrected_sentence": "这些移民结成了一个文化共同体。", "error_description": "错误在「结」。「结」单用后接「一个文化共同体」这类表示群体的宾语很不自然，应说「结成」。「结成」是复合动词，可以接「一个文化共同体」作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些村民形了成一个古老的共同体。", "corrected_sentence": "这些村民形成了一个古老的共同体。", "error_description": "错误在“了”的位置。“形成”是一个词，“了”应放在整个词之后，应说“形成了”，不能拆成“形了成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
