INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12838, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律中具体规定的条款，是法律文件的基本组成部分。", "primary_collocate": null, "pronunciation": "fǎ lǜ tiáo wén", "ipa": "fa˨˩˦ ly˥˩ tʰjɑʊ˧˥ wən˧˥", "syllable_count": 4, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "法律条文", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种对水资源的社会调控机制，本质上是一种非市场化的治理模式，其合法性源于共同体内部的文化共识，而非现代法律条文。", "target_word": "法律条文", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "律师仔细读了这条法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律条文必须写得清楚明白。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条法律条文规定，开车不能打电话。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上学习了新的法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂法律条文，所以去问律师。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官按照法律条文做出了决定。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新的法律条文从下个月开始执行。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "法律條文", "label": "繁体"}], "register": "正式", "sense_fingerprint": "法律文件中具体规定的条款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐谱", "is_correct": false, "explanation": "语义：“乐谱”是记录音乐的符号，不能作为在听证会上提出反对意见的依据。"}, {"text": "法律条文", "is_correct": true, "explanation": "“法律条文”指法律中具体规定的条款，可以作为反对意见的依据，与句意相符。"}, {"text": "食谱", "is_correct": false, "explanation": "搭配：“依据……与……”后应接数据、条文等可作凭证的材料，“食谱”不能与“生态数据”并列作依据。"}, {"text": "童话", "is_correct": false, "explanation": "语义：“童话”是虚构的故事，不能作为听证会上有理有据的依据。"}], "explanations": {"乐谱": "语义：“乐谱”是记录音乐的符号，不能作为在听证会上提出反对意见的依据。", "法律条文": "“法律条文”指法律中具体规定的条款，可以作为反对意见的依据，与句意相符。", "食谱": "搭配：“依据……与……”后应接数据、条文等可作凭证的材料，“食谱”不能与“生态数据”并列作依据。", "童话": "语义：“童话”是虚构的故事，不能作为听证会上有理有据的依据。"}, "sentence_index": 0, "correct_answer": "法律条文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学的是法律条文专业。", "explanation": "这里应该用〈法学〉。学科名称是“法学”或“法律专业”，“法律条文”只是法律中的具体规定，不能作为专业。"}, {"text": "他们签订了法律条文。", "explanation": "这里应该用〈合同〉。签订的是合同、协议，法律条文是法律中的条款，不能签订。"}, {"text": "法院作出了法律条文。", "explanation": "这里应该用〈判决〉。法院作出的是判决，法律条文是被引用、遵守的规定，不能“作出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：律师不处理天气问题，“不懂天气，所以去问律师”不合逻辑。"}, {"text": "法律条文", "is_correct": true, "explanation": "“法律条文”是法律的条款，不懂时去问律师，与句意相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图与法律无关，律师不会解答地图方面的问题。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“不懂”多接知识或道理，“饭”不是需要去理解的知识，搭配不通。"}], "explanations": {"天气": "语义：律师不处理天气问题，“不懂天气，所以去问律师”不合逻辑。", "法律条文": "“法律条文”是法律的条款，不懂时去问律师，与句意相符。", "地图": "语义：地图与法律无关，律师不会解答地图方面的问题。", "饭": "搭配：“不懂”多接知识或道理，“饭”不是需要去理解的知识，搭配不通。"}, "sentence_index": 6, "correct_answer": "法律条文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座法律条文刚刚通过。", "explanation": "这里应该用〈条〉。“座”用于山、桥、楼等大型固定物，法律条文应用“条”。"}, {"text": "一把法律条文需要认真读。", "explanation": "这里应该用〈条〉。“把”用于有柄或可以握住的东西，法律条文应用“条”。"}, {"text": "这幅法律条文很长，我看不完。", "explanation": "这里应该用〈条〉。“幅”用于字画、图画，法律条文应用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官逐条解释了这些法律条文们。", "corrected_sentence": "法官逐条解释了这些法律条文。", "error_description": "后缀错误：“们”只用于指人，“法律条文”是事物，后面不能加“们”，应说“这些法律条文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他反复阅读了三法律条文。", "corrected_sentence": "他反复阅读了三条法律条文。", "error_description": "缺少量词：数词“三”和名词“法律条文”之间要加量词“条”，应说“三条法律条文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
