INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "纽带指起联系作用的人或事物，像一条带子把双方连接起来。", "primary_collocate": null, "pronunciation": "niǔ dài", "ipa": "njoʊ̯˨˩˦ taɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "农民、学生、手工业者在共同劳作中重建了濒临瓦解的邻里纽带，形成了非正式但高效的合作网络。", "target_word": "纽带", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "由此，水资源不仅是物质供给的载体，更是社会关系与文化认同的纽带。", "target_word": "纽带", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "音乐是我们之间的纽带。", "target_word": "纽带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "共同的语言成了两国人民的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子是这个家庭最重要的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是两个村子之间的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲情是父母和孩子之间的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球成为连接不同国家球迷的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信成了我和故乡之间的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日让大家重新建立了亲人之间的纽带。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条纽带", "label": "量词"}, {"form": "情感纽带", "label": "复合"}, {"form": "紐帶", "label": "繁体"}], "register": "书面", "sense_fingerprint": "起联系作用的人或事物；感情、文化、社会关系上的连接", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31956932-1185-4de5-add8-d2c55acac8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纽带", "is_correct": true, "explanation": "纽带指起联系作用的人或事物，放在「重建了濒临瓦解的邻里……」中，与「形成合作网络」的语境一致，是本句的正确答案。"}, {"text": "坟墓", "is_correct": false, "explanation": "语义：坟墓指埋葬死者的地方，与「重建」「形成合作网络」的积极语境相悖。"}, {"text": "伤口", "is_correct": false, "explanation": "搭配：伤口可以愈合，但不说「重建伤口」，与「邻里」也无法构成合理的搭配。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，谈不上「濒临瓦解」后被「重建」，也不能表示邻里之间的联系。"}], "explanations": {"纽带": "纽带指起联系作用的人或事物，放在「重建了濒临瓦解的邻里……」中，与「形成合作网络」的语境一致，是本句的正确答案。", "坟墓": "语义：坟墓指埋葬死者的地方，与「重建」「形成合作网络」的积极语境相悖。", "伤口": "搭配：伤口可以愈合，但不说「重建伤口」，与「邻里」也无法构成合理的搭配。", "雨伞": "语义：雨伞是日用品，谈不上「濒临瓦解」后被「重建」，也不能表示邻里之间的联系。"}, "sentence_index": 0, "correct_answer": "纽带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间的纽带用铁锹挖深了。", "explanation": "这里应该用〈沟〉。挖深的是沟；纽带是起联系作用的人或事物，不能用铁锹挖。"}, {"text": "这条纽带照出了他的样子。", "explanation": "这里应该用〈镜子〉。镜子能照出人的样子，纽带指起联系作用的人或事物，不能「照出」样子。"}, {"text": "纽带把两座山削平了。", "explanation": "这里应该用〈推土机〉。削平山的是机器；纽带是起联系作用的人或事物，不能削平山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纽带", "is_correct": true, "explanation": "纽带指起联系作用的人或事物，与「亲情是父母和孩子之间的……」的语义吻合，是本句的正确答案。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是用来隔开的，与「亲情」所表达的紧密联系相反，不能放在「父母和孩子之间」。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能作为父母与孩子之间的联系。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时用具，不能作为父母与孩子之间的联系。"}], "explanations": {"纽带": "纽带指起联系作用的人或事物，与「亲情是父母和孩子之间的……」的语义吻合，是本句的正确答案。", "墙": "语义：墙是用来隔开的，与「亲情」所表达的紧密联系相反，不能放在「父母和孩子之间」。", "饼干": "语义：饼干是食物，不能作为父母与孩子之间的联系。", "闹钟": "语义：闹钟是计时用具，不能作为父母与孩子之间的联系。"}, "sentence_index": 6, "correct_answer": "纽带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师为我们指明了前进的纽带。", "explanation": "这里应该用〈方向〉。「指明」指出的是方向、道路，纽带指起联系作用的人或事物，不能「指明」前进的纽带。"}, {"text": "这排高大的树木是抵御寒风的纽带。", "explanation": "这里应该用〈屏障〉。屏障指阻挡、防护，纽带指起联系作用，两者作用相反，纽带不能抵御寒风。"}, {"text": "这辆自行车的纽带很灵敏。", "explanation": "这里应该用〈刹车〉。刹车是制动装置，「灵敏」形容的是它的反应；纽带指起联系作用的人或事物，不能说「很灵敏」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是团队里的一只纽带。", "corrected_sentence": "他是团队里的一条纽带。", "error_description": "量词错误：纽带应用「条」，「只」多用于动物或成对物品中的一个，不能用于纽带。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那段共同的经历，是我们之间的纽带们。", "corrected_sentence": "那段共同的经历，是我们之间的纽带。", "error_description": "“们”只能加在指人的名词之后。纽带是抽象事物，应说“纽带”，不说“纽带们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
