INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因为具有价值或优点而被给予某种认可", "primary_collocate": null, "pronunciation": "huò dé", "ipa": "xu̯ɔ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "它们之所以获得如此地位，不仅因其历史价值，更因其在当代气候危机背景下的适应性潜力。", "target_word": "获得", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影获得了很多好评。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画获得了第一名。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品获得大家的认可。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆获得了客人的喜爱。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书获得了一个大奖。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明因为帮助别人，获得了老师的表扬。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人获得了大家的尊重。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的歌获得了很高的评价。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司的产品获得过好几个奖。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲得", "label": "繁体"}, {"form": "获得了", "label": "体标"}, {"form": "获得过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "因价值或优点而得到认可、荣誉或好评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确答案。获得（huò dé）：因具有价值或优点而得到认可。"}, {"text": "活得", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活着、过日子，如“活得很好”。"}, {"text": "活的", "is_correct": false, "explanation": "huó 与 huò 声调不同，de（轻声）与 dé 声调不同，意思是有生命的。"}, {"text": "豁得", "is_correct": false, "explanation": "huō（第一声）与 huò（第四声）声调不同，意思是豁出去、舍得，如“豁得出去”。"}], "explanations": {"获得": "正确答案。获得（huò dé）：因具有价值或优点而得到认可。", "活得": "huó（第二声）与 huò（第四声）声调不同，意思是活着、过日子，如“活得很好”。", "活的": "huó 与 huò 声调不同，de（轻声）与 dé 声调不同，意思是有生命的。", "豁得": "huō（第一声）与 huò（第四声）声调不同，意思是豁出去、舍得，如“豁得出去”。"}, "sentence_index": null, "correct_answer": "获得"}, "level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "“获得”表示因价值得到认可，此处指它们因历史价值与适应性潜力而获得如此地位。"}, {"text": "丧失", "is_correct": false, "explanation": "语义：“丧失”是失去，与“不仅因其历史价值，更因其……潜力”的正面语境相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是主动舍去，与句中列举的正面原因不合。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：“驱赶”的对象是人或动物，不能说“驱赶地位”。"}], "explanations": {"获得": "“获得”表示因价值得到认可，此处指它们因历史价值与适应性潜力而获得如此地位。", "丧失": "语义：“丧失”是失去，与“不仅因其历史价值，更因其……潜力”的正面语境相反。", "放弃": "语义：“放弃”是主动舍去，与句中列举的正面原因不合。", "驱赶": "搭配：“驱赶”的对象是人或动物，不能说“驱赶地位”。"}, "sentence_index": 0, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的作品获得了一阵大风。", "explanation": "这里应该用〈刮起〉。“获得”用于荣誉、认可等，风不能被获得，应说“刮起一阵大风”。"}, {"text": "这家饭馆获得了一场火灾。", "explanation": "这里应该用〈发生〉。“获得”用于荣誉、认可等，火灾不能被获得，应说“饭馆发生了一场火灾”。"}, {"text": "她的画获得了一层灰尘。", "explanation": "这里应该用〈落满〉。“获得”用于荣誉、认可等，灰尘不是因价值得到的东西，应说“画上落满了灰尘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12842, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确答案。获得（huò dé）：因具有价值或优点而得到认可。"}, {"text": "过得", "is_correct": false, "explanation": "guò（第四声）与 huò 的声母不同（g 与 h），意思是过日子，如“过得很好”。"}, {"text": "握得", "is_correct": false, "explanation": "wò（第四声）与 huò 的声母不同（w 与 h），意思是握，如“握得很紧”。"}, {"text": "扩得", "is_correct": false, "explanation": "kuò（第四声）与 huò 的声母不同（k 与 h），意思是扩大，如“扩得很大”。"}], "explanations": {"获得": "正确答案。获得（huò dé）：因具有价值或优点而得到认可。", "过得": "guò（第四声）与 huò 的声母不同（g 与 h），意思是过日子，如“过得很好”。", "握得": "wò（第四声）与 huò 的声母不同（w 与 h），意思是握，如“握得很紧”。", "扩得": "kuò（第四声）与 huò 的声母不同（k 与 h），意思是扩大，如“扩得很大”。"}, "sentence_index": null, "correct_answer": "获得"}, "level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "“获得”表示得到，此处指小明因帮助别人而得到老师的表扬。"}, {"text": "遭受", "is_correct": false, "explanation": "搭配：“遭受”多接伤害、损失，不接表扬。"}, {"text": "招致", "is_correct": false, "explanation": "语义：“招致”带贬义，与“表扬”的正面语境不合。"}, {"text": "承受", "is_correct": false, "explanation": "搭配：“承受”用于压力、打击，不能接表扬。"}], "explanations": {"获得": "“获得”表示得到，此处指小明因帮助别人而得到老师的表扬。", "遭受": "搭配：“遭受”多接伤害、损失，不接表扬。", "招致": "语义：“招致”带贬义，与“表扬”的正面语境不合。", "承受": "搭配：“承受”用于压力、打击，不能接表扬。"}, "sentence_index": 6, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书获得了很多错别字。", "explanation": "这里应该用〈出现〉。“获得”用于荣誉、好评等正面对象，错别字不能被获得，应说“书里出现了很多错别字”。"}, {"text": "他的球队获得了一次失败。", "explanation": "这里应该用〈遭受〉。“获得”用于荣誉、认可等正面对象，“失败”是负面结果，应说“遭受失败”。"}, {"text": "学校获得了一场考试。", "explanation": "这里应该用〈举行〉。“获得”的对象是荣誉、认可等，考试是活动，应说“学校举行一场考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家的小说被获得了读者的喜爱。", "corrected_sentence": "这位作家的小说获得了读者的喜爱。", "error_description": "“被”字句的主语是受事，而此处“小说”是获得者，不能加“被”。应去掉“被”，说“小说获得了读者的喜爱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的合唱获得着学校的一等奖。", "corrected_sentence": "我们班的合唱获得了学校的一等奖。", "error_description": "“获得”表示已完成的结果，不能加“着”。此处应说“获得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
