INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12844, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生物体或系统随着环境变化而调整自身状态，以更好地生存或发挥功能的能力。", "primary_collocate": null, "pronunciation": "shì yìng xìng", "ipa": "ʂɻ̩˥˩ iŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "它们之所以获得如此地位，不仅因其历史价值，更因其在当代气候危机背景下的适应性潜力。", "target_word": "适应性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种植物的适应性很强，在沙漠里也能活。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的适应性帮助它们度过了冬天。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种鱼的适应性。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境变化太快，物种的适应性跟不上。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新型作物对干旱的适应性很高。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的适应性决定了它能不能在变化中活下去。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠的适应性极强，城市里到处都有。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套灌溉系统的适应性好，能应对天气变化。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟的适应性让它在不同的气候中都能生存。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "适应性训练", "label": "复合"}, {"form": "適應性", "label": "繁体"}], "register": "正式", "sense_fingerprint": "适应性|名词|生物或系统随环境变化调整自身以生存或发挥功能的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适应性", "is_correct": true, "explanation": "正确：“适应性”指生物或系统随环境调整的能力，与“气候危机背景下”的语境相合。"}, {"text": "挥发性", "is_correct": false, "explanation": "语义：“挥发性”说物质容易散发，与物种应对气候变化的潜力无关。"}, {"text": "可读性", "is_correct": false, "explanation": "语义：“可读性”说文字易懂，用在物种的潜力上语义不通。"}, {"text": "延展性", "is_correct": false, "explanation": "搭配：“延展性”指材料能拉长，不能说“延展性潜力”来修饰物种的生存能力。"}], "explanations": {"适应性": "正确：“适应性”指生物或系统随环境调整的能力，与“气候危机背景下”的语境相合。", "挥发性": "语义：“挥发性”说物质容易散发，与物种应对气候变化的潜力无关。", "可读性": "语义：“可读性”说文字易懂，用在物种的潜力上语义不通。", "延展性": "搭配：“延展性”指材料能拉长，不能说“延展性潜力”来修饰物种的生存能力。"}, "sentence_index": 0, "correct_answer": "适应性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的适应性很快，半小时就到了。", "explanation": "这里应该用〈速度〉。适应性指生物或系统适应环境的能力，车的快慢要说速度。"}, {"text": "这件衣服的适应性很贵。", "explanation": "这里应该用〈价格〉。适应性指生物或系统适应环境的能力，衣服值多少钱要说价格。"}, {"text": "这条鱼的适应性是红色的，非常好看。", "explanation": "这里应该用〈颜色〉。适应性指适应环境的能力，鱼身上的红、蓝要说颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适应性", "is_correct": true, "explanation": "正确：“公司的适应性决定了它能不能在变化中活下去”指公司适应环境变化的能力，句意相合。"}, {"text": "熔点", "is_correct": false, "explanation": "语义：“熔点”指物质熔化的温度，用于公司的生存能力上语义不通。"}, {"text": "导电性", "is_correct": false, "explanation": "语义：“导电性”指导体传电的性质，与公司应对变化无关。"}, {"text": "放射性", "is_correct": false, "explanation": "搭配：“放射性”多指物质辐射，不能用来形容公司。"}], "explanations": {"适应性": "正确：“公司的适应性决定了它能不能在变化中活下去”指公司适应环境变化的能力，句意相合。", "熔点": "语义：“熔点”指物质熔化的温度，用于公司的生存能力上语义不通。", "导电性": "语义：“导电性”指导体传电的性质，与公司应对变化无关。", "放射性": "搭配：“放射性”多指物质辐射，不能用来形容公司。"}, "sentence_index": 6, "correct_answer": "适应性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的适应性很亮，把房间照得一清二楚。", "explanation": "这里应该用〈亮度〉。适应性指适应环境的能力，灯的明暗要说亮度。"}, {"text": "这只鸟的适应性很轻。", "explanation": "这里应该用〈重量〉。适应性指生物或系统适应环境的能力，鸟的轻重要说重量。"}, {"text": "这种鸟的适应性很长。", "explanation": "这里应该用〈寿命〉。适应性指适应环境的能力，动物能活多久要说寿命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种植物的一只适应性很强，能在沙漠里生长。", "corrected_sentence": "这种植物的适应性很强，能在沙漠里生长。", "error_description": "多加了量词“一只”。“只”用于动物个体，“适应性”是抽象名词，不能说“一只适应性”。应为“这种植物的适应性很强”，去掉多余的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟得适应性很强，能在寒冷的地方生活。", "corrected_sentence": "这种鸟的适应性很强，能在寒冷的地方生活。", "error_description": "“的”误用成“得”。应为“这种鸟的适应性”，“的”连接定语和中心语“适应性”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
