INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从大气中降落到地面的液态或固态水，如雨、雪、冰雹等。", "primary_collocate": null, "pronunciation": "jiàng shuǐ", "ipa": "tɕjɑŋ⁵¹ ʂweɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "面对全球变暖加剧、降水模式日益不稳定的现实，现代水资源管理正面临前所未有的挑战。", "target_word": "降水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个地区夏季降水很多。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年春天降水比去年少。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的降水主要集中在夏天。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台说明天有降水。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降水少的地方，河水也少。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天北方的降水多是雪。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "连续的降水让河水涨高了。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠地区全年几乎没有降水。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季降水不足，农民很担心。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降水量", "label": "复合"}, {"form": "人工降水", "label": "复合"}], "register": "书面", "sense_fingerprint": "大气中落到地面的雨雪冰雹等水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "正确：“降水模式”指降水的变化规律，与全球变暖、水资源管理的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色模式”与全球变暖、水资源管理的语境不符，句子不通。"}, {"text": "货币", "is_correct": false, "explanation": "语义：“货币模式”与气候变化、水资源的语境不符，句子不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能用来描述气候与水资源的变化模式，搭配不当。"}], "explanations": {"降水": "正确：“降水模式”指降水的变化规律，与全球变暖、水资源管理的语境相符。", "颜色": "语义：“颜色模式”与全球变暖、水资源管理的语境不符，句子不通。", "货币": "语义：“货币模式”与气候变化、水资源的语境不符，句子不通。", "味道": "搭配：“味道”不能用来描述气候与水资源的变化模式，搭配不当。"}, "sentence_index": 0, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机在跑道上降水很平稳。", "explanation": "这里应该用〈降落〉。“降水”指雨雪从天上落下，飞机着陆要说“降落”。"}, {"text": "妈妈给孩子降水了一碗汤。", "explanation": "这里应该用〈盛〉。“降水”指雨雪从天而降，不能表示盛汤，应说“盛了一碗汤”。"}, {"text": "夜幕降水了，街上的灯都亮了。", "explanation": "这里应该用〈降临〉。“降水”指雨雪落下，夜幕到来要说“降临”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
